export default Object.freeze({"en":{"copyLanguage":"en","name":"Bond Calculator","title":"Bond Calculator Free & Unlimited | UsefulVerse","description":"Estimate bond price or yield to maturity from coupon, face value and term. Free, unlimited calculations run locally in your browser.","intro":"Estimate a fixed-rate bond price from its yield, or solve an approximate yield to maturity from a quoted market price. Review the assumptions and price–yield curve before using the result.","howQuestion":"How do I calculate a bond price or yield to maturity?","howAnswer":"Enter the face value, annual coupon rate, years to maturity and coupon frequency. Choose price-from-yield to discount the scheduled coupon and principal payments, or choose yield-from-price to numerically solve the nominal annual yield that matches a market price.","privacyQuestion":"Are my bond inputs uploaded?","privacyAnswer":"No. The calculation runs in this browser. Inputs are not uploaded or saved by this tool.","howTo":["Choose whether to estimate a price from yield or solve yield from a market price.","Enter face value, annual coupon rate, maturity and coupon frequency.","Calculate and compare the result with the displayed assumptions and curve."],"example":{"label":"Load a 5% coupon bond priced at par","values":[]},"actions":{"calculate":"Calculate bond value","example":"Load par-bond example","reset":"Reset","copy":"Copy results","result":"Bond estimate"},"fields":{"mode":"Calculation mode","priceMode":"Price from a yield","yieldMode":"Yield from a market price","faceValue":"Face (par) value","couponPercent":"Annual coupon rate (%)","years":"Years to maturity","frequency":"Coupon payments per year","annual":"Annual (1)","semiannual":"Semiannual (2)","quarterly":"Quarterly (4)","monthly":"Monthly (12)","yieldPercent":"Nominal annual yield (%)","marketPrice":"Market price","accuracyNote":"Educational estimate only, not investment advice. Assumes fixed coupons paid at regular intervals, principal repaid at maturity, nominal annual yield compounded at the selected coupon frequency, and no accrued interest, taxes, fees, default, call features, inflation or reinvestment effects. Maturity must be a whole number of coupon periods. Yield is numerical and approximate; confirm bond terms and market conventions independently.","resultSummary":"Estimated bond results","yieldToMaturity":"Yield to maturity (nominal annual)","estimatedPrice":"Estimated price","couponPayment":"Coupon payment per period","currentYield":"Current yield","totalCoupons":"Total scheduled coupons","premiumDiscount":"Premium / discount to face value","periods":"Coupon periods","chartTitle":"Estimated price–yield curve","chartDescription":"Bond price generally moves in the opposite direction to yield. The curve uses the entered fixed coupon and maturity assumptions.","chartYield":"Nominal annual yield (%)","chartPrice":"Estimated price"},"messages":{"calculated":"Bond estimate calculated.","exampleLoaded":"Example loaded: 5% coupon, 5 years, annual payments, price at par.","checkInputs":"Check the bond values and try again.","copied":"Results copied.","copyUnavailable":"Copy is unavailable in this browser.","invalidPeriods":"Choose a maturity that contains a whole number of coupon periods (up to 1,200).","yieldOutOfRange":"The market price is outside the supported numerical yield range."},"additionalFaqs":[{"question":"What yield does a 5% coupon bond have when it is priced at par?","answer":"Under the calculator assumptions, a bond with a 5% annual coupon rate, a market price equal to face value and regular coupon payments has a nominal yield to maturity of 5%."},{"question":"Why do bond prices and yields move in opposite directions?","answer":"A bond price is the present value of its scheduled coupons and principal. A higher discount yield reduces that present value; a lower yield increases it."},{"question":"Is current yield the same as yield to maturity?","answer":"No. Current yield is the annual coupon divided by the current price. Yield to maturity also accounts for the price difference from face value and the time remaining, under the stated cash-flow assumptions."},{"question":"Does this estimate include accrued interest or taxes?","answer":"No. It models regular fixed coupon payments and principal repayment only. It does not calculate clean-versus-dirty price, accrued interest, taxes, fees, credit risk or optional redemption."}],"sources":[],"localizationStatus":"approved"},"es":{"copyLanguage":"es","name":"Calculadora de bonos","title":"Calculadora de bonos gratis | UsefulVerse","description":"Estimar el precio del bono o el rendimiento al vencimiento a partir del cupón, el valor nominal y el plazo. Cálculos gratuitos e ilimitados se ejecutan…","intro":"Estimar el precio de un bono de tasa fija a partir de su rendimiento, o resolver un rendimiento aproximado al vencimiento a partir de un precio de mercado cotizado. Revise los supuestos y la curva precio-rendimiento antes de utilizar el resultado.","howQuestion":"¿Cómo calculo el precio de un bono o el rendimiento al vencimiento?","howAnswer":"Ingrese el valor nominal, la tasa de cupón anual, los años hasta el vencimiento y la frecuencia del cupón. Elija precio-rendimiento para descontar el cupón programado y los pagos de principal, o elija rendimiento-precio para resolver numéricamente el rendimiento anual nominal que coincide con un precio de mercado.","privacyQuestion":"¿Se cargaron mis entradas de bonos?","privacyAnswer":"No. El cálculo se ejecuta en este navegador. Esta herramienta no carga ni guarda las entradas.","howTo":["Elija si desea estimar un precio a partir del rendimiento o resolver el rendimiento a partir de un precio de mercado.","Introduzca el valor nominal, la tasa de cupón anual, el vencimiento y la frecuencia del cupón.","Calcule y compare el resultado con las suposiciones y la curva mostradas."],"example":{"label":"Cargue un bono con cupón del 5% a la par","values":[]},"actions":{"calculate":"Calcular el valor del bono","example":"Ejemplo de carga par-bond","reset":"Restablecer","copy":"Copiar resultados","result":"Estimación de bonos"},"fields":{"mode":"Modo de cálculo","priceMode":"Precio a partir de un rendimiento","yieldMode":"Rendimiento a partir de un precio de mercado","faceValue":"Valor nominal (par)","couponPercent":"Tasa de cupón anual (%)","years":"Años hasta el vencimiento","frequency":"Pagos de cupones por año","annual":"Anual (1)","semiannual":"Semestral (2)","quarterly":"Trimestral (4)","monthly":"Mensual (12)","yieldPercent":"Rendimiento nominal anual (%)","marketPrice":"Precio de mercado","accuracyNote":"Estimación educativa únicamente, no asesoramiento de inversión. Supone cupones fijos pagados a intervalos regulares, principal reembolsado al vencimiento, rendimiento nominal anual compuesto con la frecuencia de cupón seleccionada y sin intereses, impuestos, tarifas, incumplimiento, características de compra, inflación o efectos de reinversión acumulados. El vencimiento debe ser un número entero de períodos de cupón. El rendimiento es numérico y aproximado; confirmar los términos de los bonos y las convenciones del mercado de forma independiente.","resultSummary":"Resultados estimados de bonos","yieldToMaturity":"Rendimiento al vencimiento (nominal anual)","estimatedPrice":"Precio estimado","couponPayment":"Pago de cupón por periodo","currentYield":"Rendimiento actual","totalCoupons":"Total de cupones programados","premiumDiscount":"Prima / descuento sobre el valor nominal","periods":"Períodos de cupón","chartTitle":"Curva precio-rendimiento estimado","chartDescription":"El precio de los bonos generalmente se mueve en la dirección opuesta al rendimiento. La curva utiliza los supuestos de vencimiento y cupón fijo ingresados.","chartYield":"Rendimiento nominal anual (%)","chartPrice":"Precio estimado"},"messages":{"calculated":"Estimación del bono calculada.","exampleLoaded":"Ejemplo cargado: cupón del 5%, 5 años, pagos anuales, precio a la par.","checkInputs":"Verifique los valores de enlace y vuelva a intentarlo.","copied":"Resultados copiados.","copyUnavailable":"La copia no está disponible en este navegador.","invalidPeriods":"Elija un vencimiento que contenga un número entero de períodos de cupón (hasta 1200).","yieldOutOfRange":"El precio de mercado está fuera del rango de rendimiento numérico admitido."},"additionalFaqs":[{"question":"¿Qué rendimiento tiene un bono con cupón del 5% cuando su precio es a la par?","answer":"Según los supuestos de la calculadora, un bono con una tasa de cupón anual del 5%, un precio de mercado igual al valor nominal y pagos regulares de cupones tiene un rendimiento nominal al vencimiento del 5%."},{"question":"¿Por qué los precios y los rendimientos de los bonos se mueven en direcciones opuestas?","answer":"El precio de un bono es el valor presente de sus cupones programados y su principal. Un mayor rendimiento del descuento reduce ese valor presente; un menor rendimiento lo aumenta."},{"question":"¿Es el rendimiento actual lo mismo que el rendimiento al vencimiento?","answer":"No. El rendimiento actual es el cupón anual dividido por el precio actual. El rendimiento al vencimiento también representa la diferencia de precio con respecto al valor nominal y el tiempo restante, según los supuestos de flujo de efectivo establecidos."},{"question":"¿Esta estimación incluye intereses o impuestos acumulados?","answer":"No. Modela pagos regulares de cupones fijos y reembolsos de principal únicamente. No calcula el precio limpio versus sucio, intereses acumulados, impuestos, tarifas, riesgo crediticio o canje opcional."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"fr":{"copyLanguage":"fr","name":"Calculateur d'obligations","title":"Calculateur d'obligations gratuit | UsefulVerse","description":"Estimation du prix ou du rendement d'une obligation à l'échéance à partir du coupon, de la valeur nominale et de la durée. Des calculs gratuits et illimités…","intro":"Estimez le prix d'une obligation à taux fixe à partir de son rendement, ou résolvez un rendement approximatif jusqu'à l'échéance à partir d'un prix de marché coté. Examinez les hypothèses et la courbe prix-rendement avant d’utiliser le résultat.","howQuestion":"Comment calculer le prix ou le rendement d'une obligation à l'échéance ?","howAnswer":"Entrez la valeur nominale, le taux du coupon annuel, les années jusqu'à l'échéance et la fréquence du coupon. Choisissez le prix à partir du rendement pour actualiser les paiements de coupon et de principal programmés, ou choisissez le rendement à partir du prix pour résoudre numériquement le rendement annuel nominal qui correspond à un prix de marché.","privacyQuestion":"Mes entrées d'obligations sont-elles téléchargées ?","privacyAnswer":"Non. Le calcul s'exécute dans ce navigateur. Les entrées ne sont ni téléchargées ni enregistrées par cet outil.","howTo":["Choisissez s'il faut estimer un prix à partir du rendement ou résoudre le rendement à partir d'un prix de marché.","Entrez la valeur nominale, le taux du coupon annuel, l'échéance et la fréquence du coupon.","Calculez et comparez le résultat avec les hypothèses et la courbe affichées."],"example":{"label":"Charger une obligation à coupon de 5 % au prix nominal","values":[]},"actions":{"calculate":"Calculer la valeur de l'obligation","example":"Exemple de chargement de par-bond","reset":"Réinitialiser","copy":"Copier les résultats","result":"Estimation de l'obligation"},"fields":{"mode":"Mode de calcul","priceMode":"Prix à partir d'un rendement","yieldMode":"Rendement à partir d’un prix de marché","faceValue":"Valeur nominale (par)","couponPercent":"Taux du coupon annuel (%)","years":"Années jusqu’à l’échéance","frequency":"Paiements de coupons par an","annual":"Annuel (1)","semiannual":"Semestriel (2)","quarterly":"Trimestriel (4)","monthly":"Mensuel (12)","yieldPercent":"Rendement annuel nominal (%)","marketPrice":"Prix du marché","accuracyNote":"Estimation éducative uniquement, pas de conseil en investissement. Suppose que des coupons fixes sont payés à intervalles réguliers, que le capital est remboursé à l'échéance, que le rendement annuel nominal est composé à la fréquence de coupon sélectionnée et qu'il n'y a pas d'intérêts, taxes, frais, défauts de paiement, caractéristiques d'achat, inflation ou effets de réinvestissement accumulés. L'échéance doit être un nombre entier de périodes de coupon. Le rendement est numérique et approximatif ; confirmer les conditions des obligations et les conventions de marché de manière indépendante.","resultSummary":"Résultats obligataires estimés","yieldToMaturity":"Rendement actuariel (annuel nominal)","estimatedPrice":"Prix estimé","couponPayment":"Paiement du coupon par période","currentYield":"Rendement actuel","totalCoupons":"Total des coupons programmés","premiumDiscount":"Prime / remise par rapport à la valeur nominale","periods":"Périodes de coupon","chartTitle":"Courbe prix-rendement estimée","chartDescription":"Le prix des obligations évolue généralement dans la direction opposée au rendement. La courbe utilise les hypothèses de coupon fixe et d'échéance saisies.","chartYield":"Rendement annuel nominal (%)","chartPrice":"Prix estimé"},"messages":{"calculated":"Estimation de l'obligation calculée.","exampleLoaded":"Exemple chargé : coupon de 5 %, 5 ans, versements annuels, prix au pair.","checkInputs":"Vérifiez les valeurs des liaisons et réessayez.","copied":"Résultats copiés.","copyUnavailable":"n'est pas disponible dans ce navigateur.","invalidPeriods":"Choisissez une échéance qui contient un nombre entier de périodes de coupons (jusqu'à 1 200).","yieldOutOfRange":"Le prix du marché se situe en dehors de la plage de rendement numérique prise en charge."},"additionalFaqs":[{"question":"Quel rendement offre une obligation à coupon de 5 % lorsqu'elle est évaluée au pair ?","answer":"Selon les hypothèses du calculateur, une obligation avec un taux de coupon annuel de 5 %, un prix de marché égal à la valeur nominale et des paiements de coupons réguliers a un rendement nominal jusqu'à l'échéance de 5 %."},{"question":"Pourquoi les prix et les rendements obligataires évoluent-ils dans des directions opposées ?","answer":"Le prix d'une obligation est la valeur actuelle de ses coupons programmés et de son principal. Un rendement d’escompte plus élevé réduit cette valeur actuelle ; un rendement inférieur l’augmente."},{"question":"Le rendement actuel est-il le même que le rendement à l'échéance ?","answer":"Non. Le rendement actuel est le coupon annuel divisé par le prix actuel. Le rendement à l'échéance tient également compte de la différence de prix par rapport à la valeur nominale et du temps restant, selon les hypothèses de flux de trésorerie énoncées."},{"question":"Cette estimation inclut-elle les intérêts ou les taxes courus ?","answer":"Non. Il modélise uniquement les paiements réguliers de coupons fixes et le remboursement du principal. Il ne calcule pas le prix propre ou sale, les intérêts courus, les taxes, les frais, le risque de crédit ou le rachat facultatif."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"pt":{"copyLanguage":"pt","name":"Bond Calculator","title":"Bond Calculator grátis | UsefulVerse","description":"Estime o preço ou rendimento do título até o vencimento a partir do cupom, valor de face e prazo. Cálculos gratuitos e ilimitados são executados localmente no…","intro":"Estime o preço de um título de taxa fixa a partir de seu rendimento ou resolva um rendimento aproximado até o vencimento a partir de um preço de mercado cotado. Revise as premissas e a curva preço-rendimento antes de usar o resultado.","howQuestion":"Como calculo o preço ou o rendimento de um título até o vencimento?","howAnswer":"Insira o valor nominal, a taxa de cupom anual, os anos até o vencimento e a frequência do cupom. Escolha o preço do rendimento para descontar o cupom programado e os pagamentos do principal, ou escolha o rendimento do preço para resolver numericamente o rendimento anual nominal que corresponde a um preço de mercado.","privacyQuestion":"Minhas entradas de títulos foram carregadas?","privacyAnswer":"Não. O cálculo é executado neste navegador. As entradas não são carregadas ou salvas por esta ferramenta.","howTo":["Escolha se deseja estimar um preço a partir do rendimento ou resolver o rendimento a partir de um preço de mercado.","Insira o valor nominal, a taxa de cupom anual, o vencimento e a frequência do cupom.","Calcule e compare o resultado com as suposições e curvas exibidas."],"example":{"label":"Carregar um título com cupom de 5% ao par","values":[]},"actions":{"calculate":"Calcular o valor do título","example":"Exemplo de carga par-bond","reset":"Redefinir","copy":"Copiar resultados","result":"Estimativa de títulos"},"fields":{"mode":"Modo de cálculo","priceMode":"Preço de um rendimento","yieldMode":"Rendimento a partir de um preço de mercado","faceValue":"Valor nominal (par)","couponPercent":"Taxa de cupom anual (%)","years":"Anos até o vencimento","frequency":"Pagamentos de cupom por ano","annual":"Anual (1)","semiannual":"Semestral (2)","quarterly":"Trimestralmente (4)","monthly":"Mensal (12)","yieldPercent":"Rendimento nominal anual (%)","marketPrice":"Preço de mercado","accuracyNote":"Apenas estimativa educacional, não consultoria de investimento. Assume cupons fixos pagos em intervalos regulares, principal reembolsado no vencimento, rendimento nominal anual composto na frequência de cupom selecionada e nenhum juro acumulado, impostos, taxas, inadimplência, recursos de chamada, inflação ou efeitos de reinvestimento. O vencimento deve ser um número inteiro de períodos de cupom. O rendimento é numérico e aproximado; confirmar os termos dos títulos e as convenções de mercado de forma independente.","resultSummary":"Resultados estimados de títulos","yieldToMaturity":"Rendimento até o vencimento (nominal anual)","estimatedPrice":"Preço estimado","couponPayment":"Pagamento de cupom por período","currentYield":"Rendimento atual","totalCoupons":"Total de cupons programados","premiumDiscount":"Prêmio / desconto no valor de face","periods":"Coupon periods","chartTitle":"Curva preço-rendimento estimada","chartDescription":"geralmente se move na direção oposta ao rendimento. A curva utiliza as premissas de cupom fixo e vencimento inseridas.","chartYield":"Rendimento nominal anual (%)","chartPrice":"Preço estimado"},"messages":{"calculated":"calculada.","exampleLoaded":"Exemplo carregado: cupom de 5%, 5 anos, pagamentos anuais, preço ao par.","checkInputs":"Verifique os valores dos títulos e tente novamente.","copied":"copiados.","copyUnavailable":"não está disponível neste navegador.","invalidPeriods":"Escolha um vencimento que contenha um número inteiro de períodos de cupom (até 1.200).","yieldOutOfRange":"O preço de mercado está fora da faixa de rendimento numérico suportada."},"additionalFaqs":[{"question":"Qual é o rendimento de um título com cupom de 5% quando seu preço é nominal?","answer":"De acordo com as premissas da calculadora, um título com taxa de cupom anual de 5%, preço de mercado igual ao valor de face e pagamentos regulares de cupom tem um rendimento nominal até o vencimento de 5%."},{"question":"Por que os preços e os rendimentos dos títulos se movem em direções opostas?","answer":"O preço de um título é o valor presente de seus cupons programados e principal. Um rendimento de desconto mais elevado reduz esse valor presente; um rendimento mais baixo aumenta-o."},{"question":"O rendimento atual é igual ao rendimento até o vencimento?","answer":"Não. O rendimento atual é o cupom anual dividido pelo preço atual. O rendimento até ao vencimento também contabiliza a diferença de preço em relação ao valor nominal e ao tempo restante, de acordo com os pressupostos de fluxo de caixa declarados."},{"question":"Esta estimativa inclui juros ou impostos acumulados?","answer":"Não. Ele modela apenas pagamentos regulares de cupom fixo e reembolso de principal. Não calcula preço limpo versus sujo, juros acumulados, impostos, taxas, risco de crédito ou resgate opcional."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"de":{"copyLanguage":"de","name":"Anleihenrechner","title":"Anleihenrechner kostenlos | UsefulVerse","description":"Schätzen Sie den Anleihepreis oder die Rendite bis zur Fälligkeit anhand von Kupon, Nennwert und Laufzeit. Kostenlose, unbegrenzte Berechnungen werden lokal…","intro":"Schätzen Sie den Preis einer festverzinslichen Anleihe anhand der Rendite oder ermitteln Sie die ungefähre Rendite bis zur Fälligkeit anhand eines notierten Marktpreises. Überprüfen Sie die Annahmen und die Preis-Rendite-Kurve, bevor Sie das Ergebnis verwenden.","howQuestion":"Wie berechne ich den Anleihepreis oder die Rendite bis zur Fälligkeit?","howAnswer":"Geben Sie den Nennwert, den jährlichen Kuponsatz, die Restlaufzeit und die Kuponhäufigkeit ein. Wählen Sie „Preis-aus-Rendite“, um die geplanten Kupon- und Kapitalzahlungen abzuzinsen, oder wählen Sie „Rendite-aus-Preis“, um die nominelle Jahresrendite numerisch zu ermitteln, die einem Marktpreis entspricht.","privacyQuestion":"Werden meine Anleiheeingaben hochgeladen?","privacyAnswer":"Nein. Die Berechnung läuft in diesem Browser. Eingaben werden von diesem Tool nicht hochgeladen oder gespeichert.","howTo":["Wählen Sie, ob ein Preis anhand der Rendite geschätzt oder die Rendite anhand eines Marktpreises ermittelt werden soll.","Geben Sie den Nennwert, den jährlichen Kuponsatz, die Laufzeit und die Kuponhäufigkeit ein.","Berechnen und vergleichen Sie das Ergebnis mit den angezeigten Annahmen und der Kurve."],"example":{"label":"Laden Sie eine 5 %-Kuponanleihe zum Nennwert","values":[]},"actions":{"calculate":"Berechnen Sie den Anleihewert","example":"Par-Bond-Beispiel","reset":"Reset","copy":"Ergebnisse kopieren","result":"Anleiheschätzung"},"fields":{"mode":"Berechnungsmodus","priceMode":"Preis aus einem Ertrag","yieldMode":"Rendite aus einem Marktpreis","faceValue":"Nennwert (Nennwert)","couponPercent":"Jährlicher Kuponsatz (%)","years":"Jahre bis zur Fälligkeit","frequency":"Couponzahlungen pro Jahr","annual":"Jährlich (1)","semiannual":"Halbjährlich (2)","quarterly":"Vierteljährlich (4)","monthly":"Monatlich (12)","yieldPercent":"Nomineller Jahresertrag (%)","marketPrice":"Marktpreis","accuracyNote":"Nur pädagogische Schätzung, keine Anlageberatung. Es wird davon ausgegangen, dass in regelmäßigen Abständen feste Kupons gezahlt werden, das Kapital bei Fälligkeit zurückgezahlt wird, die jährliche Nominalrendite mit der gewählten Kuponfrequenz aufgezinst wird und keine aufgelaufenen Zinsen, Steuern, Gebühren, Zahlungsausfälle, Kündigungsfunktionen, Inflations- oder Reinvestitionseffekte anfallen. Die Laufzeit muss eine ganze Anzahl von Kuponperioden betragen. Die Ausbeute ist numerisch und ungefähr; Anleihebedingungen und Marktkonventionen selbstständig bestätigen.","resultSummary":"Geschätzte Anleiheergebnisse","yieldToMaturity":"Rendite bis zur Fälligkeit (nominal jährlich)","estimatedPrice":"Geschätzter Preis","couponPayment":"Couponzahlung pro Periode","currentYield":"Aktuelle Rendite","totalCoupons":"Gesamtzahl der geplanten Coupons","premiumDiscount":"Aufschlag/Rabatt auf Nennwert","periods":"Kuponperioden","chartTitle":"Geschätzte Preis-Rendite-Kurve","chartDescription":"Der Anleihepreis bewegt sich im Allgemeinen in die entgegengesetzte Richtung zur Rendite. Die Kurve verwendet die eingegebenen festen Kupon- und Fälligkeitsannahmen.","chartYield":"Nomineller Jahresertrag (%)","chartPrice":"Geschätzter Preis"},"messages":{"calculated":"Anleiheschätzung berechnet.","exampleLoaded":"Beispiel geladen: 5 % Kupon, 5 Jahre, jährliche Zahlungen, Preis zum Nennwert.","checkInputs":"Überprüfen Sie die Bindungswerte und versuchen Sie es erneut.","copied":"Ergebnisse kopiert.","copyUnavailable":"Copy ist in diesem Browser nicht verfügbar.","invalidPeriods":"Wählen Sie eine Laufzeit, die eine ganze Anzahl von Kuponperioden (bis zu 1.200) enthält.","yieldOutOfRange":"Der Marktpreis liegt außerhalb des unterstützten numerischen Ertragsbereichs."},"additionalFaqs":[{"question":"Welche Rendite hat eine 5 %-Kuponanleihe, wenn sie zum Nennwert bewertet wird?","answer":"Unter den Annahmen des Rechners hat eine Anleihe mit einem jährlichen Kupon von 5 %, einem Marktpreis in Höhe des Nennwerts und regelmäßigen Kuponzahlungen eine Nominalrendite bis zur Fälligkeit von 5 %."},{"question":"Warum bewegen sich Anleihepreise und -renditen in entgegengesetzte Richtungen?","answer":"Der Preis einer Anleihe ist der Barwert der geplanten Kupons und des Kapitals. Eine höhere Diskontrendite verringert diesen Barwert; ein geringerer Ertrag erhöht ihn."},{"question":"Ist die aktuelle Rendite dasselbe wie die Rendite bis zur Fälligkeit?","answer":"Nein. Die aktuelle Rendite ist der jährliche Kupon dividiert durch den aktuellen Preis. Die Rendite bis zur Fälligkeit berücksichtigt unter den angegebenen Cashflow-Annahmen auch die Preisdifferenz zwischen dem Nennwert und der verbleibenden Restlaufzeit."},{"question":"Beinhaltet diese Schätzung aufgelaufene Zinsen oder Steuern?","answer":"Nein. Es werden nur regelmäßige feste Kuponzahlungen und die Kapitalrückzahlung modelliert. Es werden kein Clean-versus-Dirty-Preis, aufgelaufene Zinsen, Steuern, Gebühren, Kreditrisiken oder optionale Rückzahlungen berechnet."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"ja":{"copyLanguage":"ja","name":"債券計算機","title":"債券計算機 無料 | UsefulVerse","description":"クーポン、額面、期間から債券価格または満期までの利回りを推定します。無料で無制限の計算がブラウザ内でローカルに実行されます。","intro":"固定利付債券の利回りから価格を推定するか、市場価格から満期までのおおよその利回りを求めます。結果を使用する前に、仮定と価格利回り曲線を確認してください。","howQuestion":"債券価格や満期までの利回りはどのように計算すればよいですか?","howAnswer":"額面、年間クーポン利率、満期までの年数、クーポン頻度を入力します。予定利率と元本の支払いを割引するには利回りからの価格を選択するか、市場価格と一致する名目年間利回りを数値的に解決するには価格からの利回りを選択します。","privacyQuestion":"私の債券入力はアップロードされていますか?","privacyAnswer":"いいえ。計算はこのブラウザで実行されます。このツールでは入力はアップロードまたは保存されません。","howTo":["利回りから価格を見積もるか、市場価格から利回りを求めるかを選択します。","額面、年間クーポン利率、満期、クーポン頻度を入力します。","計算し、結果を表示された仮定および曲線と比較します。"],"example":{"label":"額面価格の 5% クーポン債券をロードします","values":[]},"actions":{"calculate":"債券価値の計算","example":"額面債券のロード例","reset":"リセット","copy":"コピー結果","result":"債券予想"},"fields":{"mode":"演算モード","priceMode":"利回りからの価格","yieldMode":"市場価格からの利回り","faceValue":"面（パー）値","couponPercent":"年間クーポン率 (%)","years":"満期までの年数","frequency":"年間クーポンの支払い","annual":"年次 (1)","semiannual":"半年ごと (2)","quarterly":"四半期ごと (4)","monthly":"月間 (12)","yieldPercent":"名目年間利回り (%)","marketPrice":"市場価格","accuracyNote":"教育上の見積もりのみであり、投資アドバイスではありません。固定クーポンが一定の間隔で支払われ、元本が満期に返済され、名目年間利回りは選択したクーポン頻度で複利計算され、未払いの利息、税金、手数料、債務不履行、コール機能、インフレまたは再投資の影響がないことを前提としています。満期はクーポン期間の整数である必要があります。収量はおおよその数値です。債券条件と市場慣習を独立して確認します。","resultSummary":"推定債券結果","yieldToMaturity":"満期までの利回り (名目年間)","estimatedPrice":"推定価格","couponPayment":"期間ごとのクーポン支払い","currentYield":"現在の利回り","totalCoupons":"予定されているクーポンの合計","premiumDiscount":"プレミアム/額面価格からの割引","periods":"クーポン期間","chartTitle":"推定価格利回り曲線","chartDescription":"債券価格は通常、利回りとは逆の方向に動きます。この曲線は、入力された固定クーポンと満期の仮定を使用します。","chartYield":"名目年間利回り (%)","chartPrice":"概算価格"},"messages":{"calculated":"債券の見積りが計算されました。","exampleLoaded":"ロードされた例: 5% クーポン、5 年間、年払い、額面価格。","checkInputs":"結合値を確認して、再試行してください。","copied":"結果がコピーされました。","copyUnavailable":"このブラウザではコピーを利用できません。","invalidPeriods":"クーポン期間の整数 (最大 1,200) を含む満期を選択します。","yieldOutOfRange":"市場価格がサポートされている数値収量範囲外です。"},"additionalFaqs":[{"question":"5% クーポン債の価格が額面のときの利回りはどれくらいですか?","answer":"計算機の仮定の下では、年間クーポン利率が 5%、市場価格が額面に等しく、定期的なクーポン支払いが行われる債券の満期までの名目利回りは 5% です。"},{"question":"債券価格と利回りが逆方向に動くのはなぜですか?","answer":"債券価格は、予定されているクーポンと元本の現在価値です。割引利回りが高くなると、現在価値が減少します。収量が低いと増加します。"},{"question":"現在の利回りは満期までの利回りと同じですか?","answer":"いいえ。現在の利回りは、年間クーポンを現在の価格で割ったものです。満期までの利回りには、記載されたキャッシュフローの仮定に基づいて、額面との価格差および残存期間も考慮されます。"},{"question":"この見積もりには未払い利息または税金が含まれますか?","answer":"いいえ。定期的な固定クーポンの支払いと元金の返済のみをモデル化しています。クリーン対ダーティの価格、未払い利息、税金、手数料、信用リスク、またはオプションの償還は計算されません。"}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"ko":{"copyLanguage":"ko","name":"채권 계산기","title":"채권 계산기 무료 | UsefulVerse","description":"쿠폰, 액면가 및 기간을 통해 채권 가격이나 만기 수익률을 추정합니다. 무료 무제한 계산은 브라우저에서 로컬로 실행됩니다.","intro":"수익률로부터 고정 금리 채권 가격을 추정하거나 공시된 시장 가격에서 대략적인 만기 수익률을 구합니다. 결과를 사용하기 전에 가정과 가격-수익률 곡선을 검토하십시오.","howQuestion":"채권 가격이나 만기 수익률을 어떻게 계산합니까?","howAnswer":"액면가, 연간 이표율, 만기 연수 및 이표 빈도를 입력합니다. 예정된 쿠폰과 원금 지급액을 할인하려면 수익률 대비 가격을 선택하고, 시장 가격과 일치하는 명목 연간 수익률을 수치적으로 해결하려면 가격 대비 수익률을 선택하세요.","privacyQuestion":"내 채권 입력이 업로드됩니까?","privacyAnswer":"아니요. 계산은 이 브라우저에서 실행됩니다. 이 도구는 입력을 업로드하거나 저장하지 않습니다.","howTo":["수익률로부터 가격을 추정할지 아니면 시장 가격에서 수익률을 구할지 선택합니다.","액면가, 연간 쿠폰 금리, 만기 및 쿠폰 빈도를 입력하세요.","표시된 가정 및 곡선과 결과를 계산하고 비교합니다."],"example":{"label":"액면","values":[]},"actions":{"calculate":"채권 가치 계산","example":"로드 동등 결합 예시","reset":"재설정","copy":"결과 복사","result":"채권 추정치"},"fields":{"mode":"계산 모드","priceMode":"수익률에 따른 가격","yieldMode":"시장 가격으로부터의 수익률","faceValue":"액면가(액면가)","couponPercent":"연간 쿠폰율(%)","years":"만기까지의 연수","frequency":"연간 이자 지급","annual":"연간 (1)","semiannual":"반기별 (2)","quarterly":"분기별 (4)","monthly":"월별 (12)","yieldPercent":"명목 연간 수익률(%)","marketPrice":"시장 가격","accuracyNote":"투자 조언이 아닌 교육적 견적만 제공됩니다. 정기적으로 지급되는 고정 이표, 만기 시 원금 상환, 선택한 이표 빈도에 따라 복리로 계산되는 명목 연간 수익률, 발생 이자, 세금, 수수료, 채무 불이행, 콜 기능, 인플레이션 또는 재투자 효과가 없다고 가정합니다. 만기는 이자 지급 기간의 정수여야 합니다. 수율은 숫자이며 대략적입니다. 채권 조건과 시장 관행을 독립적으로 확인합니다.","resultSummary":"예상 채권 결과","yieldToMaturity":"만기수익률(명목 연간)","estimatedPrice":"예상 가격","couponPayment":"기간별 쿠폰 지급","currentYield":"현재 수익률","totalCoupons":"총 예정 쿠폰","premiumDiscount":"프리미엄 / 액면가 대비 할인","periods":"쿠폰 기간","chartTitle":"예상 가격-수익률 곡선","chartDescription":"채권 가격은 일반적으로 수익률과 반대 방향으로 움직입니다. 곡선은 입력된 고정 이표와 만기 가정을 사용합니다.","chartYield":"명목 연간 수익률(%)","chartPrice":"예상 가격"},"messages":{"calculated":"채권 추정치가 계산되었습니다.","exampleLoaded":"로드된 예: 5% 쿠폰, 5년, 연간 지불, 액면가 가격.","checkInputs":"채권값을 확인하고 다시 시도해 보세요.","copied":"결과가 복사되었습니다.","copyUnavailable":"이 브라우저에서는 복사를 사용할 수 없습니다.","invalidPeriods":"전체 이자 기간(최대 1,200)을 포함하는 만기를 선택합니다.","yieldOutOfRange":"시장 가격이 지원되는 수치 수익률 범위를 벗어났습니다."},"additionalFaqs":[{"question":"액면가로 가격이 책정될 때 5% 쿠폰 채권의 수익률은 얼마입니까?","answer":"계산기 가정에 따르면, 연간 표면이자율이 5%이고, 시장 가격이 액면가와 동일하며, 정기적으로 쿠폰을 지급하는 채권의 명목 만기 수익률은 5%입니다."},{"question":"채권 가격과 수익률이 반대 방향으로 움직이는 이유는 무엇입니까?","answer":"채권 가격은 예정된 이표와 원금의 현재 가치입니다. 할인 수익률이 높을수록 현재 가치가 감소합니다. 수확량이 낮을수록 증가합니다."},{"question":"현재 수익률은 만기 수익률과 동일합니까?","answer":"아니요. 현재 수익률은 연간 쿠폰을 현재 가격으로 나눈 값입니다. 만기수익률은 명시된 현금 흐름 가정에 따라 액면가 및 남은 시간과의 가격 차이도 고려합니다."},{"question":"이 추정치에 경과이자나 세금이 포함되어 있습니까?","answer":"아니요. 정기적인 고정 이표 지급과 원금 상환만 모델로 합니다. 순수 가격 대 더러운 가격, 발생 이자, 세금, 수수료, 신용 위험 또는 선택적 상환은 계산하지 않습니다."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"id":{"copyLanguage":"id","name":"Bond Calculator","title":"Bond Calculator gratis | UsefulVerse","description":"Perkirakan harga obligasi atau imbal hasil hingga jatuh tempo dari kupon, nilai nominal, dan jangka waktu. Penghitungan gratis dan tidak terbatas dijalankan…","intro":"Perkirakan harga obligasi dengan suku bunga tetap dari imbal hasilnya, atau selesaikan perkiraan imbal hasil hingga jatuh tempo dari harga pasar yang dikutip. Tinjau kembali asumsi dan kurva harga-hasil sebelum menggunakan hasilnya.","howQuestion":"Bagaimana cara menghitung harga obligasi atau imbal hasil hingga jatuh tempo?","howAnswer":"Masukkan nilai nominal, tingkat kupon tahunan, jangka waktu jatuh tempo, dan frekuensi kupon. Pilih harga-dari-hasil untuk mendiskon pembayaran kupon dan pokok yang dijadwalkan, atau pilih hasil-dari-harga untuk menyelesaikan secara numerik hasil tahunan nominal yang sesuai dengan harga pasar.","privacyQuestion":"Apakah masukan obligasi saya sudah diupload?","privacyAnswer":"Tidak. Perhitungan dijalankan di browser ini. Masukan tidak diunggah atau disimpan oleh alat ini.","howTo":["Pilih apakah akan memperkirakan harga dari hasil atau menyelesaikan hasil dari harga pasar.","Masukkan nilai nominal, tingkat kupon tahunan, jatuh tempo dan frekuensi kupon.","Hitung dan bandingkan hasilnya dengan asumsi dan kurva yang ditampilkan."],"example":{"label":"Muat obligasi kupon 5% dengan harga setara","values":[]},"actions":{"calculate":"Hitung nilai obligasi","example":"Muat contoh par-bond","reset":"Setel ulang","copy":"Copy hasil","result":"Estimasi obligasi"},"fields":{"mode":"Mode perhitungan","priceMode":"Harga dari hasil","yieldMode":"Hasil dari harga pasar","faceValue":"Nilai muka (par)","couponPercent":"Tingkat kupon tahunan (%)","years":"Tahun jatuh tempo","frequency":"Pembayaran kupon per tahun","annual":"Tahunan (1)","semiannual":"Semesteran (2)","quarterly":"Triwulanan (4)","monthly":"Bulanan (12)","yieldPercent":"Hasil tahunan nominal (%)","marketPrice":"Harga pasar","accuracyNote":"Hanya perkiraan pendidikan, bukan saran investasi. Mengasumsikan kupon tetap dibayarkan secara berkala, pokok dilunasi pada saat jatuh tempo, nominal imbal hasil tahunan yang dimajemukkan pada frekuensi kupon yang dipilih, dan tidak ada bunga, pajak, biaya, gagal bayar, fitur panggilan, inflasi atau efek reinvestasi yang masih harus dibayar. Jatuh tempo harus berupa sejumlah periode kupon. Hasil bersifat numerik dan perkiraan; mengkonfirmasi ketentuan obligasi dan konvensi pasar secara independen.","resultSummary":"Perkiraan hasil obligasi","yieldToMaturity":"Hasil hingga jatuh tempo (nominal tahunan)","estimatedPrice":"Perkiraan harga","couponPayment":"Pembayaran kupon per periode","currentYield":"Hasil saat ini","totalCoupons":"Total kupon terjadwal","premiumDiscount":"Premium / diskon sesuai nilai nominal","periods":"Periode kupon","chartTitle":"Estimasi kurva harga-hasil","chartDescription":"Harga obligasi umumnya bergerak berlawanan arah dengan imbal hasil. Kurva tersebut menggunakan asumsi kupon tetap dan jatuh tempo yang dimasukkan.","chartYield":"Hasil tahunan nominal (%)","chartPrice":"Perkiraan harga"},"messages":{"calculated":"Estimasi obligasi dihitung.","exampleLoaded":"Contoh dimuat: kupon 5%, 5 tahun, pembayaran tahunan, harga par.","checkInputs":"Periksa nilai obligasi dan coba lagi.","copied":"disalin.","copyUnavailable":"tidak tersedia di browser ini.","invalidPeriods":"Pilih jatuh tempo yang berisi seluruh jumlah periode kupon (hingga 1.200).","yieldOutOfRange":"Harga pasar berada di luar kisaran hasil numerik yang didukung."},"additionalFaqs":[{"question":"Berapa imbal hasil obligasi dengan kupon 5% jika dihargai setara?","answer":"Berdasarkan asumsi kalkulator, obligasi dengan tingkat kupon tahunan 5%, harga pasar sama dengan nilai nominal dan pembayaran kupon reguler memiliki imbal hasil nominal hingga jatuh tempo sebesar 5%."},{"question":"Mengapa harga dan imbal hasil obligasi bergerak berlawanan arah?","answer":"Harga obligasi adalah nilai sekarang dari kupon dan pokok yang dijadwalkan. Hasil diskon yang lebih tinggi mengurangi nilai sekarang; hasil yang lebih rendah meningkatkannya."},{"question":"Apakah imbal hasil saat ini sama dengan imbal hasil hingga jatuh tempo?","answer":"No. Hasil saat ini adalah kupon tahunan dibagi dengan harga saat ini. Hasil hingga jatuh tempo juga memperhitungkan perbedaan harga dari nilai nominal dan sisa waktu, berdasarkan asumsi arus kas yang disebutkan."},{"question":"Apakah perkiraan ini sudah termasuk bunga atau pajak yang masih harus dibayar?","answer":"Tidak. Ini memodelkan pembayaran kupon tetap reguler dan pembayaran pokok saja. Ini tidak menghitung harga bersih versus kotor, bunga yang masih harus dibayar, pajak, biaya, risiko kredit atau penebusan opsional."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"hi":{"copyLanguage":"hi","name":"बांड कैलकुलेटर","title":"बांड कैलकुलेटर मुफ़्त | UsefulVerse","description":"कूपन, अंकित मूल्य और अवधि से बांड की कीमत या परिपक्वता तक उपज का अनुमान लगाएं। निःशुल्क, असीमित गणनाएँ आपके ब्राउज़र में स्थानीय रूप से चलती हैं।","intro":"इसकी उपज से एक निश्चित दर बांड मूल्य का अनुमान लगाएं, या उद्धृत बाजार मूल्य से परिपक्वता तक अनुमानित उपज का समाधान करें। परिणाम का उपयोग करने से पहले मान्यताओं और मूल्य-उपज वक्र की समीक्षा करें।","howQuestion":"मैं बांड मूल्य या परिपक्वता पर उपज की गणना कैसे करूं?","howAnswer":"अंकित मूल्य, वार्षिक कूपन दर, परिपक्वता के वर्ष और कूपन आवृत्ति दर्ज करें। निर्धारित कूपन और मूल भुगतान पर छूट देने के लिए उपज से मूल्य चुनें, या बाजार मूल्य से मेल खाने वाली नाममात्र वार्षिक उपज को संख्यात्मक रूप से हल करने के लिए उपज से कीमत चुनें।","privacyQuestion":"क्या मेरे बांड इनपुट अपलोड किए गए हैं?","privacyAnswer":"नहीं. गणना इस ब्राउज़र में चलती है. इस टूल द्वारा इनपुट अपलोड या सहेजे नहीं जाते हैं।","howTo":["चुनें कि उपज से कीमत का अनुमान लगाना है या बाजार मूल्य से उपज का समाधान करना है।","अंकित मूल्य, वार्षिक कूपन दर, परिपक्वता और कूपन आवृत्ति दर्ज करें।","प्रदर्शित मान्यताओं और वक्र के साथ परिणाम की गणना और तुलना करें।"],"example":{"label":"Load a 5% coupon bond priced at par","values":[]},"actions":{"calculate":"बांड मूल्य","example":"लोड पार-बॉन्ड उदाहरण","reset":"रीसेट","copy":"परिणाम कॉपी करें","result":"बांड अनुमान"},"fields":{"mode":"गणना मोड","priceMode":"उपज","yieldMode":"बाजार मूल्य","faceValue":"अंकित मूल्य","couponPercent":"वार्षिक कूपन दर (%)","years":"परिपक्वता तक वर्ष","frequency":"कूपन भुगतान प्रति वर्ष","annual":"वार्षिक (1)","semiannual":"अर्धवार्षिक (2)","quarterly":"त्रैमासिक (4)","monthly":"मासिक (12)","yieldPercent":"नाममात्र वार्षिक उपज (%)","marketPrice":"बाजार मूल्य","accuracyNote":"केवल शैक्षिक अनुमान, निवेश सलाह नहीं। नियमित अंतराल पर भुगतान किए गए निश्चित कूपन, परिपक्वता पर चुकाया गया मूलधन, चयनित कूपन आवृत्ति पर नाममात्र वार्षिक उपज, और कोई अर्जित ब्याज, कर, शुल्क, डिफ़ॉल्ट, कॉल सुविधाएँ, मुद्रास्फीति या पुनर्निवेश प्रभाव नहीं मानता है। परिपक्वता कूपन अवधियों की एक पूरी संख्या होनी चाहिए। उपज संख्यात्मक और अनुमानित है; बांड की शर्तों और बाज़ार परंपराओं की स्वतंत्र रूप से पुष्टि करें।","resultSummary":"अनुमानित बांड परिणाम","yieldToMaturity":"परिपक्वता तक उपज (नाममात्र वार्षिक)","estimatedPrice":"अनुमानित कीमत","couponPayment":"कूपन भुगतान प्रति अवधि","currentYield":"वर्तमान उपज","totalCoupons":"कुल निर्धारित कूपन","premiumDiscount":"प्रीमियम/अंकित मूल्य पर छूट","periods":"कूपन अवधि","chartTitle":"अनुमानित मूल्य-उपज वक्र","chartDescription":"बांड की कीमत आम तौर पर उपज की विपरीत दिशा में चलती है। वक्र दर्ज किए गए निश्चित कूपन और परिपक्वता मान्यताओं का उपयोग करता है।","chartYield":"नाममात्र वार्षिक उपज (%)","chartPrice":"अनुमानित कीमत"},"messages":{"calculated":"बांड अनुमान की गणना की गई।","exampleLoaded":"उदाहरण लोड किया गया: 5% कूपन, 5 वर्ष, वार्षिक भुगतान, कीमत बराबर।","checkInputs":"बांड मूल्यों की जाँच करें और पुनः प्रयास करें।","copied":"परिणाम कॉपी किये गये।","copyUnavailable":"कॉपी इस ब्राउज़र में उपलब्ध नहीं है.","invalidPeriods":"ऐसी परिपक्वता चुनें जिसमें कूपन अवधियों की पूरी संख्या (1,200 तक) शामिल हो।","yieldOutOfRange":"बाजार मूल्य समर्थित संख्यात्मक उपज सीमा से बाहर है।"},"additionalFaqs":[{"question":"5% कूपन बांड की कीमत बराबर होने पर क्या उपज होती है?","answer":"कैलकुलेटर मान्यताओं के तहत, 5% वार्षिक कूपन दर, अंकित मूल्य के बराबर बाजार मूल्य और नियमित कूपन भुगतान वाले बांड की परिपक्वता पर 5% की नाममात्र उपज होती है।"},{"question":"बांड की कीमतें और प्रतिफल विपरीत दिशाओं में क्यों बढ़ते हैं?","answer":"एक बांड मूल्य उसके निर्धारित कूपन और मूलधन का वर्तमान मूल्य है। अधिक छूट उपज उस वर्तमान मूल्य को कम कर देती है; कम उपज इसे बढ़ाती है।"},{"question":"क्या वर्तमान उपज परिपक्वता पर उपज के समान है?","answer":"नं. वर्तमान उपज वार्षिक कूपन को वर्तमान कीमत से विभाजित किया जाता है। बताई गई नकदी-प्रवाह धारणाओं के तहत, परिपक्वता तक उपज अंकित मूल्य और शेष समय से मूल्य अंतर के लिए भी जिम्मेदार होती है।"},{"question":"क्या इस अनुमान में अर्जित ब्याज या कर शामिल हैं?","answer":"नहीं। यह केवल नियमित निश्चित कूपन भुगतान और मूलधन पुनर्भुगतान को मॉडल करता है। यह साफ़-बनाम-गंदी कीमत, अर्जित ब्याज, कर, शुल्क, क्रेडिट जोखिम या वैकल्पिक मोचन की गणना नहीं करता है।"}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"ar":{"copyLanguage":"ar","name":"حاسبة السندات","title":"حاسبة السندات مجانا | UsefulVerse","description":"تقدير سعر السند أو العائد حتى تاريخ الاستحقاق من القسيمة والقيمة الاسمية والمدة. يتم تشغيل حسابات مجانية وغير محدودة محليًا في متصفحك.","intro":"قم بتقدير سعر السندات ذات السعر الثابت من عائدها، أو حل العائد التقريبي حتى تاريخ الاستحقاق من سعر السوق المعروض. راجع الافتراضات ومنحنى السعر والعائد قبل استخدام النتيجة.","howQuestion":"كيف يمكنني حساب سعر السند أو العائد حتى تاريخ الاستحقاق؟","howAnswer":"أدخل القيمة الاسمية ومعدل القسيمة السنوي والسنوات حتى الاستحقاق وتكرار القسيمة. اختر السعر من العائد لخصم القسيمة المجدولة والدفعات الأساسية، أو اختر العائد من السعر لحل العائد السنوي الاسمي الذي يطابق سعر السوق عدديًا.","privacyQuestion":"هل تم تحميل مدخلات السندات الخاصة بي؟","privacyAnswer":"لا. يتم تشغيل الحساب في هذا المتصفح. لا يتم تحميل المدخلات أو حفظها بواسطة هذه الأداة.","howTo":["اختر ما إذا كنت تريد تقدير السعر من العائد أو حل العائد من سعر السوق.","أدخل القيمة الاسمية ومعدل القسيمة السنوي والاستحقاق وتكرار القسيمة.","قم بحساب النتيجة ومقارنتها مع الافتراضات والمنحنى المعروضين."],"example":{"label":"قم بتحميل سندات قسيمة بنسبة 5٪ بسعر","values":[]},"actions":{"calculate":"حساب قيمة السند","example":"تحميل مثال السندات الاسمية","reset":"إعادة الضبط","copy":"نسخ النتائج","result":"Bond estimate"},"fields":{"mode":"وضع الحساب","priceMode":"السعر من عائد","yieldMode":"العائد من سعر السوق","faceValue":"قيمة الوجه (الاسمية)","couponPercent":"معدل القسيمة السنوية (%)","years":"السنوات حتى الاستحقاق","frequency":"تكرار دفع القسيمة سنويًا","annual":"السنوي (1)","semiannual":"نصف سنوي (2)","quarterly":"ربع سنوي (4)","monthly":"شهري (12)","yieldPercent":"العائد السنوي الاسمي (٪)","marketPrice":"سعر السوق","accuracyNote":"تقدير تعليمي فقط، وليس نصيحة استثمارية. يفترض أن الكوبونات الثابتة تُدفع على فترات منتظمة، ويتم سداد أصل المبلغ عند الاستحقاق، والعائد السنوي الاسمي المركب بتكرار القسيمة المحدد، ولا توجد فوائد مستحقة أو ضرائب أو رسوم أو تقصير أو ميزات استدعاء أو تضخم أو آثار إعادة استثمار. يجب أن يكون الاستحقاق عددًا صحيحًا من فترات القسيمة. العائد عددي وتقريبي. تأكيد شروط السندات واتفاقيات السوق بشكل مستقل.","resultSummary":"نتائج السندات المقدرة","yieldToMaturity":"العائد حتى تاريخ الاستحقاق (السنوي الاسمي)","estimatedPrice":"السعر المقدر","couponPayment":"دفع القسيمة لكل فترة","currentYield":"العائد الحالي","totalCoupons":"إجمالي الكوبونات المجدولة","premiumDiscount":"قسط / خصم على القيمة الاسمية","periods":"Coupon periods","chartTitle":"منحنى السعر والعائد المقدر","chartDescription":"بشكل عام في الاتجاه المعاكس للعائد. يستخدم المنحنى القسيمة الثابتة المدخلة وافتراضات الاستحقاق.","chartYield":"العائد السنوي الاسمي (٪)","chartPrice":"السعر المقدر"},"messages":{"calculated":".","exampleLoaded":"تم تحميل المثال: قسيمة 5%، 5 سنوات، دفعات سنوية، السعر بالقيمة الاسمية.","checkInputs":"تحقق من قيم السندات وحاول مرة أخرى.","copied":".","copyUnavailable":"غير متاحة في هذا المتصفح.","invalidPeriods":"اختر فترة استحقاق تحتوي على عدد صحيح من فترات القسيمة (حتى 1200).","yieldOutOfRange":"سعر السوق خارج نطاق العائد العددي المدعوم."},"additionalFaqs":[{"question":"ما العائد لسند بمعدل قسيمة 5% عندما يساوي سعره قيمته الاسمية؟","answer":"وفق افتراضات الحاسبة، يكون العائد الاسمي حتى الاستحقاق 5% لسند بمعدل قسيمة سنوي 5% وسعر سوق يساوي قيمته الاسمية مع دفعات منتظمة."},{"question":"لماذا تتحرك أسعار السندات وعوائدها في اتجاهين متعاكسين؟","answer":"سعر السند هو القيمة الحالية لكوبوناته المجدولة وأصله. يؤدي ارتفاع عائد الخصم إلى تقليل القيمة الحالية؛ انخفاض العائد يزيد منه."},{"question":"هل العائد الحالي هو نفسه العائد حتى تاريخ الاستحقاق؟","answer":"لا. العائد الحالي هو القسيمة السنوية مقسومة على السعر الحالي. ويأخذ العائد حتى تاريخ الاستحقاق في الحسبان أيضًا الفرق عن القيمة الاسمية والمدة المتبقية، وفق افتراضات التدفقات النقدية المذكورة."},{"question":"هل يشمل هذا التقدير الفوائد أو الضرائب المستحقة؟","answer":"لا. إنها نماذج دفعات القسيمة الثابتة المنتظمة وسداد أصل المبلغ فقط. ولا يحسب السعر النظيف مقابل القذر أو الفوائد المستحقة أو الضرائب أو الرسوم أو مخاطر الائتمان أو الاسترداد الاختياري."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"zh":{"copyLanguage":"zh","name":"债券计算器","title":"债券计算器 免费 | UsefulVerse","description":"根据息票、面值和期限估算债券价格或到期收益率。免费、无限制的计算在您的浏览器本地运行。","intro":"根据收益率估算固定利率债券价格，或根据市场报价求解近似到期收益率。在使用结果之前检查假设和价格-收益率曲线。","howQuestion":"如何计算债券价格或到期收益率？","howAnswer":"输入面值、年票面利率、到期年限和票面频率。选择收益率价格来贴现预定的息票和本金付款，或者选择价格收益率来数值求解与市场价格相匹配的名义年收益率。","privacyQuestion":"我的债券输入是否已上传？","privacyAnswer":"否。计算在此浏览器中运行。此工具不会上传或保存输入。","howTo":["选择是根据收益率估计价格还是根据市场价格求解收益率。","输入面值、年票息率、期限和票息频率。","计算结果并将其与显示的假设和曲线进行比较。"],"example":{"label":"加载按面值定价的 5% 息票债券","values":[]},"actions":{"calculate":"计算债券价值","example":"加载普通债券示例","reset":"复位","copy":"复制结果","result":"债券预估"},"fields":{"mode":"计算模式","priceMode":"收益率的价格","yieldMode":"市场价格的收益率","faceValue":"面值","couponPercent":"年票利率 (%)","years":"到期年数","frequency":"每年的息票支付","annual":"年度 (1)","semiannual":"半年一次 (2)","quarterly":"Quarterly (4)","monthly":"每月 (12)","yieldPercent":"名义年收益率(%)","marketPrice":"市场价格","accuracyNote":"仅作教育评估，不构成投资建议。假设定期支付固定息票，到期时偿还本金，按所选息票频率复利名义年收益率，并且没有应计利息、税费、费用、违约、赎回特征、通货膨胀或再投资影响。到期日必须是息票期的整数倍。产量是数值和近似值；独立确认债券条款和市场惯例。","resultSummary":"预计债券结果","yieldToMaturity":"到期收益率（名义年利率）","estimatedPrice":"预估价格","couponPayment":"每期息票支付","currentYield":"当前收益率","totalCoupons":"预定优惠券总数","premiumDiscount":"面值升贴水","periods":"优惠券期限","chartTitle":"预估价格-收益率曲线","chartDescription":"债券价格通常与收益率走势相反。该曲线使用输入的固定息票和期限假设。","chartYield":"名义年收益率(%)","chartPrice":"预估价格"},"messages":{"calculated":"债券估算已计算。","exampleLoaded":"加载示例：5% 优惠券，5 年，每年付款，平价。","checkInputs":"检查键值并重试。","copied":"结果已复制。","copyUnavailable":"复制在此浏览器中不可用。","invalidPeriods":"选择包含整数个息票期（最多 1,200 个）的到期日。","yieldOutOfRange":"市场价格超出支持的数值收益率范围。"},"additionalFaqs":[{"question":"5%息票债券按面值定价时的收益率是多少？","answer":"在计算器假设下，年票面利率为 5%、市场价格等于票面价值、定期支付息票的债券的名义到期收益率为 5%。"},{"question":"为什么债券价格和收益率走势相反？","answer":"债券价格是其预定票息和本金的现值。较高的贴现率会降低现值；较低的产量会增加它。"},{"question":"当前收益率与到期收益率相同吗？","answer":"否。 当前收益率是年息除以当前价格。在规定的现金流假设下，到期收益率还考虑了与面值和剩余时间的价格差异。"},{"question":"该估算是否包括应计利息或税费？","answer":"否。仅模拟定期固定息票支付和本金偿还。它不计算干净价格与脏价格、应计利息、税费、费用、信用风险或可选赎回。"}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"bn":{"copyLanguage":"bn","name":"বন্ড ক্যালকুলেটর","title":"বন্ড ক্যালকুলেটর বিনামূল্যে | UsefulVerse","description":"আনুমানিক বন্ড মূল্য বা কুপন, অভিহিত মূল্য এবং মেয়াদ থেকে পরিপক্কতা পর্যন্ত ফলন। বিনামূল্যে, সীমাহীন গণনা আপনার ব্রাউজারে স্থানীয়ভাবে চালানো হয়।","intro":"এর ফলন থেকে একটি নির্দিষ্ট হারের বন্ড মূল্য অনুমান করুন, বা উদ্ধৃত বাজার মূল্য থেকে পরিপক্কতার জন্য আনুমানিক ফলন সমাধান করুন৷ ফলাফল ব্যবহার করার আগে অনুমান এবং মূল্য-ফলন বক্ররেখা পর্যালোচনা করুন।","howQuestion":"কিভাবে আমি একটি বন্ডের মূল্য বা পরিপক্কতার ফলন গণনা করব?","howAnswer":"ফেস ভ্যালু, বার্ষিক কুপন রেট, পরিপক্কতা থেকে বছর এবং কুপন ফ্রিকোয়েন্সি লিখুন। নির্ধারিত কুপন এবং মূল অর্থপ্রদানে ছাড় দিতে মূল্য-থেকে-ফলন চয়ন করুন, অথবা বাজার মূল্যের সাথে মেলে এমন নামমাত্র বার্ষিক ফলনকে সংখ্যাগতভাবে সমাধান করতে দাম-থেকে-মূল্য বেছে নিন।","privacyQuestion":"আমার বন্ড ইনপুট আপলোড করা হয়?","privacyAnswer":"নম্বর। গণনা এই ব্রাউজারে চলে। ইনপুট এই টুল দ্বারা আপলোড বা সংরক্ষণ করা হয় না.","howTo":["ফলন থেকে মূল্য অনুমান করা বা বাজার মূল্য থেকে ফলন সমাধান করা চয়ন করুন।","ফেস ভ্যালু, বার্ষিক কুপন রেট, পরিপক্কতা এবং কুপন ফ্রিকোয়েন্সি লিখুন।","গণনা করুন এবং প্রদর্শিত অনুমান এবং বক্ররেখার সাথে ফলাফলের তুলনা করুন।"],"example":{"label":"Load a 5% coupon bond priced at par","values":[]},"actions":{"calculate":"বন্ডের মান গণনা করুন","example":"লোড পার-বন্ড উদাহরণ","reset":"Reset","copy":"ফলাফল কপি করুন","result":"বন্ড অনুমান"},"fields":{"mode":"গণনা মোড","priceMode":"একটি ফলন থেকে মূল্য","yieldMode":"বাজার মূল্য থেকে ফলন","faceValue":"ফেস (পার) মান","couponPercent":"বার্ষিক কুপন রেট (%)","years":"পরিপক্কতা থেকে","frequency":"প্রতি বছর কুপন অর্থপ্রদান","annual":"বার্ষিক (1)","semiannual":"অর্ধবার্ষিক (2)","quarterly":"ত্রৈমাসিক (4)","monthly":"মাসিক (12)","yieldPercent":"নামমাত্র বার্ষিক ফলন (%)","marketPrice":"বাজার মূল্য","accuracyNote":"শুধুমাত্র শিক্ষাগত অনুমান, বিনিয়োগের পরামর্শ নয়। নিয়মিত ব্যবধানে প্রদত্ত নির্দিষ্ট কুপন, মেয়াদপূর্তির সময়ে মূল পরিশোধ করা, নির্বাচিত কুপন ফ্রিকোয়েন্সিতে নামমাত্র বার্ষিক ফলন, এবং কোন সুদ, কর, ফি, ​​ডিফল্ট, কল বৈশিষ্ট্য, মুদ্রাস্ফীতি বা পুনঃবিনিয়োগ প্রভাব অনুমান করে। পরিপক্কতা অবশ্যই কুপন সময়কালের একটি সম্পূর্ণ সংখ্যা হতে হবে। ফলন সংখ্যাগত এবং আনুমানিক; স্বাধীনভাবে বন্ড শর্তাবলী এবং বাজার নিয়মাবলী নিশ্চিত করুন।","resultSummary":"আনুমানিক বন্ড ফলাফল","yieldToMaturity":"পরিপক্কতা পর্যন্ত ফলন (নামমাত্র বার্ষিক)","estimatedPrice":"আনুমানিক মূল্য","couponPayment":"প্রতি পিরিয়ড","currentYield":"বর্তমান ফল","totalCoupons":"মোট নির্ধারিত কুপন","premiumDiscount":"প্রিমিয়াম / মূল্য ছাড়","periods":"কুপন সময়কাল","chartTitle":"আনুমানিক মূল্য-ফলন বক্ররেখা","chartDescription":"বন্ডের দাম সাধারণত ফলনের বিপরীত দিকে চলে। বক্ররেখা প্রবেশ করা নির্দিষ্ট কুপন এবং পরিপক্কতা অনুমান ব্যবহার করে।","chartYield":"নামমাত্র বার্ষিক ফলন (%)","chartPrice":"আনুমানিক মূল্য"},"messages":{"calculated":"বন্ড অনুমান গণনা করা হয়েছে।","exampleLoaded":"উদাহরণ লোড করা হয়েছে: 5% কুপন, 5 বছর, বার্ষিক অর্থপ্রদান, সমান মূল্য।","checkInputs":"বন্ডের মান পরীক্ষা করে আবার চেষ্টা করুন।","copied":"ফলাফল কপি করা হয়েছে।","copyUnavailable":"অনুলিপি এই ব্রাউজারে অনুপলব্ধ৷","invalidPeriods":"একটি পরিপক্কতা চয়ন করুন যাতে পুরো সংখ্যক কুপন পিরিয়ড থাকে (1,200 পর্যন্ত)।","yieldOutOfRange":"বাজার মূল্য সমর্থিত সংখ্যাসূচক ফলন সীমার বাইরে।"},"additionalFaqs":[{"question":"একটি 5% কুপন বন্ডের মূল্য যখন সমান হয় তখন কী ফলন পাওয়া যায়?","answer":"ক্যালকুলেটর অনুমানের অধীনে, 5% বার্ষিক কুপন রেট সহ একটি বন্ড, একটি বাজার মূল্য অভিহিত মূল্যের সমান এবং নিয়মিত কুপন পেমেন্টের 5% পরিপক্কতার জন্য নামমাত্র ফলন রয়েছে।"},{"question":"কেন বন্ডের দাম এবং ফলন বিপরীত দিকে চলে?","answer":"একটি বন্ডের মূল্য হল তার নির্ধারিত কুপন এবং মূলধনের বর্তমান মূল্য। একটি উচ্চ ডিসকাউন্ট ফলন যে বর্তমান মান হ্রাস করে; একটি কম ফলন এটি বৃদ্ধি করে."},{"question":"বর্তমান ফলন কি পরিপক্কতার ফলনের সমান?","answer":"নং। বর্তমান ফল হল বর্তমান মূল্য দ্বারা ভাগ করা বার্ষিক কুপন। বিবৃত নগদ-প্রবাহ অনুমানের অধীনে, পরিপক্কতা থেকে ফলনও অভিহিত মূল্য থেকে মূল্যের পার্থক্য এবং অবশিষ্ট সময়ের জন্য দায়ী।"},{"question":"এই অনুমানটি কি অর্জিত সুদ বা কর অন্তর্ভুক্ত করে?","answer":"নং। এটি নিয়মিত নির্দিষ্ট কুপন পেমেন্ট এবং শুধুমাত্র মূল পরিশোধের মডেল। এটি পরিষ্কার-বনাম-নোংরা মূল্য, অর্জিত সুদ, কর, ফি, ​​ক্রেডিট ঝুঁকি বা ঐচ্ছিক রিডেম্পশন গণনা করে না।"}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"ru":{"copyLanguage":"ru","name":"Калькулятор облигаций","title":"Калькулятор облигаций бесплатно | UsefulVerse","description":"Оцените цену облигации или доходность к погашению на основе купона, номинальной стоимости и срока. Бесплатные неограниченные вычисления выполняются локально в…","intro":"Оцените цену облигации с фиксированной ставкой на основе ее доходности или определите приблизительную доходность к погашению на основе котируемой рыночной цены. Прежде чем использовать результат, просмотрите допущения и кривую цена-доходность.","howQuestion":"Как рассчитать цену облигации или доходность к погашению?","howAnswer":"Введите номинальную стоимость, годовую купонную ставку, количество лет до погашения и частоту купона. Выберите соотношение «цена-от-доходности», чтобы дисконтировать запланированные купонные и основные выплаты, или выберите «доходность-от-цены», чтобы численно определить номинальную годовую доходность, соответствующую рыночной цене.","privacyQuestion":"Загружены ли мои данные по облигациям?","privacyAnswer":"Нет. Расчет выполняется в этом браузере. Входные данные не загружаются и не сохраняются с помощью этого инструмента.","howTo":["Выберите, оценивать ли цену на основе доходности или определять доходность на основе рыночной цены.","Введите номинальную стоимость, годовую купонную ставку, срок погашения и частоту купона.","Рассчитайте и сравните результат с отображаемыми предположениями и кривой."],"example":{"label":"Загрузите 5%-ную купонную облигацию по номинальной цене","values":[]},"actions":{"calculate":"Рассчитать стоимость облигации","example":"Загрузить пример номинальной облигации","reset":"Сброс","copy":"Копировать результаты","result":"Оценка облигаций"},"fields":{"mode":"Режим расчета","priceMode":"Цена от доходности","yieldMode":"Доходность от рыночной цены","faceValue":"Номинальное значение","couponPercent":"Годовая купонная ставка (%)","years":"Срок погашения","frequency":"Купонные выплаты в год","annual":"Годовой (1)","semiannual":"Полугодовой (2)","quarterly":"Ежеквартально (4)","monthly":"Ежемесячно (12)","yieldPercent":"Номинальная годовая доходность (%)","marketPrice":"Рыночная цена","accuracyNote":"Только образовательная оценка, а не инвестиционные советы. Предполагается, что фиксированные купоны выплачиваются через регулярные промежутки времени, основная сумма выплачивается при наступлении срока погашения, номинальная годовая доходность начисляется с выбранной частотой купона, а также отсутствие начисленных процентов, налогов, комиссий, дефолта, функций досрочного погашения, инфляции или эффектов реинвестирования. Срок погашения должен составлять целое число купонных периодов. Выход является числовым и приблизительным; самостоятельно подтверждать условия облигаций и рыночные соглашения.","resultSummary":"Предполагаемые результаты облигаций","yieldToMaturity":"Доходность к погашению (номинальная годовая)","estimatedPrice":"Ориентировочная цена","couponPayment":"Выплата купона за период","currentYield":"Текущая доходность","totalCoupons":"Всего запланированных купонов","premiumDiscount":"Премиум / скидка к номиналу","periods":"Купонные периоды","chartTitle":"Расчетная кривая цена-доходность","chartDescription":"Цена облигации обычно движется в направлении, противоположном доходности. Кривая использует введенные предположения о фиксированном купоне и сроке погашения.","chartYield":"Номинальная годовая доходность (%)","chartPrice":"Ориентировочная цена"},"messages":{"calculated":"Рассчитана оценка облигаций.","exampleLoaded":"Пример загружен: купон 5%, 5 лет, ежегодные выплаты, цена по номиналу.","checkInputs":"Проверьте стоимость облигаций и повторите попытку.","copied":"Результаты скопированы.","copyUnavailable":"Копирование недоступно в этом браузере.","invalidPeriods":"Выберите срок погашения, содержащий целое количество купонных периодов (до 1 200).","yieldOutOfRange":"Рыночная цена находится за пределами поддерживаемого диапазона числовых доходностей."},"additionalFaqs":[{"question":"Какую доходность имеет 5%-ная купонная облигация, если она оценена по номиналу?","answer":"Согласно предположениям калькулятора, облигация с годовой купонной ставкой 5%, рыночной ценой, равной номинальной стоимости, и регулярными купонными выплатами имеет номинальную доходность к погашению 5%."},{"question":"Почему цены и доходность облигаций движутся в противоположных направлениях?","answer":"Цена облигации представляет собой приведенную стоимость ее запланированных купонов и основной суммы долга. Более высокая дисконтная доходность снижает эту приведенную стоимость; более низкая урожайность увеличивает его."},{"question":"Является ли текущая доходность такой же, как доходность к погашению?","answer":"Нет. Текущая доходность равна годовому купону, разделенному на текущую цену. Доходность к погашению также учитывает разницу в цене от номинальной стоимости и оставшееся время в соответствии с заявленными предположениями о движении денежных средств."},{"question":"Включает ли эта оценка начисленные проценты или налоги?","answer":"Нет. Он моделирует только регулярные фиксированные купонные выплаты и погашение основной суммы долга. Он не рассчитывает чистую и грязную цену, начисленные проценты, налоги, сборы, кредитный риск или дополнительное погашение."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"ur":{"copyLanguage":"ur","name":"بانڈ کیلکولیٹر","title":"بانڈ کیلکولیٹر مفت | UsefulVerse","description":"بانڈ کی قیمت کا تخمینہ لگائیں یا کوپن، فیس ویلیو اور مدت سے میچورٹی تک حاصل کریں۔ مفت، لامحدود حسابات آپ کے براؤزر میں مقامی طور پر چلتے ہیں۔","intro":"اس کی پیداوار سے ایک مقررہ شرح والے بانڈ کی قیمت کا تخمینہ لگائیں، یا مارکیٹ کی قیمت کے حوالے سے ایک تخمینی پیداوار کو پختگی تک حل کریں۔ نتیجہ کو استعمال کرنے سے پہلے مفروضوں اور قیمت کا جائزہ لیں۔","howQuestion":"میں بانڈ کی قیمت یا میچورٹی پر حاصل ہونے کا حساب کیسے لگا سکتا ہوں؟","howAnswer":"فیس ویلیو، سالانہ کوپن ریٹ، میچورٹی کے سال اور کوپن فریکوئنسی درج کریں۔ طے شدہ کوپن اور پرنسپل ادائیگیوں میں رعایت کے لیے قیمت سے پیداوار کا انتخاب کریں، یا مارکیٹ کی قیمت سے مماثل معمولی سالانہ پیداوار کو عددی طور پر حل کرنے کے لیے قیمت سے پیداوار کا انتخاب کریں۔","privacyQuestion":"کیا میرے بانڈ ان پٹس اپ لوڈ ہیں؟","privacyAnswer":"نمبر۔ حساب کتاب اس براؤزر میں چلتا ہے۔ ان پٹ اس ٹول کے ذریعے اپ لوڈ یا محفوظ نہیں کیے جاتے ہیں۔","howTo":["منتخب کریں کہ آیا پیداوار سے قیمت کا اندازہ لگانا ہے یا مارکیٹ کی قیمت سے پیداوار کو حل کرنا ہے۔","فیس ویلیو، سالانہ کوپن ریٹ، میچورٹی اور کوپن فریکوئنسی درج کریں۔","ظاہر کردہ مفروضوں اور وکر کے ساتھ نتیجہ کا حساب لگائیں اور موازنہ کریں۔"],"example":{"label":"ایک 5% کوپن بانڈ لوڈ کریں جس کی قیمت","values":[]},"actions":{"calculate":"بانڈ کی قیمت کا حساب لگائیں","example":"لوڈ پار بانڈ مثال","reset":"Reset","copy":"نتائج کاپی کریں","result":"بانڈ کا تخمینہ"},"fields":{"mode":"کیلکولیشن موڈ","priceMode":"ایک پیداوار سے قیمت","yieldMode":"مارکیٹ کی قیمت سے حاصل ہونے والا","faceValue":"چہرہ (برابر) قدر","couponPercent":"سالانہ کوپن کی شرح (%)","years":"پختگی کے سال","frequency":"کوپن کی ادائیگی ہر سال","annual":"سالانہ (1)","semiannual":"نیم سالانہ (2)","quarterly":"سہ ماہی (4)","monthly":"ماہانہ (12)","yieldPercent":"برائے نام سالانہ پیداوار (%)","marketPrice":"مارکیٹ قیمت","accuracyNote":"صرف تعلیمی تخمینہ، سرمایہ کاری کا مشورہ نہیں۔ مستقل وقفوں پر ادا کیے گئے مقررہ کوپن، میچورٹی پر ادا کیے جانے والے پرنسپل، منتخب کوپن فریکوئنسی پر جمع کردہ برائے نام سالانہ پیداوار، اور کوئی جمع شدہ سود، ٹیکس، فیس، ڈیفالٹ، کال فیچرز، افراط زر یا دوبارہ سرمایہ کاری کے اثرات کو فرض کرتا ہے۔ میچورٹی کوپن پیریڈز کی پوری تعداد ہونی چاہیے۔ پیداوار عددی اور تخمینی ہے؛ بانڈ کی شرائط اور مارکیٹ کنونشنز کی آزادانہ طور پر تصدیق کریں۔","resultSummary":"تخمینہ شدہ بانڈ کے نتائج","yieldToMaturity":"پختگی کی پیداوار (برائے نام سالانہ)","estimatedPrice":"تخمینی قیمت","couponPayment":"کوپن کی ادائیگی فی مدت","currentYield":"موجودہ پیداوار","totalCoupons":"کل شیڈول کوپن","premiumDiscount":"پریمیم / ڈسکاؤنٹ فیس ویلیو","periods":"کوپن کی مدت","chartTitle":"تخمینی قیمت–پیداوار وکر","chartDescription":"بانڈ کی قیمت عام طور پر حاصل کرنے کے لیے مخالف سمت میں چلتی ہے۔ وکر داخل شدہ مقررہ کوپن اور پختگی کے مفروضوں کا استعمال کرتا ہے۔","chartYield":"برائے نام سالانہ پیداوار (%)","chartPrice":"تخمینی قیمت"},"messages":{"calculated":"بانڈ کا تخمینہ لگایا گیا۔","exampleLoaded":"مثال بھری ہوئی: 5% کوپن، 5 سال، سالانہ ادائیگیاں، قیمت برابر۔","checkInputs":"بانڈ کی قدریں چیک کریں اور دوبارہ کوشش کریں۔","copied":"نتائج کاپی ہو گئے۔","copyUnavailable":"کاپی اس براؤزر میں دستیاب نہیں ہے۔","invalidPeriods":"ایک میچورٹی کا انتخاب کریں جس میں کوپن پیریڈز کی پوری تعداد (1,200 تک) ہو۔","yieldOutOfRange":"مارکیٹ کی قیمت تائید شدہ عددی پیداوار کی حد سے باہر ہے۔"},"additionalFaqs":[{"question":"جب 5% کوپن بانڈ کی قیمت برابر ہوتی ہے تو اس کا کیا حاصل ہوتا ہے؟","answer":"کیلکولیٹر کے مفروضوں کے تحت، 5% سالانہ کوپن ریٹ کے ساتھ ایک بانڈ، ایک مارکیٹ پرائس فیس ویلیو کے مساوی اور کوپن کی باقاعدہ ادائیگیوں میں 5% کی میچورٹی کی معمولی پیداوار ہوتی ہے۔"},{"question":"بانڈ کی قیمتیں اور پیداوار مخالف سمتوں میں کیوں حرکت کرتے ہیں؟","answer":"ایک بانڈ کی قیمت اس کے طے شدہ کوپنز اور پرنسپل کی موجودہ قیمت ہے۔ زیادہ رعایتی پیداوار اس موجودہ قدر کو کم کر دیتی ہے۔ کم پیداوار اس میں اضافہ کرتی ہے۔"},{"question":"کیا موجودہ پیداوار میچورٹی کی پیداوار کے برابر ہے؟","answer":"نمبر موجودہ پیداوار موجودہ قیمت سے تقسیم ہونے والا سالانہ کوپن ہے۔ بیان کردہ نقد بہاؤ کے مفروضوں کے تحت، میچورٹی سے حاصل ہونے والی قیمت چہرے کی قیمت سے قیمت کے فرق اور باقی وقت کے لیے بھی حساب رکھتی ہے۔"},{"question":"کیا اس تخمینہ میں جمع شدہ سود یا ٹیکس شامل ہیں؟","answer":"نمبر۔ یہ باقاعدہ فکسڈ کوپن کی ادائیگیوں اور صرف اصل ادائیگی کا ماڈل بناتا ہے۔ یہ صاف بمقابلہ گندی قیمت، جمع شدہ سود، ٹیکس، فیس، کریڈٹ رسک یا اختیاری چھٹکارے کا حساب نہیں لگاتا ہے۔"}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"tr":{"copyLanguage":"tr","name":"Tahvil Hesaplayıcı","title":"Tahvil Hesaplayıcı ücretsiz | UsefulVerse","description":"Kupon, nominal değer ve vadeye göre tahvil fiyatını veya vadeye kadar getiriyi tahmin edin. Ücretsiz, sınırsız hesaplamalar tarayıcınızda yerel olarak çalışır.","intro":"Getirisinden sabit faizli tahvil fiyatını tahmin edin veya kote edilmiş bir piyasa fiyatından vadeye kadar yaklaşık getiriyi çözün. Sonucu kullanmadan önce varsayımları ve fiyat-getiri eğrisini gözden geçirin.","howQuestion":"Tahvil fiyatını veya vadeye kadar getirisini nasıl hesaplarım?","howAnswer":"Nominal değeri, yıllık kupon oranını, vadeye kalan yılı ve kupon sıklığını girin. Planlanan kupon ve anapara ödemelerini iskonto etmek için getiriden fiyat seçeneğini seçin veya bir piyasa fiyatıyla eşleşen nominal yıllık getiriyi sayısal olarak çözmek için fiyattan getiriyi seçin.","privacyQuestion":"Tahvil girişlerim yüklendi mi?","privacyAnswer":"Hayır. Hesaplama bu tarayıcıda çalışır. Girişler bu araç tarafından yüklenmez veya kaydedilmez.","howTo":["Getiriden fiyat tahmin etmeyi veya getiriyi piyasa fiyatından çözmeyi seçin.","Nominal değeri, yıllık kupon oranını, vadeyi ve kupon sıklığını girin.","Sonucu hesaplayın ve görüntülenen varsayımlar ve eğriyle karşılaştırın."],"example":{"label":"Load a 5% coupon bond priced at par","values":[]},"actions":{"calculate":"Tahvil değerini hesaplayın","example":"Kısmi bağ örneğini yükleyin","reset":"Reset","copy":"Sonuçları kopyala","result":"Tahvil tahmini"},"fields":{"mode":"Hesaplama modu","priceMode":"Getiriden gelen fiyat","yieldMode":"Piyasa fiyatından elde edilen getiri","faceValue":"Nominal (par) değer","couponPercent":"Yıllık kupon oranı (%)","years":"Vadeye kalan süre","frequency":"Yıllık kupon ödemeleri","annual":"Yıllık (1)","semiannual":"Altı Aylık (2)","quarterly":"Üç Aylık (4)","monthly":"Aylık (12)","yieldPercent":"Nominal yıllık getiri (%)","marketPrice":"Piyasa fiyatı","accuracyNote":"Yalnızca eğitim tahminidir, yatırım tavsiyesi değildir. Düzenli aralıklarla ödenen sabit kuponların, vade sonunda geri ödenen anaparanın, seçilen kupon sıklığına göre birleştirilen nominal yıllık getirinin ve tahakkuk eden faiz, vergi, ücret, temerrüt, geri ödeme özellikleri, enflasyon veya yeniden yatırım etkilerinin bulunmadığını varsayar. Vade tam sayıda kupon dönemi olmalıdır. Verim sayısal ve yaklaşıktır; Tahvil şartlarını ve piyasa konvansiyonlarını bağımsız olarak onaylayın.","resultSummary":"Tahmini tahvil sonuçları","yieldToMaturity":"Vadeye kadar getiri (yıllık nominal)","estimatedPrice":"Estimated price","couponPayment":"Dönem başına kupon ödemesi","currentYield":"Güncel getiri","totalCoupons":"Toplam planlanan kuponlar","premiumDiscount":"Premium / nominal değere göre indirim","periods":"Kupon dönemleri","chartTitle":"Tahmini fiyat-getiri eğrisi","chartDescription":"Tahvil fiyatı genellikle getiri yönünde ters yönde hareket eder. Eğri, girilen sabit kupon ve vade varsayımlarını kullanır.","chartYield":"Nominal yıllık getiri (%)","chartPrice":"Tahmini fiyat"},"messages":{"calculated":"Tahvil tahmini hesaplandı.","exampleLoaded":"Yüklenen örnek: %5 kupon, 5 yıl, yıllık ödemeler, nominal fiyat.","checkInputs":"Bağ değerlerini kontrol edin ve tekrar deneyin.","copied":"Sonuçlar kopyalandı.","copyUnavailable":"Kopyası bu tarayıcıda kullanılamıyor.","invalidPeriods":"Tam sayıda kupon dönemi (1.200'e kadar) içeren bir vade seçin.","yieldOutOfRange":"Piyasa fiyatı desteklenen sayısal getiri aralığının dışında."},"additionalFaqs":[{"question":"Paritede fiyatlandırıldığında %5 kuponlu tahvilin getirisi nedir?","answer":"Hesap makinesinin varsayımlarına göre, yıllık kupon oranı %5, nominal değerine eşit piyasa fiyatı ve düzenli kupon ödemeleri olan bir tahvilin vadeye kadar nominal getirisi %5'tir."},{"question":"Tahvil fiyatları ve getirileri neden zıt yönlerde hareket ediyor?","answer":"Bir tahvilin fiyatı, planlanan kuponlarının ve anaparasının bugünkü değeridir. Daha yüksek bir iskonto getirisi bugünkü değeri azaltır; Daha düşük bir verim onu ​​artırır."},{"question":"Cari getiri vadeye kadar getiri ile aynı mı?","answer":"Hayır. Cari getiri, yıllık kuponun cari fiyata bölünmesiyle elde edilir. Vadeye kadar getiri, belirtilen nakit akışı varsayımları altında, nominal değerden ve kalan süreden fiyat farkını da hesaba katar."},{"question":"Bu tahmine tahakkuk eden faiz veya vergiler dahil mi?","answer":"Hayır. Yalnızca düzenli sabit kupon ödemelerini ve anapara geri ödemesini modeller. Temiz-kirli fiyatı, tahakkuk eden faizi, vergileri, ücretleri, kredi riskini veya isteğe bağlı geri ödemeyi hesaplamaz."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"vi":{"copyLanguage":"vi","name":"Máy tính trái phiếu","title":"Máy tính trái phiếu miễn phí | UsefulVerse","description":"Ước tính giá trái phiếu hoặc lợi tức đến ngày đáo hạn từ phiếu lãi, mệnh giá và kỳ hạn. Các phép tính miễn phí, không giới hạn chạy cục bộ trong trình duyệt…","intro":"Ước tính giá trái phiếu có lãi suất cố định từ lợi tức của nó hoặc tính lợi suất đến ngày đáo hạn gần đúng từ giá thị trường niêm yết. Xem lại các giả định và đường cong giá-lợi suất trước khi sử dụng kết quả.","howQuestion":"Làm cách nào để tính giá trái phiếu hoặc lợi tức đến ngày đáo hạn?","howAnswer":"Nhập mệnh giá, lãi suất phiếu lãi hàng năm, số năm đáo hạn và tần suất phiếu lãi. Chọn giá theo lợi tức để chiết khấu phiếu giảm giá và các khoản thanh toán gốc theo lịch trình hoặc chọn lợi tức theo giá để giải quyết bằng số lợi tức danh nghĩa hàng năm phù hợp với giá thị trường.","privacyQuestion":"Đầu vào trái phiếu của tôi đã được tải lên chưa?","privacyAnswer":"Không. Phép tính chạy trong trình duyệt này. Đầu vào không được tải lên hoặc lưu bởi công cụ này.","howTo":["Chọn ước tính giá từ lợi tức hoặc giải quyết lợi nhuận từ giá thị trường.","Nhập mệnh giá, lãi suất coupon hàng năm, kỳ hạn và tần suất coupon.","Tính toán và so sánh kết quả với các giả định và đường cong được hiển thị."],"example":{"label":"Nạp trái phiếu lãi suất 5% có giá bằng mệnh giá","values":[]},"actions":{"calculate":"Tính giá trị trái phiếu","example":"Tải ví dụ về trái phiếu ngang giá","reset":"Đặt lại","copy":"Sao chép kết quả","result":"Ước tính trái phiếu"},"fields":{"mode":"Chế độ tính toán","priceMode":"Giá từ lợi suất","yieldMode":"Lợi nhuận từ giá thị trường","faceValue":"Giá trị mệnh giá","couponPercent":"Lãi suất trái phiếu hàng năm (%)","years":"Số năm đáo hạn","frequency":"Thanh toán phiếu giảm giá mỗi năm","annual":"Hàng năm (1)","semiannual":"Nửa năm một lần (2)","quarterly":"Hàng quý (4)","monthly":"Hàng tháng (12)","yieldPercent":"Sản lượng danh nghĩa hàng năm (%)","marketPrice":"Giá thị trường","accuracyNote":"Chỉ ước tính mang tính giáo dục, không phải lời khuyên đầu tư. Giả sử các phiếu lãi cố định được thanh toán theo định kỳ, tiền gốc được hoàn trả khi đáo hạn, lãi suất danh nghĩa hàng năm được cộng dồn theo tần suất phiếu lãi đã chọn và không có lãi tích lũy, thuế, phí, vỡ nợ, tính năng gọi vốn, lạm phát hoặc hiệu ứng tái đầu tư. Kỳ hạn phải là toàn bộ số kỳ phiếu lãi. Năng suất là số và gần đúng; xác nhận các điều khoản trái phiếu và quy ước thị trường một cách độc lập.","resultSummary":"Kết quả trái phiếu ước tính","yieldToMaturity":"Lợi suất đáo hạn (danh nghĩa hàng năm)","estimatedPrice":"Giá dự kiến","couponPayment":"Thanh toán phiếu giảm giá mỗi kỳ","currentYield":"Sản lượng hiện tại","totalCoupons":"Tổng số phiếu giảm giá theo lịch trình","premiumDiscount":"Premium / chiết khấu so với mệnh giá","periods":"Thời hạn phiếu giảm giá","chartTitle":"Đường cong giá-lợi suất ước tính","chartDescription":"Giá trái phiếu thường di chuyển theo hướng ngược lại với lợi suất. Đường cong sử dụng các giả định về phiếu lãi cố định và kỳ hạn đã nhập.","chartYield":"Lợi suất danh nghĩa hàng năm (%)","chartPrice":"Giá dự kiến"},"messages":{"calculated":"Ước tính trái phiếu đã được tính toán.","exampleLoaded":"Ví dụ được tải: phiếu giảm giá 5%, 5 năm, thanh toán hàng năm, giá ngang bằng.","checkInputs":"Kiểm tra giá trị trái phiếu và thử lại.","copied":"Đã sao chép kết quả.","copyUnavailable":"không có sẵn trong trình duyệt này.","invalidPeriods":"Chọn kỳ hạn có toàn bộ số kỳ phiếu lãi (tối đa 1.200).","yieldOutOfRange":"Giá thị trường nằm ngoài phạm vi lợi nhuận bằng số được hỗ trợ."},"additionalFaqs":[{"question":"Một trái phiếu lãi suất 5% có lãi suất bao nhiêu khi nó được định giá bằng mệnh giá?","answer":"Theo giả định của máy tính, một trái phiếu có lãi suất coupon hàng năm là 5%, giá thị trường bằng mệnh giá và thanh toán lãi coupon định kỳ có lãi suất danh nghĩa đến khi đáo hạn là 5%."},{"question":"Tại sao giá trái phiếu và lợi suất lại biến động ngược chiều nhau?","answer":"Giá trái phiếu là giá trị hiện tại của các phiếu lãi và tiền gốc theo lịch trình của nó. Lợi tức chiết khấu cao hơn làm giảm giá trị hiện tại đó; năng suất thấp hơn làm tăng nó."},{"question":"Lợi suất hiện tại có bằng lợi suất đáo hạn không?","answer":"Không. Lợi suất hiện tại là lãi suất hàng năm chia cho giá hiện tại. Lợi suất đến ngày đáo hạn cũng tính đến chênh lệch giá so với mệnh giá và thời gian còn lại, theo các giả định về dòng tiền đã nêu."},{"question":"Ước tính này có bao gồm lãi hoặc thuế tích lũy không?","answer":"Không. Nó chỉ mô hình hóa các khoản thanh toán lãi cố định thường xuyên và trả nợ gốc. Nó không tính toán giá sạch và giá bẩn, lãi tích lũy, thuế, phí, rủi ro tín dụng hoặc tùy chọn mua lại."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"it":{"copyLanguage":"it","name":"Calcolatore di obbligazioni","title":"Calcolatore di obbligazioni gratis | UsefulVerse","description":"Stima del prezzo o del rendimento delle obbligazioni alla scadenza in base alla cedola, al valore nominale e alla durata. Calcoli gratuiti e illimitati…","intro":"Stimare il prezzo di un'obbligazione a tasso fisso in base al suo rendimento o determinare un rendimento approssimativo alla scadenza a partire da un prezzo di mercato quotato. Rivedere le ipotesi e la curva prezzo-rendimento prima di utilizzare il risultato.","howQuestion":"Come posso calcolare il prezzo di un'obbligazione o il rendimento alla scadenza?","howAnswer":"Inserire il valore nominale, il tasso cedolare annuo, gli anni rimanenti e la frequenza della cedola. Scegli prezzo da rendimento per scontare la cedola programmata e i pagamenti del capitale oppure scegli rendimento da prezzo per risolvere numericamente il rendimento annuale nominale che corrisponde a un prezzo di mercato.","privacyQuestion":"I miei input obbligazionari vengono caricati?","privacyAnswer":"No. Il calcolo viene eseguito in questo browser. Gli input non vengono caricati o salvati da questo strumento.","howTo":["Scegli se stimare un prezzo dal rendimento o risolvere il rendimento da un prezzo di mercato.","Inserire il valore nominale, il tasso cedolare annuo, la scadenza e la frequenza della cedola.","Calcola e confronta il risultato con le ipotesi e la curva visualizzate."],"example":{"label":"Caricare un'obbligazione con cedola del 5% al prezzo pari","values":[]},"actions":{"calculate":"Calcola il valore dell'obbligazione","example":"Carica esempio di par-bond","reset":"Ripristina","copy":"Copia risultati","result":"Stima obbligazionaria"},"fields":{"mode":"Modalità di calcolo","priceMode":"Prezzo da un rendimento","yieldMode":"Rendimento da un prezzo di mercato","faceValue":"Valore facciale (par)","couponPercent":"Tasso cedolare annuo (%)","years":"Anni alla scadenza","frequency":"Pagamenti della cedola all'anno","annual":"Annuale (1)","semiannual":"Semestrale (2)","quarterly":"Trimestrale (4)","monthly":"Mensile (12)","yieldPercent":"Rendimento annuo nominale (%)","marketPrice":"Prezzo di mercato","accuracyNote":"Solo stima educativa, non consulenza sugli investimenti. Presuppone cedole fisse pagate a intervalli regolari, capitale rimborsato alla scadenza, rendimento annuo nominale composto alla frequenza cedolare selezionata e assenza di interessi maturati, tasse, commissioni, default, caratteristiche di call, inflazione o effetti di reinvestimento. La scadenza deve essere un numero intero di periodi cedolari. La resa è numerica e approssimativa; confermare i termini delle obbligazioni e le convenzioni di mercato in modo indipendente.","resultSummary":"Risultati obbligazionari stimati","yieldToMaturity":"Rendimento alla scadenza (nominale annuo)","estimatedPrice":"Prezzo stimato","couponPayment":"Pagamento della cedola per periodo","currentYield":"Rendimento attuale","totalCoupons":"Totale tagliandi programmati","premiumDiscount":"Premio/sconto al valore nominale","periods":"Periodi della cedola","chartTitle":"Curva prezzo-rendimento stimata","chartDescription":"Il prezzo delle obbligazioni generalmente si muove nella direzione opposta al rendimento. La curva utilizza le ipotesi di cedola fissa e scadenza inserite.","chartYield":"Rendimento annuo nominale (%)","chartPrice":"Prezzo stimato"},"messages":{"calculated":"Stima obbligazionaria calcolata.","exampleLoaded":"Esempio caricato: cedola 5%, 5 anni, pagamenti annuali, prezzo alla pari.","checkInputs":"Controllare i valori obbligazionari e riprovare.","copied":"Risultati copiati.","copyUnavailable":"La copia non è disponibile in questo browser.","invalidPeriods":"Scegliere una scadenza che contenga un numero intero di periodi cedolari (fino a 1.200).","yieldOutOfRange":"Il prezzo di mercato è al di fuori dell'intervallo di rendimento numerico supportato."},"additionalFaqs":[{"question":"Quale rendimento ha un'obbligazione con cedola del 5% quando ha un prezzo alla pari?","answer":"Secondo i presupposti del calcolatore, un'obbligazione con un tasso cedolare annuo del 5%, un prezzo di mercato pari al valore nominale e pagamenti cedolari regolari ha un rendimento nominale alla scadenza del 5%."},{"question":"Perché i prezzi e i rendimenti obbligazionari si muovono in direzioni opposte?","answer":"Il prezzo di un'obbligazione è il valore attuale delle sue cedole programmate e del capitale. Un rendimento di sconto più elevato riduce tale valore attuale; un rendimento inferiore lo aumenta."},{"question":"Il rendimento attuale è uguale al rendimento alla scadenza?","answer":"No. Il rendimento attuale è la cedola annuale divisa per il prezzo corrente. Il rendimento alla scadenza tiene conto anche della differenza di prezzo rispetto al valore nominale e al tempo rimanente, secondo le ipotesi di flusso di cassa indicate."},{"question":"Questa stima include gli interessi maturati o le tasse?","answer":"No. Modella solo pagamenti regolari di cedole fisse e rimborso del capitale. Non calcola il prezzo pulito rispetto a quello sporco, gli interessi maturati, le tasse, le commissioni, il rischio di credito o il riscatto facoltativo."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"zh_tw":{"copyLanguage":"zh_tw","name":"債券計算器","title":"債券計算器 免費 | UsefulVerse","description":"根據票面價值、面額和期限估算債券價格或到期收益率。免費、無限制的計算在您的瀏覽器本地運行。","intro":"根據收益率估算固定利率債券價格，或根據市場報價求解近似到期收益率。在使用結果之前檢查假設和價格-收益率曲線。","howQuestion":"如何計算債券價格或到期收益率？","howAnswer":"輸入面額、年票面利率、到期年限和票面頻率。选择收益率价格来贴现预定的息票和本金付款，或者选择价格收益率来数值求解与市场价格相匹配的名义年收益率。","privacyQuestion":"我的債券輸入是否已上傳？","privacyAnswer":"否。計算在此瀏覽器中運行。此工具不會上傳或儲存輸入。","howTo":["選擇是根據收益率估計價格還是根據市場價格求解收益率。","輸入面額、年票息率、期限和票息頻率。","計算結果並與顯示的假設和曲線進行比較。"],"example":{"label":"載入以票面價值定價的 5% 票息債券","values":[]},"actions":{"calculate":"計算債券價值","example":"載入普通債券範例","reset":"重設","copy":"複製結果","result":"債券預估"},"fields":{"mode":"計算模式","priceMode":"收益率的價格","yieldMode":"市場價格的報酬率","faceValue":"面值","couponPercent":"年票利率 (%)","years":"到期年數","frequency":"每年的票面支付","annual":"年度 (1)","semiannual":"半年一次 (2)","quarterly":"Quarterly (4)","monthly":"每月 (12)","yieldPercent":"名目年殖利率(%)","marketPrice":"市場價格","accuracyNote":"僅作教育評估，不構成投資建議。假设定期支付固定息票，到期时偿还本金，按所选息票频率复利名义年收益率，并且没有应计利息、税费、费用、违约、赎回特征、通货膨胀或再投资影响。到期日必須是息票期的整數倍。產量是數值和近似值；獨立確認債券條款和市場慣例。","resultSummary":"預計債券結果","yieldToMaturity":"到期收益率（名目年利率）","estimatedPrice":"預估價格","couponPayment":"每期票息支付","currentYield":"目前收益率","totalCoupons":"預定優惠券總數","premiumDiscount":"面額升貼水","periods":"優惠券期限","chartTitle":"預估價格-殖利率曲線","chartDescription":"債券價格通常與殖利率走勢相反。此曲線使用輸入的固定票息和期限假設。","chartYield":"名目年殖利率(%)","chartPrice":"預估價格"},"messages":{"calculated":"債券估算已計算。","exampleLoaded":"加載範例：5% 優惠券，5 年，每年付款，平價。","checkInputs":"檢查鍵值並重試。","copied":"結果已複製。","copyUnavailable":"複製在此瀏覽器中不可用。","invalidPeriods":"選擇包含整數個票面利率（最多 1,200 個）的到期日。","yieldOutOfRange":"市場價格超出支援的數值收益率範圍。"},"additionalFaqs":[{"question":"5%票息債券以面額定價時的收益率是多少？","answer":"在計算器假設下，年票面利率為 5%、市場價格等於票面價值、定期支付息票的債券的名目到期收益率為 5%。"},{"question":"為什麼債券價格和殖利率走勢相反？","answer":"債券價格是其預定票息和本金的現值。較高的折現率會降低現值；較低的產量會增加它。"},{"question":"目前殖利率與到期殖利率相同嗎？","answer":"否。 當前收益率是年息除以當前價格。在規定的現金流量假設下，到期收益率也考慮了與面額和剩餘時間的價格差異。"},{"question":"該估算是否包含應計利息或稅金？","answer":"否。僅模擬定期固定票息支付和本金償還。它不計算乾淨價格與髒價格、應計利息、稅金、費用、信用風險或可選贖回。"}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"bg":{"copyLanguage":"bg","name":"Калкулатор за облигации","title":"Калкулатор за облигации безплатно | UsefulVerse","description":"Приблизителна цена на облигация или доходност до падежа от купон, номинална стойност и срок. Безплатни, неограничени изчисления се изпълняват локално във…","intro":"Оценете цената на облигация с фиксиран лихвен процент от нейната доходност или разрешете приблизителна доходност до падежа от котирана пазарна цена. Прегледайте предположенията и кривата цена-доходност, преди да използвате резултата.","howQuestion":"Как да изчисля цена на облигация или доходност до падежа?","howAnswer":"Въведете номиналната стойност, годишния купонен процент, годините до падежа и честотата на купона. Изберете цена от доходност, за да намалите планираните плащания по купон и главница, или изберете доходност от цена, за да решите числено номиналната годишна доходност, която съответства на пазарна цена.","privacyQuestion":"Качени ли са входовете ми за облигации?","privacyAnswer":"Не. Изчислението се изпълнява в този браузър. Входящите данни не се качват или запазват от този инструмент.","howTo":["Изберете дали да оцените цена от доходност или да решите доходност от пазарна цена.","Въведете номинална стойност, годишен процент на купона, падеж и честота на купона.","Изчислете и сравнете резултата с показаните допускания и крива."],"example":{"label":"Заредете 5% купонна облигация на цена по номинална стойност","values":[]},"actions":{"calculate":"Изчислете стойността на облигацията","example":"Заредете пример за номинална облигация","reset":"Нулирайте","copy":"Копиране на резултатите","result":"Оценка на облигациите"},"fields":{"mode":"Режим на изчисление","priceMode":"Цена от доходност","yieldMode":"Доходност от пазарна цена","faceValue":"Номинална (номинална) стойност","couponPercent":"Годишен купонен процент (%)","years":"Години до падеж","frequency":"Купонни плащания на година","annual":"Годишен (1)","semiannual":"На шест месеца (2)","quarterly":"Тримесечно (4)","monthly":"Месечно (12)","yieldPercent":"Номинална годишна доходност (%)","marketPrice":"Пазарна цена","accuracyNote":"Само образователна оценка, а не инвестиционен съвет. Предполага фиксирани купони, изплащани на редовни интервали, главница, изплатена на падежа, номинална годишна доходност, съставена при избраната честота на купони, и без натрупани лихви, данъци, такси, неизпълнение, функции за изплащане, инфлация или ефекти на реинвестиране. Падежът трябва да бъде цял брой купонни периоди. Добивът е числов и приблизителен; потвърждава независимо условията на облигациите и пазарните конвенции.","resultSummary":"Очаквани резултати за облигации","yieldToMaturity":"Доходност до падежа (номинална годишна)","estimatedPrice":"Прогнозна цена","couponPayment":"Плащане на купон за период","currentYield":"Текуща доходност","totalCoupons":"Общо планирани купони","premiumDiscount":"Премиум / отстъпка спрямо номиналната стойност","periods":"Купонни периоди","chartTitle":"Очаквана крива цена-доходност","chartDescription":"Цената на облигациите обикновено се движи в посока, обратна на доходността. Кривата използва въведените предположения за фиксиран купон и падеж.","chartYield":"Номинална годишна доходност (%)","chartPrice":"Прогнозна цена"},"messages":{"calculated":"Изчислена оценка на облигациите.","exampleLoaded":"Зареден пример: 5% купон, 5 години, годишни плащания, цена по номинал.","checkInputs":"Проверете стойностите на облигацията и опитайте отново.","copied":"Резултатите са копирани.","copyUnavailable":"Копирането не е налично в този браузър.","invalidPeriods":"Изберете падеж, който съдържа цял брой купонни периоди (до 1200).","yieldOutOfRange":"Пазарната цена е извън поддържания числен диапазон на доходност."},"additionalFaqs":[{"question":"Каква доходност има 5% купонна облигация, когато е оценена по номинал?","answer":"Съгласно предположенията на калкулатора, облигация с 5% годишен купонен процент, пазарна цена, равна на номиналната стойност и редовни купонни плащания, има номинална доходност до падежа от 5%."},{"question":"Защо цените и доходността на облигациите се движат в противоположни посоки?","answer":"Цената на облигация е настоящата стойност на нейните планирани купони и главница. По-високата доходност на отстъпката намалява настоящата стойност; по-нисък добив го увеличава."},{"question":"Текущата доходност същата ли е като доходността до падежа?","answer":"Не. Текущата доходност е годишният купон, разделен на текущата цена. Доходността до падежа също така отчита ценовата разлика спрямо номиналната стойност и оставащото време, съгласно посочените допускания за паричния поток."},{"question":"Тази оценка включва ли натрупани лихви или данъци?","answer":"Не. Той моделира редовни плащания с фиксиран купон и само погасяване на главницата. Той не изчислява чиста срещу мръсна цена, натрупани лихви, данъци, такси, кредитен риск или незадължително обратно изкупуване."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"ca":{"copyLanguage":"ca","name":"Calculadora de bons","title":"Calculadora de bons gratuït | UsefulVerse","description":"Estimar el preu del bon o el rendiment fins al venciment a partir del cupó, el valor nominal i el termini. Els càlculs gratuïts i il·limitats s'executen…","intro":"Estima el preu d'un bon de tipus fix a partir del seu rendiment o resol un rendiment aproximat fins al venciment a partir d'un preu de mercat cotitzat. Reviseu les hipòtesis i la corba preu-rendiment abans d'utilitzar el resultat.","howQuestion":"Com puc calcular el preu d'un bon o el rendiment fins al venciment?","howAnswer":"Introduïu el valor nominal, la taxa anual del cupó, els anys fins al venciment i la freqüència del cupó. Trieu el preu a partir del rendiment per descomptar el cupó programat i els pagaments de principal, o trieu el rendiment a partir del preu per resoldre numèricament el rendiment anual nominal que coincideixi amb un preu de mercat.","privacyQuestion":"S'han penjat les meves entrades de bons?","privacyAnswer":"No. El càlcul s'executa en aquest navegador. Aquesta eina no carrega ni desa les entrades.","howTo":["Trieu si voleu estimar un preu a partir del rendiment o resoldre el rendiment a partir d'un preu de mercat.","Introduïu el valor nominal, la taxa anual del cupó, el venciment i la freqüència del cupó.","Calculeu i compareu el resultat amb les suposicions i la corba que es mostren."],"example":{"label":"Carregueu un bon de cupó del 5% amb un preu igual a","values":[]},"actions":{"calculate":"Calcula el valor de l'enllaç","example":"Exemple d'enllaç parell de càrrega","reset":"Restableix","copy":"Copia els resultats","result":"Estimació de bons"},"fields":{"mode":"Mode de càlcul","priceMode":"Preu a partir d'un rendiment","yieldMode":"Rendiment a partir d'un preu de mercat","faceValue":"Valor facial (par)","couponPercent":"Taxa anual del cupó (%)","years":"Anys fins al venciment","frequency":"Pagaments de cupó per any","annual":"Anual (1)","semiannual":"Semestral (2)","quarterly":"Trimestral (4)","monthly":"Mensual (12)","yieldPercent":"Rendiment nominal anual (%)","marketPrice":"Preu de mercat","accuracyNote":"Només pressupost educatiu, no consell d'inversió. Assumeix cupons fixos pagats a intervals regulars, principal reemborsat al venciment, rendiment anual nominal compost amb la freqüència de cupó seleccionada i sense efectes d'interès, impostos, comissions, impagament, trucades, inflació o reinversió acumulats. El venciment ha de ser un nombre sencer de períodes de cupó. El rendiment és numèric i aproximat; confirmar els termes dels bons i les convencions del mercat de manera independent.","resultSummary":"Resultats estimats dels bons","yieldToMaturity":"Rendiment fins al venciment (nominal anual)","estimatedPrice":"Preu estimat","couponPayment":"Pagament del cupó per període","currentYield":"Rendiment actual","totalCoupons":"Total de cupons programats","premiumDiscount":"Premium/descompte al valor nominal","periods":"Períodes de cupó","chartTitle":"Corba estimada preu-rendiment","chartDescription":"El preu dels bons generalment es mou en la direcció oposada al rendiment. La corba utilitza el cupó fix introduït i les hipòtesis de venciment.","chartYield":"Rendiment anual nominal (%)","chartPrice":"Preu estimat"},"messages":{"calculated":"Estimació de bons calculada.","exampleLoaded":"Exemple carregat: cupó del 5%, 5 anys, pagaments anuals, preu a la paritat.","checkInputs":"Comproveu els valors de l'enllaç i torneu-ho a provar.","copied":"Resultats copiats.","copyUnavailable":"La còpia no està disponible en aquest navegador.","invalidPeriods":"Trieu un venciment que contingui un nombre sencer de períodes de cupó (fins a 1.200).","yieldOutOfRange":"El preu de mercat està fora del rang de rendiment numèric admès."},"additionalFaqs":[{"question":"Quin rendiment té un bon de cupó del 5% quan té un preu igual?","answer":"Segons els supòsits de la calculadora, un bon amb una taxa de cupó anual del 5%, un preu de mercat igual al valor nominal i pagaments regulars de cupó té un rendiment nominal fins al venciment del 5%."},{"question":"Per què els preus i els rendiments dels bons es mouen en direccions oposades?","answer":"El preu d'un bon és el valor actual dels seus cupons i principal programats. Un rendiment de descompte més alt redueix aquest valor actual; un rendiment inferior l'augmenta."},{"question":"El rendiment actual és el mateix que el rendiment fins al venciment?","answer":"No. El rendiment actual és el cupó anual dividit pel preu actual. El rendiment fins al venciment també té en compte la diferència de preu respecte al valor nominal i el temps restant, segons les hipòtesis de flux d'efectiu establertes."},{"question":"Aquesta estimació inclou interessos o impostos acumulats?","answer":"No. Modela els pagaments regulars de cupó fix i només el reemborsament del capital. No calcula el preu net versus brut, els interessos acumulats, els impostos, les comissions, el risc de crèdit o l'amortització opcional."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"nl":{"copyLanguage":"nl","name":"Obligatiecalculator","title":"Obligatiecalculator gratis | UsefulVerse","description":"Schat de koers van een obligatie of het rendement tot de vervaldatum op basis van coupon, nominale waarde en looptijd. Gratis, onbeperkte berekeningen worden…","intro":"Schat de prijs van een obligatie met een vaste rente op basis van het rendement ervan, of los een geschat rendement op tot de vervaldag op basis van een genoteerde marktprijs. Controleer de aannames en de koers-rendementscurve voordat u het resultaat gebruikt.","howQuestion":"Hoe bereken ik de prijs van een obligatie of het rendement tot de vervaldatum?","howAnswer":"Voer de nominale waarde, de jaarlijkse couponrente, het aantal jaren tot de vervaldatum en de couponfrequentie in. Kies prijs-van-rendement om korting te geven op de geplande coupon- en hoofdsombetalingen, of kies rendement-van-prijs om het nominale jaarlijkse rendement dat overeenkomt met een marktprijs numeriek op te lossen.","privacyQuestion":"Worden mijn obligatie-invoer geüpload?","privacyAnswer":"Nee. De berekening wordt in deze browser uitgevoerd. Invoer wordt door deze tool niet geüpload of opgeslagen.","howTo":["Kies of u een prijs wilt schatten op basis van de opbrengst of de opbrengst wilt oplossen op basis van een marktprijs.","Voer de nominale waarde, de jaarlijkse couponrente, de looptijd en de couponfrequentie in.","Bereken en vergelijk het resultaat met de weergegeven aannames en curve."],"example":{"label":"Laad een obligatie met een coupon van 5%, geprijsd op pari","values":[]},"actions":{"calculate":"Bereken de obligatiewaarde","example":"Voorbeeld van een par-bond laden","reset":"Reset","copy":"Kopieer resultaten","result":"Schatting van de obligaties"},"fields":{"mode":"Berekeningsmodus","priceMode":"Prijs vanaf een opbrengst","yieldMode":"Opbrengst van een marktprijs","faceValue":"Gezichtswaarde (par.)","couponPercent":"Jaarlijkse couponrente (%)","years":"Aantal jaren tot einde looptijd","frequency":"Couponbetalingen per jaar","annual":"Jaarlijks (1)","semiannual":"Halfjaarlijks (2)","quarterly":"Driemaandelijks (4)","monthly":"Maandelijks (12)","yieldPercent":"Nominaal jaarrendement (%)","marketPrice":"Marktprijs","accuracyNote":"Alleen educatieve schatting, geen beleggingsadvies. Er wordt uitgegaan van vaste coupons die met regelmatige tussenpozen worden betaald, de hoofdsom die op de vervaldag wordt terugbetaald, het nominale jaarlijkse rendement dat wordt samengesteld op basis van de geselecteerde couponfrequentie, en geen opgebouwde rente, belastingen, vergoedingen, wanbetalingen, call-functies, inflatie of herinvesteringseffecten. De looptijd moet een geheel aantal couponperioden bedragen. De opbrengst is numeriek en bij benadering; onafhankelijk de obligatievoorwaarden en marktconventies bevestigen.","resultSummary":"Geschatte obligatieresultaten","yieldToMaturity":"Rendement tot einde looptijd (nominaal jaarlijks)","estimatedPrice":"Geschatte prijs","couponPayment":"Couponbetaling per periode","currentYield":"Huidig rendement","totalCoupons":"Totaal geplande coupons","premiumDiscount":"Premium/korting tot nominale waarde","periods":"Couponperiodes","chartTitle":"Geschatte prijs-rendementscurve","chartDescription":"De koers van obligaties beweegt doorgaans in de tegenovergestelde richting van het rendement. De curve maakt gebruik van de ingevoerde vaste coupon- en looptijdaannames.","chartYield":"Nominaal jaarrendement (%)","chartPrice":"Geschatte prijs"},"messages":{"calculated":"Schatting van de obligaties berekend.","exampleLoaded":"Voorbeeld geladen: 5% coupon, 5 jaar, jaarlijkse betalingen, prijs a pari.","checkInputs":"Controleer de obligatiewaarden en probeer het opnieuw.","copied":"Resultaten gekopieerd.","copyUnavailable":"Kopiëren is niet beschikbaar in deze browser.","invalidPeriods":"Kies een looptijd die een geheel aantal couponperioden bevat (tot 1.200).","yieldOutOfRange":"De marktprijs ligt buiten het ondersteunde numerieke rendementsbereik."},"additionalFaqs":[{"question":"Welk rendement heeft een obligatie met een coupon van 5% als deze tegen pari geprijsd is?","answer":"Volgens de aannames van de rekenmachine heeft een obligatie met een jaarlijkse couponrente van 5%, een marktprijs gelijk aan de nominale waarde en regelmatige couponbetalingen een nominaal rendement tot de vervaldatum van 5%."},{"question":"Waarom bewegen de koersen en rendementen van obligaties in tegengestelde richtingen?","answer":"De prijs van een obligatie is de contante waarde van de geplande coupons en hoofdsom. Een hoger kortingsrendement verlaagt die contante waarde; een lagere opbrengst verhoogt deze."},{"question":"Is het huidige rendement hetzelfde als het rendement tot einde looptijd?","answer":"Nee. Het huidige rendement is de jaarlijkse coupon gedeeld door de huidige prijs. Het rendement tot de vervaldatum houdt ook rekening met het prijsverschil met de nominale waarde en de resterende tijd, op basis van de vermelde kasstroomaannames."},{"question":"Is deze schatting inclusief opgelopen rente of belastingen?","answer":"Nee. Het modelleert alleen reguliere vaste couponbetalingen en aflossing van de hoofdsom. Het berekent geen schone versus vuile prijs, opgebouwde rente, belastingen, kosten, kredietrisico of optionele aflossing."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"el":{"copyLanguage":"el","name":"Υπολογιστής ομολόγων","title":"Υπολογιστής ομολόγων δωρεάν | UsefulVerse","description":"Υπολογίστε την τιμή ή την απόδοση του ομολόγου έως τη λήξη από το κουπόνι, την ονομαστική αξία και τη διάρκεια. Δωρεάν, απεριόριστοι υπολογισμοί εκτελούνται…","intro":"Υπολογίστε μια τιμή ομολόγου σταθερού επιτοκίου από την απόδοσή του ή λύστε μια κατά προσέγγιση απόδοση έως τη λήξη από μια τιμή αγοράς. Ελέγξτε τις υποθέσεις και την καμπύλη τιμής-απόδοσης πριν χρησιμοποιήσετε το αποτέλεσμα.","howQuestion":"Πώς μπορώ να υπολογίσω μια τιμή ομολόγου ή την απόδοση μέχρι τη λήξη;","howAnswer":"Εισαγάγετε την ονομαστική αξία, το ετήσιο επιτόκιο κουπονιού, τα έτη έως τη λήξη και τη συχνότητα του κουπονιού. Επιλέξτε τιμή-από-απόδοση για έκπτωση στο προγραμματισμένο κουπόνι και πληρωμές κεφαλαίου ή επιλέξτε απόδοση από τιμή για να λύσετε αριθμητικά την ονομαστική ετήσια απόδοση που αντιστοιχεί σε τιμή αγοράς.","privacyQuestion":"Έχουν μεταφορτωθεί οι εισροές ομολόγων μου;","privacyAnswer":"Όχι. Ο υπολογισμός εκτελείται σε αυτό το πρόγραμμα περιήγησης. Οι είσοδοι δεν μεταφορτώνονται ούτε αποθηκεύονται από αυτό το εργαλείο.","howTo":["Επιλέξτε εάν θα εκτιμήσετε μια τιμή από την απόδοση ή θα λύσετε την απόδοση από μια τιμή αγοράς.","Εισαγάγετε την ονομαστική αξία, το ετήσιο επιτόκιο κουπονιού, τη λήξη και τη συχνότητα κουπονιού.","Υπολογίστε και συγκρίνετε το αποτέλεσμα με τις εμφανιζόμενες παραδοχές και την καμπύλη."],"example":{"label":"Φορτώστε ένα ομόλογο κουπονιού 5% στην τιμή","values":[]},"actions":{"calculate":"Υπολογίστε την τιμή ομολόγου","example":"Φόρτωση παραδείγματος ομολόγου","reset":"Επαναφορά","copy":"Αντιγραφή αποτελεσμάτων","result":"Εκτίμηση ομολόγου"},"fields":{"mode":"Τρόπος υπολογισμού","priceMode":"Τιμή από απόδοση","yieldMode":"Απόδοση από τιμή αγοράς","faceValue":"Όψη (παρ) τιμή","couponPercent":"Ετήσιο επιτόκιο κουπονιού (%)","years":"Έτη έως τη λήξη","frequency":"Πληρωμές κουπονιών ανά έτος","annual":"Ετήσιο (1)","semiannual":"Εξαμηνιαία (2)","quarterly":"Τριμηνιαία (4)","monthly":"Μηνιαίο (12)","yieldPercent":"Ονομαστική ετήσια απόδοση (%)","marketPrice":"Τιμή αγοράς","accuracyNote":"Εκπαιδευτική εκτίμηση μόνο, όχι επενδυτικές συμβουλές. Προϋποθέτει σταθερά κουπόνια που καταβάλλονται σε τακτά χρονικά διαστήματα, αποπληρωμή κεφαλαίου στη λήξη, ονομαστική ετήσια απόδοση με την επιλεγμένη συχνότητα κουπονιών και χωρίς δεδουλευμένους τόκους, φόρους, τέλη, χρεοκοπία, χαρακτηριστικά κλήσεων, πληθωρισμό ή επανεπένδυση. Η λήξη πρέπει να είναι ένας ακέραιος αριθμός περιόδων κουπονιών. Η απόδοση είναι αριθμητική και κατά προσέγγιση. επιβεβαιώνουν ανεξάρτητα τους όρους των ομολόγων και τις συμβάσεις της αγοράς.","resultSummary":"Εκτιμώμενα αποτελέσματα ομολόγων","yieldToMaturity":"Απόδοση έως τη λήξη (ονομαστική ετήσια)","estimatedPrice":"Εκτιμώμενη τιμή","couponPayment":"Πληρωμή κουπονιού ανά περίοδο","currentYield":"Τρέχουσα απόδοση","totalCoupons":"Σύνολο προγραμματισμένων κουπονιών","premiumDiscount":"Premium / έκπτωση στην ονομαστική αξία","periods":"Περίοδοι κουπονιών","chartTitle":"Εκτιμώμενη καμπύλη τιμής-απόδοσης","chartDescription":"κινείται γενικά προς την αντίθετη κατεύθυνση από την απόδοση. Η καμπύλη χρησιμοποιεί τα εισαγόμενα σταθερά κουπόνια και παραδοχές λήξης.","chartYield":"Ονομαστική ετήσια απόδοση (%)","chartPrice":"Εκτιμώμενη τιμή"},"messages":{"calculated":".","exampleLoaded":"Παράδειγμα φόρτωσης: κουπόνι 5%, 5 χρόνια, ετήσιες πληρωμές, τιμή στο άρ.","checkInputs":"Ελέγξτε τις τιμές δεσμών και δοκιμάστε ξανά.","copied":"Τα αποτελέσματα αντιγράφηκαν.","copyUnavailable":"δεν είναι διαθέσιμο σε αυτό το πρόγραμμα περιήγησης.","invalidPeriods":"Επιλέξτε μια λήξη που περιέχει έναν ακέραιο αριθμό περιόδων κουπονιών (έως 1.200).","yieldOutOfRange":"Η τιμή αγοράς είναι εκτός του υποστηριζόμενου εύρους αριθμητικής απόδοσης."},"additionalFaqs":[{"question":"Τι απόδοση έχει ένα ομόλογο κουπονιού 5% όταν τιμολογείται στο άρτιο;","answer":"Σύμφωνα με τις υποθέσεις της αριθμομηχανής, ένα ομόλογο με ετήσιο επιτόκιο κουπονιού 5%, τιμή αγοράς ίση με την ονομαστική αξία και τακτικές πληρωμές κουπονιών έχει ονομαστική απόδοση έως τη λήξη 5%."},{"question":"Γιατί οι τιμές και οι αποδόσεις των ομολόγων κινούνται προς αντίθετες κατευθύνσεις;","answer":"Μια τιμή ομολόγου είναι η παρούσα αξία των προγραμματισμένων κουπονιών και του κεφαλαίου του. Μια υψηλότερη απόδοση έκπτωσης μειώνει αυτήν την παρούσα αξία. χαμηλότερη απόδοση την αυξάνει."},{"question":"Η τρέχουσα απόδοση είναι ίδια με την απόδοση μέχρι τη λήξη;","answer":"Όχι. Η τρέχουσα απόδοση είναι το ετήσιο κουπόνι διαιρεμένο με την τρέχουσα τιμή. Η απόδοση μέχρι τη λήξη λαμβάνει επίσης υπόψη τη διαφορά τιμής από την ονομαστική αξία και τον υπολειπόμενο χρόνο, σύμφωνα με τις αναφερόμενες παραδοχές ταμειακών ροών."},{"question":"Αυτή η εκτίμηση περιλαμβάνει δεδουλευμένους τόκους ή φόρους;","answer":"Όχι. Μοντελοποιεί μόνο τις κανονικές πληρωμές με σταθερό κουπόνι και την εξόφληση του κεφαλαίου. Δεν υπολογίζει καθαρή έναντι βρώμικη τιμή, δεδουλευμένους τόκους, φόρους, προμήθειες, πιστωτικό κίνδυνο ή προαιρετική εξαργύρωση."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"ms":{"copyLanguage":"ms","name":"Bond Calculator","title":"Bond Calculator percuma | UsefulVerse","description":"Anggarkan harga bon atau hasil sehingga matang daripada kupon, nilai muka dan tempoh. Pengiraan percuma dan tanpa had dijalankan secara setempat dalam…","intro":"Anggarkan harga bon kadar tetap daripada hasilnya, atau selesaikan anggaran hasil hingga matang daripada harga pasaran yang disebut harga. Semak andaian dan keluk harga-hasil sebelum menggunakan hasilnya.","howQuestion":"Bagaimanakah cara saya mengira harga bon atau hasil sehingga matang?","howAnswer":"Masukkan nilai muka, kadar kupon tahunan, tahun hingga matang dan kekerapan kupon. Pilih harga daripada hasil untuk mendiskaunkan kupon berjadual dan pembayaran pokok, atau pilih hasil daripada harga untuk menyelesaikan secara numerik hasil tahunan nominal yang sepadan dengan harga pasaran.","privacyQuestion":"Adakah input bon saya dimuat naik?","privacyAnswer":"No. Pengiraan berjalan dalam pelayar ini. Input tidak dimuat naik atau disimpan oleh alat ini.","howTo":["Pilih sama ada untuk menganggarkan harga daripada hasil atau menyelesaikan hasil daripada harga pasaran.","Masukkan nilai muka, kadar kupon tahunan, tempoh matang dan kekerapan kupon.","Kira dan bandingkan keputusan dengan andaian dan lengkung yang dipaparkan."],"example":{"label":"Muatkan bon kupon 5% berharga pada par","values":[]},"actions":{"calculate":"Kira nilai bon","example":"Muatkan contoh par-bon","reset":"Tetapkan Semula","copy":"Salin keputusan","result":"Bond estimate"},"fields":{"mode":"Mod pengiraan","priceMode":"Harga daripada hasil","yieldMode":"Hasil daripada harga pasaran","faceValue":"Nilai muka (par)","couponPercent":"Kadar kupon tahunan (%)","years":"Tahun hingga matang","frequency":"setahun","annual":"Tahunan (1)","semiannual":"Separuh Tahun (2)","quarterly":"Suku Tahun (4)","monthly":"Bulanan (12)","yieldPercent":"Hasil tahunan nominal (%)","marketPrice":"Harga pasaran","accuracyNote":"Anggaran pendidikan sahaja, bukan nasihat pelaburan. Andaikan kupon tetap dibayar pada selang masa yang tetap, prinsipal dibayar balik pada tempoh matang, hasil tahunan nominal dikompaun pada kekerapan kupon yang dipilih, dan tiada faedah terakru, cukai, yuran, lalai, ciri panggilan, inflasi atau kesan pelaburan semula. Kematangan mestilah sejumlah keseluruhan tempoh kupon. Hasil adalah berangka dan anggaran; mengesahkan terma bon dan konvensyen pasaran secara bebas.","resultSummary":"Anggaran keputusan bon","yieldToMaturity":"Hasil hingga matang (nominal tahunan)","estimatedPrice":"Anggaran harga","couponPayment":"Bayaran kupon setiap tempoh","currentYield":"Hasil semasa","totalCoupons":"Jumlah kupon berjadual","premiumDiscount":"Premium / diskaun kepada nilai muka","periods":"Tempoh kupon","chartTitle":"Anggaran harga-keluk hasil","chartDescription":"biasanya bergerak ke arah yang bertentangan untuk menghasilkan. Keluk menggunakan kupon tetap yang dimasukkan dan andaian kematangan.","chartYield":"Hasil tahunan nominal (%)","chartPrice":"Anggaran harga"},"messages":{"calculated":"dikira.","exampleLoaded":"Contoh dimuatkan: kupon 5%, 5 tahun, bayaran tahunan, harga pada par.","checkInputs":"Semak nilai bon dan cuba lagi.","copied":"disalin.","copyUnavailable":"tidak tersedia dalam penyemak imbas ini.","invalidPeriods":"Pilih tempoh matang yang mengandungi sejumlah keseluruhan tempoh kupon (sehingga 1,200).","yieldOutOfRange":"Harga pasaran berada di luar julat hasil berangka yang disokong."},"additionalFaqs":[{"question":"Apakah hasil bon kupon 5% apabila ia berharga pada par?","answer":"Di bawah andaian kalkulator, bon dengan kadar kupon tahunan 5%, harga pasaran yang sama dengan nilai muka dan pembayaran kupon biasa mempunyai hasil nominal hingga matang sebanyak 5%."},{"question":"Mengapa harga dan hasil bon bergerak ke arah yang bertentangan?","answer":"Harga bon ialah nilai semasa kupon dan prinsipalnya yang dijadualkan. Hasil diskaun yang lebih tinggi mengurangkan nilai semasa itu; hasil yang lebih rendah meningkatkannya."},{"question":"Adakah hasil semasa sama dengan hasil hingga matang?","answer":"No. Hasil semasa ialah kupon tahunan dibahagikan dengan harga semasa. Hasil sehingga matang juga mengambil kira perbezaan harga daripada nilai muka dan baki masa, di bawah andaian aliran tunai yang dinyatakan."},{"question":"Adakah anggaran ini termasuk faedah atau cukai terakru?","answer":"Tidak. Ia memodelkan pembayaran kupon tetap biasa dan pembayaran balik prinsipal sahaja. Ia tidak mengira harga bersih-berbanding-kotor, faedah terakru, cukai, yuran, risiko kredit atau penebusan pilihan."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"pl":{"copyLanguage":"pl","name":"Bond Calculator","title":"Bond Calculator za darmo | UsefulVerse","description":"Oszacuj cenę obligacji lub rentowność do terminu zapadalności na podstawie kuponu, wartości nominalnej i terminu. Bezpłatne, nieograniczone obliczenia…","intro":"Oszacuj cenę obligacji o stałym oprocentowaniu na podstawie jej rentowności lub oblicz przybliżoną rentowność do terminu zapadalności na podstawie notowanej ceny rynkowej. Przed wykorzystaniem wyniku przejrzyj założenia i krzywą ceny do wydajności.","howQuestion":"Jak obliczyć cenę obligacji lub rentowność do terminu zapadalności?","howAnswer":"Wprowadź wartość nominalną, roczną stopę kuponu, liczbę lat pozostałych do zapadalności i częstotliwość kuponu. Wybierz cenę z rentowności, aby zdyskontować zaplanowane płatności kuponowe i kapitałowe, lub wybierz rentowność z ceny, aby numerycznie rozwiązać nominalną roczną stopę zwrotu odpowiadającą cenie rynkowej.","privacyQuestion":"Czy moje dane wejściowe obligacji zostały przesłane?","privacyAnswer":"Nie. Obliczenia są uruchamiane w tej przeglądarce. Dane wejściowe nie są przesyłane ani zapisywane przez to narzędzie.","howTo":["Wybierz, czy oszacować cenę na podstawie uzysku, czy rozwiązać uzysk na podstawie ceny rynkowej.","Wprowadź wartość nominalną, roczną stopę kuponu, termin zapadalności i częstotliwość kuponu.","Oblicz i porównaj wynik z wyświetlonymi założeniami i krzywą."],"example":{"label":"Załaduj 5% obligację kuponową o cenie nominalnej","values":[]},"actions":{"calculate":"Oblicz wartość obligacji","example":"Załaduj przykład wiązania par","reset":"Zresetuj","copy":"Kopiuj wyniki","result":"Szacunek obligacji"},"fields":{"mode":"Tryb obliczeniowy","priceMode":"Cena z plonu","yieldMode":"Rentowność z ceny rynkowej","faceValue":"Wartość czołowa (par)","couponPercent":"Roczna stopa kuponu (%)","years":"Lata do terminu zapadalności","frequency":"Płatności kuponowe rocznie","annual":"Roczne (1)","semiannual":"Półroczne (2)","quarterly":"Kwartalnie (4)","monthly":"Miesięcznie (12)","yieldPercent":"Nominalna roczna wydajność (%)","marketPrice":"Cena rynkowa","accuracyNote":"Tylko szacunki edukacyjne, a nie porady inwestycyjne. Zakłada stałe kupony płacone w regularnych odstępach czasu, kwotę kapitału spłacaną w terminie zapadalności, nominalną roczną stopę zwrotu składaną z wybraną częstotliwością kuponów oraz brak naliczonych odsetek, podatków, opłat, niewykonania zobowiązania, funkcji kupna, inflacji lub skutków reinwestycji. Termin zapadalności musi być całkowitą liczbą okresów kuponowych. Wydajność jest liczbowa i przybliżona; niezależnie potwierdzaj warunki obligacji i konwencje rynkowe.","resultSummary":"Szacunkowe wyniki obligacji","yieldToMaturity":"Rentowność do terminu zapadalności (nominalna roczna)","estimatedPrice":"Szacunkowa cena","couponPayment":"Płatność kuponem na okres","currentYield":"Bieżąca rentowność","totalCoupons":"Łączna liczba zaplanowanych kuponów","premiumDiscount":"Premia / rabat do wartości nominalnej","periods":"Okresy kuponów","chartTitle":"Szacowana krzywa ceny do wydajności","chartDescription":"Cena obligacji generalnie porusza się w kierunku przeciwnym do rentowności. Krzywa wykorzystuje wprowadzone założenia dotyczące stałego kuponu i terminu zapadalności.","chartYield":"Nominalna roczna wydajność (%)","chartPrice":"Szacunkowa cena"},"messages":{"calculated":".","exampleLoaded":"Załadowano przykład: kupon 5%, 5 lat, płatności roczne, cena po cenie nominalnej.","checkInputs":"Sprawdź wartości wiązań i spróbuj ponownie.","copied":"Wyniki skopiowane.","copyUnavailable":"jest niedostępna w tej przeglądarce.","invalidPeriods":"Wybierz termin zapadalności zawierający całą liczbę okresów kuponowych (do 1200).","yieldOutOfRange":"Cena rynkowa wykracza poza obsługiwany numeryczny zakres rentowności."},"additionalFaqs":[{"question":"Jaką rentowność daje 5% obligacja kuponowa, jeśli jest wyceniona po cenie nominalnej?","answer":"Zgodnie z założeniami kalkulatora obligacja o rocznej stopie kuponu wynoszącej 5%, cenie rynkowej równej wartości nominalnej i regularnych płatnościach kuponowych ma nominalną rentowność do terminu zapadalności wynoszącą 5%."},{"question":"Dlaczego ceny obligacji i rentowności zmieniają się w przeciwnych kierunkach?","answer":"Cena obligacji to bieżąca wartość jej zaplanowanych kuponów i kapitału. Wyższa stopa dyskonta zmniejsza tę wartość bieżącą; niższy plon zwiększa go."},{"question":"Czy bieżąca rentowność jest taka sama jak rentowność do terminu zapadalności?","answer":"Nie. Bieżąca rentowność to kupon roczny podzielony przez aktualną cenę. Rentowność do terminu zapadalności uwzględnia także różnicę ceny w stosunku do wartości nominalnej oraz pozostały czas, zgodnie z przyjętymi założeniami dotyczącymi przepływów pieniężnych."},{"question":"Czy szacunki obejmują naliczone odsetki lub podatki?","answer":"Nie. Modeluje jedynie regularne płatności o stałym kuponie i spłatę kapitału. Nie oblicza ceny czystej kontra brudnej, naliczonych odsetek, podatków, opłat, ryzyka kredytowego ani opcjonalnego wykupu."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"sv":{"copyLanguage":"sv","name":"Obligationsräknare","title":"Obligationsräknare gratis | UsefulVerse","description":"Uppskatta obligationspriset eller avkastning till förfallotid från kupong, nominellt värde och löptid. Gratis, obegränsade beräkningar körs lokalt i din…","intro":"Beräkna ett obligationspris med fast ränta från dess avkastning, eller lös en ungefärlig avkastning till förfall från ett noterat marknadspris. Gå igenom antagandena och kurs-avkastningskurvan innan du använder resultatet.","howQuestion":"Hur beräknar jag ett obligationspris eller avkastning till förfall?","howAnswer":"Ange nominellt värde, årlig kupongränta, år till löptid och kupongfrekvens. Välj pris-från-avkastning för att rabattera den planerade kupong- och kapitalbetalningen, eller välj avkastning-från-pris för att numeriskt lösa den nominella årliga avkastningen som matchar ett marknadspris.","privacyQuestion":"Är mina bondingångar uppladdade?","privacyAnswer":"Nej. Beräkningen körs i den här webbläsaren. Indata laddas inte upp eller sparas av detta verktyg.","howTo":["Välj om du vill uppskatta ett pris från avkastning eller lösa avkastning från ett marknadspris.","Ange nominellt värde, årlig kupongränta, löptid och kupongfrekvens.","Beräkna och jämför resultatet med de visade antagandena och kurvan."],"example":{"label":"Ladda en kupongobligation på 5 % prissatt till pari","values":[]},"actions":{"calculate":"Beräkna obligationsvärdet","example":"Ladda par-bond exempel","reset":"Återställ","copy":"Kopiera resultat","result":"Obligationsuppskattning"},"fields":{"mode":"Beräkningsläge","priceMode":"Pris från en avkastning","yieldMode":"Avkastning från ett marknadspris","faceValue":"Nominellt (par) värde","couponPercent":"Årlig kupongränta (%)","years":"År till löptid","frequency":"Kupongbetalningar per år","annual":"Årlig (1)","semiannual":"Halvårsvis (2)","quarterly":"Kvartalsvis (4)","monthly":"Månatlig (12)","yieldPercent":"Nominell årlig avkastning (%)","marketPrice":"Marknadspris","accuracyNote":"Endast utbildningsberäkning, inte investeringsrådgivning. Förutsätter fasta kuponger som betalas med regelbundna intervall, kapital återbetalas vid förfallodagen, nominell årlig avkastning sammansatt med den valda kupongfrekvensen och inga upplupna räntor, skatter, avgifter, fallissemang, köpfunktioner, inflation eller återinvesteringseffekter. Löptiden måste vara ett helt antal kupongperioder. Utbytet är numeriskt och ungefärligt; bekräfta obligationsvillkor och marknadskonventioner oberoende.","resultSummary":"Uppskattade obligationsresultat","yieldToMaturity":"Avkastning till löptid (nominell årlig)","estimatedPrice":"Uppskattat pris","couponPayment":"Kupongbetalning per period","currentYield":"Aktuell avkastning","totalCoupons":"Totalt schemalagda kuponger","premiumDiscount":"Premium / rabatt till nominellt värde","periods":"Kupongperioder","chartTitle":"Beräknad kurs-avkastningskurva","chartDescription":"Obligationspriset rör sig i allmänhet i motsatt riktning mot avkastningen. Kurvan använder angivna fasta kupong- och löptidsantaganden.","chartYield":"Nominell årlig avkastning (%)","chartPrice":"Uppskattat pris"},"messages":{"calculated":"Obligationsuppskattning beräknad.","exampleLoaded":"Exempel laddat: 5 % kupong, 5 år, årliga betalningar, pris till par.","checkInputs":"Kontrollera obligationsvärdena och försök igen.","copied":"Resultaten har kopierats.","copyUnavailable":"Copy är inte tillgänglig i den här webbläsaren.","invalidPeriods":"Välj en löptid som innehåller ett helt antal kupongperioder (upp till 1 200).","yieldOutOfRange":"Marknadspriset ligger utanför det stödda numeriska avkastningsintervallet."},"additionalFaqs":[{"question":"Vilken avkastning har en 5 % kupongobligation när den är prissatt till pari?","answer":"Enligt kalkylatorns antaganden har en obligation med en årlig kupongränta på 5 %, ett marknadspris lika med nominellt värde och regelbundna kupongbetalningar en nominell avkastning till förfallodagen på 5 %."},{"question":"Varför rör sig obligationspriser och räntor i motsatta riktningar?","answer":"Ett obligationspris är nuvärdet av dess planerade kuponger och kapital. En högre diskonteringsavkastning minskar det nuvärdet; en lägre avkastning ökar den."},{"question":"Är aktuell avkastning detsamma som avkastning till förfall?","answer":"Nej. Aktuell avkastning är den årliga kupongen dividerad med det aktuella priset. Avkastning till förfall står också för prisskillnaden från nominellt värde och återstående tid, enligt de angivna kassaflödesantagandena."},{"question":"Inkluderar denna uppskattning upplupen ränta eller skatter?","answer":"Nej. Den modellerar endast vanliga fasta kupongbetalningar och återbetalning av kapital. Den beräknar inte rent-mot-smutsigt pris, upplupen ränta, skatter, avgifter, kreditrisk eller valfri inlösen."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"th":{"copyLanguage":"th","name":"Bond Calculator","title":"Bond Calculator ฟรี | UsefulVerse","description":"ประมาณการราคาพันธบัตรหรืออัตราผลตอบแทนจนครบกำหนดจากคูปอง มูลค่าที่ตราไว้ และระยะเวลา การคำนวณฟรีไม่จำกัดทำงานภายในเบราว์เซอร์ของคุณ","intro":"ประมาณการราคาพันธบัตรที่มีอัตราคงที่จากอัตราผลตอบแทน หรือแก้อัตราผลตอบแทนโดยประมาณจนครบกำหนดจากราคาตลาดที่เสนอราคา ทบทวนสมมติฐานและเส้นราคา-ผลตอบแทนก่อนใช้ผลลัพธ์","howQuestion":"ฉันจะคำนวณราคาพันธบัตรหรืออัตราผลตอบแทนจนครบกำหนดได้อย่างไร?","howAnswer":"ป้อนมูลค่าที่ตราไว้ อัตราคูปองรายปี ปีที่จะครบกำหนด และความถี่ของคูปอง เลือกราคาจากผลตอบแทนเพื่อลดคูปองตามกำหนดการและการชำระเงินต้น หรือเลือกผลตอบแทนจากราคาเพื่อคำนวณผลตอบแทนประจำปีที่ระบุที่ตรงกับราคาตลาดเป็นตัวเลข","privacyQuestion":"อินพุตพันธบัตรของฉันถูกอัปโหลดหรือไม่","privacyAnswer":"ไม่ การคำนวณรันในเบราว์เซอร์นี้ เครื่องมือนี้ไม่ได้อัปโหลดหรือบันทึกอินพุต","howTo":["เลือกว่าจะประมาณราคาจากผลผลิตหรือแก้ผลตอบแทนจากราคาตลาด","ป้อนมูลค่าที่ตราไว้ อัตราคูปองรายปี อายุครบกำหนด และความถี่ของคูปอง","คำนวณและเปรียบเทียบผลลัพธ์กับสมมติฐานและเส้นโค้งที่แสดง"],"example":{"label":"โหลดพันธบัตรคูปอง 5% ที่ราคาพาร์","values":[]},"actions":{"calculate":"คำนวณมูลค่าพันธบัตร","example":"โหลดตัวอย่างพาร์บอนด์","reset":"รีเซ็ต","copy":"คัดลอกผลลัพธ์","result":"ประมาณการพันธบัตร"},"fields":{"mode":"โหมดการคำนวณ","priceMode":"ราคาจากผลตอบแทน","yieldMode":"อัตราผลตอบแทนจากราคาตลาด","faceValue":"ค่าหน้า (พาร์)","couponPercent":"อัตราคูปองรายปี (%)","years":"ปีถึงกำหนด","frequency":"การจ่ายคูปองต่อปี","annual":"ประจำปี (1)","semiannual":"รายครึ่งปี (2)","quarterly":"รายไตรมาส (4)","monthly":"รายเดือน (12)","yieldPercent":"อัตราผลตอบแทนต่อปีที่กำหนด (%)","marketPrice":"ราคาตลาด","accuracyNote":"เป็นประมาณการทางการศึกษาเท่านั้น ไม่ใช่คำแนะนำในการลงทุน ถือว่าคูปองคงที่ที่จ่ายในช่วงเวลาปกติ ชำระคืนเงินต้นเมื่อครบกำหนด อัตราผลตอบแทนรายปีที่ระบุทบต้นตามความถี่ของคูปองที่เลือก และไม่มีดอกเบี้ยค้างจ่าย ภาษี ค่าธรรมเนียม การผิดนัด ลักษณะการโทร อัตราเงินเฟ้อ หรือผลกระทบจากการลงทุนซ้ำ ระยะเวลาครบกำหนดต้องเป็นจำนวนงวดคูปองทั้งหมด อัตราผลตอบแทนเป็นตัวเลขและเป็นค่าโดยประมาณ ยืนยันเงื่อนไขพันธบัตรและข้อตกลงทางการตลาดอย่างเป็นอิสระ","resultSummary":"ผลลัพธ์ของพันธบัตรโดยประมาณ","yieldToMaturity":"อัตราผลตอบแทนจนครบกำหนด (ระบุรายปี)","estimatedPrice":"ราคาโดยประมาณ","couponPayment":"การจ่ายคูปองต่องวด","currentYield":"อัตราผลตอบแทนปัจจุบัน","totalCoupons":"คูปองที่กำหนดทั้งหมด","premiumDiscount":"Premium / ส่วนลดตามมูลค่า","periods":"ระยะเวลาคูปอง","chartTitle":"เส้นราคา–ผลตอบแทนโดยประมาณ","chartDescription":"จะเคลื่อนไหวไปในทิศทางตรงกันข้ามเพื่อให้ได้อัตราผลตอบแทน เส้นโค้งใช้สมมติฐานคงที่ของคูปองและระยะเวลาครบกำหนดที่ป้อน","chartYield":"อัตราผลตอบแทนต่อปีที่กำหนด (%)","chartPrice":"ราคาโดยประมาณ"},"messages":{"calculated":"แล้ว","exampleLoaded":"ตัวอย่างที่โหลด: คูปอง 5%, 5 ปี, ชำระเงินรายปี, ราคาพาร์","checkInputs":"ตรวจสอบค่าบอนด์แล้วลองอีกครั้ง","copied":"แล้ว","copyUnavailable":"Copy ไม่พร้อมใช้งานในเบราว์เซอร์นี้","invalidPeriods":"เลือกระยะเวลาครบกำหนดที่มีระยะเวลาคูปองจำนวนเต็ม (สูงสุด 1,200)","yieldOutOfRange":"ราคาตลาดอยู่นอกช่วงอัตราผลตอบแทนที่เป็นตัวเลขที่รองรับ"},"additionalFaqs":[{"question":"พันธบัตรคูปอง 5% ให้ผลตอบแทนเท่าใดเมื่อมีราคาที่ตราไว้?","answer":"ภายใต้สมมติฐานของเครื่องคิดเลข พันธบัตรที่มีอัตราคูปองต่อปี 5% ราคาตลาดเท่ากับมูลค่าที่ตราไว้ และการจ่ายคูปองปกติจะมีอัตราผลตอบแทนเล็กน้อยจนถึงวันครบกำหนดที่ 5%"},{"question":"ทำไมราคาและอัตราผลตอบแทนพันธบัตรจึงเคลื่อนไหวในทิศทางตรงกันข้าม?","answer":"ราคาพันธบัตรคือมูลค่าปัจจุบันของคูปองและเงินต้นที่กำหนดไว้ อัตราผลตอบแทนที่สูงกว่าจะลดมูลค่าปัจจุบันนั้น ผลผลิตที่ต่ำกว่าจะเพิ่มขึ้น"},{"question":"อัตราผลตอบแทนปัจจุบันเท่ากับอัตราผลตอบแทนเมื่อครบกำหนดหรือไม่?","answer":"No. อัตราผลตอบแทนปัจจุบันคือคูปองรายปีหารด้วยราคาปัจจุบัน อัตราผลตอบแทนจนครบกำหนดยังคำนึงถึงส่วนต่างของราคาจากมูลค่าที่ตราไว้และเวลาที่เหลืออยู่ภายใต้สมมติฐานกระแสเงินสดที่ระบุไว้"},{"question":"การประมาณการนี้รวมดอกเบี้ยหรือภาษีค้างจ่ายหรือไม่","answer":"ไม่ใช่ โดยจะจำลองการชำระคูปองคงที่ปกติและการชำระคืนเงินต้นเท่านั้น โดยจะไม่คำนวณราคาที่สะอาดเมื่อเทียบกับราคาที่สกปรก ดอกเบี้ยค้างรับ ภาษี ค่าธรรมเนียม ความเสี่ยงด้านเครดิต หรือการไถ่ถอนเพิ่มเติม"}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"uk":{"copyLanguage":"uk","name":"Калькулятор облігацій","title":"Калькулятор облігацій безкоштовно | UsefulVerse","description":"Оцініть ціну облігації або прибутковість до погашення на основі купону, номінальної вартості та терміну. Безкоштовні необмежені обчислення виконуються…","intro":"Оцініть ціну облігації з фіксованою процентною ставкою на основі її дохідності або розв’яжіть приблизну дохідність до погашення на основі котированої ринкової ціни. Перед використанням результату перегляньте припущення та криву ціна–прибутковість.","howQuestion":"Як розрахувати ціну облігації або прибутковість до погашення?","howAnswer":"Введіть номінальну вартість, річну купонну ставку, кількість років до погашення та частоту купонів. Виберіть «ціна-від-прибутковості», щоб дисконтувати заплановані виплати купона та основної суми, або виберіть «прибутковість-від-ціни», щоб чисельно визначити номінальну річну дохідність, яка відповідає ринковій ціні.","privacyQuestion":"Чи завантажено мої дані про облігації?","privacyAnswer":"Ні. Розрахунок виконується в цьому браузері. Цей інструмент не завантажує та не зберігає дані.","howTo":["Виберіть, чи оцінювати ціну на основі прибутковості чи розв’язувати прибутковість на основі ринкової ціни.","Введіть номінальну вартість, річну купонну ставку, термін погашення та частоту купонів.","Обчисліть і порівняйте результат із показаними припущеннями та кривою."],"example":{"label":"Завантажте 5% купонну облігацію за номіналом","values":[]},"actions":{"calculate":"Обчисліть вартість облігації","example":"Приклад номіналу навантаження","reset":"Скинути","copy":"Копіювати результати","result":"Оцінка облігацій"},"fields":{"mode":"Режим розрахунку","priceMode":"Ціна від урожайності","yieldMode":"Прибуток від ринкової ціни","faceValue":"Номінальна (номінальна) вартість","couponPercent":"Річна купонна ставка (%)","years":"Років до погашення","frequency":"Купонні виплати на рік","annual":"Річний (1)","semiannual":"Раз на півроку (2)","quarterly":"Щоквартальник (4)","monthly":"Щомісяця (12)","yieldPercent":"Номінальна річна дохідність (%)","marketPrice":"Ринкова ціна","accuracyNote":"Лише освітня оцінка, а не інвестиційні консультації. Припускає фіксовані купони, що виплачуються через регулярні проміжки часу, основну суму погашають у момент погашення, номінальний річний дохід, що складається з вибраною частотою купонів, і відсутність нарахованих відсотків, податків, комісій, дефолту, функцій колл, інфляції чи реінвестування. Термін погашення має бути цілим числом купонних періодів. Урожайність чисельна і приблизна; самостійно підтверджувати умови облігацій та ринкові конвенції.","resultSummary":"Приблизні результати облігацій","yieldToMaturity":"Дохідність до погашення (номінальна річна)","estimatedPrice":"Орієнтовна ціна","couponPayment":"Виплата купона за період","currentYield":"Поточний дохід","totalCoupons":"Усього запланованих купонів","premiumDiscount":"Преміум / знижка до номіналу","periods":"Купонні періоди","chartTitle":"Розрахункова крива дохідності","chartDescription":"Ціна облігацій зазвичай рухається в протилежному напрямку до прибутковості. Крива використовує введені припущення з фіксованим купоном і терміном погашення.","chartYield":"Номінальна річна дохідність (%)","chartPrice":"Орієнтовна ціна"},"messages":{"calculated":".","exampleLoaded":"Завантажений приклад: 5% купон, 5 років, щорічні платежі, ціна за номіналом.","checkInputs":"Перевірте вартість облігацій і повторіть спробу.","copied":"Результати скопійовано.","copyUnavailable":"Копія недоступна в цьому браузері.","invalidPeriods":"Виберіть строк погашення, який містить цілу кількість купонних періодів (до 1200).","yieldOutOfRange":"Ринкова ціна виходить за межі підтримуваного числового діапазону дохідності."},"additionalFaqs":[{"question":"Яку дохідність має 5% купонна облігація, якщо вона оцінюється за номіналом?","answer":"Згідно з припущеннями калькулятора, облігація з 5% річною купонною ставкою, ринковою ціною, що дорівнює номіналу, і регулярними купонними виплатами має номінальний дохід до погашення 5%."},{"question":"Чому ціни на облігації та прибутковість рухаються в протилежних напрямках?","answer":"Ціна облігації – це теперішня вартість її запланованих купонів і основної суми. Вищий дисконтний дохід зменшує теперішню вартість; нижча врожайність збільшує його."},{"question":"Чи є поточна дохідність такою ж, як дохідність до погашення?","answer":"Ні. Поточна прибутковість – річний купон, поділений на поточну ціну. Прибутковість до погашення також враховує різницю ціни від номінальної вартості та час, що залишився, відповідно до заявлених припущень щодо грошових потоків."},{"question":"Чи включає ця оцінка нараховані відсотки чи податки?","answer":"Ні. Він моделює регулярні виплати з фіксованим купоном і лише погашення основної суми. Він не розраховує чисту ціну проти брудної, нараховані відсотки, податки, комісії, кредитний ризик або необов’язковий викуп."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"sw":{"copyLanguage":"sw","name":"Bond Calculator","title":"Bond Calculator bure | UsefulVerse","description":"Kadiria bei ya dhamana au mavuno hadi ukomavu kutoka kwa kuponi, thamani ya uso na muda. Hesabu za bure na zisizo na kikomo zinaendeshwa ndani ya kivinjari…","intro":"Kadiria bei ya dhamana ya kiwango maalum kutoka kwa mavuno yake, au suluhisha takriban mavuno hadi ukomavu kutoka kwa bei iliyonukuliwa ya soko. Kagua mawazo na msururu wa bei-mavuno kabla ya kutumia matokeo.","howQuestion":"Je, ninawezaje kukokotoa bei ya dhamana au mavuno hadi ukomavu?","howAnswer":"Weka thamani ya uso, kiwango cha kuponi ya kila mwaka, miaka hadi ukomavu na marudio ya kuponi. Chagua bei-kutoka-mavuno ili upunguze kuponi iliyoratibiwa na malipo kuu, au uchague mavuno-kutoka-bei ili kutatua kwa nambari mapato ya kila mwaka yanayolingana na bei ya soko.","privacyQuestion":"Je, ingizo za bondi yangu zimepakiwa?","privacyAnswer":". Hesabu inaendeshwa katika kivinjari hiki. Ingizo hazijapakiwa au kuhifadhiwa na zana hii.","howTo":["Chagua kama utakadiria bei kutokana na mavuno au utatue mavuno kutoka kwa bei ya soko.","Weka thamani ya uso, kiwango cha kuponi ya kila mwaka, ukomavu na marudio ya kuponi.","Kokotoa na ulinganishe matokeo na mawazo na curve iliyoonyeshwa."],"example":{"label":"Pakia dhamana ya 5% ya kuponi iliyo bei sawa na","values":[]},"actions":{"calculate":"Kokotoa dhamana ya dhamana","example":"Pakia par-bond mfano","reset":"Weka upya","copy":"Nakili matokeo","result":"Bond estimate"},"fields":{"mode":"Calculation mode","priceMode":"Bei kutoka kwa mavuno","yieldMode":"Mazao kutoka kwa bei ya soko","faceValue":"Uso (par) thamani","couponPercent":"Kiwango cha kuponi kwa mwaka (%)","years":"Miaka hadi kukomaa","frequency":"kwa mwaka","annual":"Mwaka (1)","semiannual":"Semiannual (2)","quarterly":"Kila Robo (4)","monthly":"Kila Mwezi (12)","yieldPercent":"Mavuno ya kawaida ya kila mwaka (%)","marketPrice":"Bei ya soko","accuracyNote":"Makadirio ya kielimu pekee, sio ushauri wa uwekezaji. Huchukua kuponi zisizobadilika zinazolipwa kwa vipindi vya kawaida, malipo kuu ya ukomavu, mavuno ya kila mwaka yanayojumuishwa katika marudio ya kuponi yaliyochaguliwa, na hakuna riba iliyoongezwa, kodi, ada, chaguo-msingi, vipengele vya kupiga simu, mfumuko wa bei au athari za uwekaji upya. Ukomavu lazima uwe idadi nzima ya vipindi vya kuponi. Mavuno ni nambari na takriban; thibitisha masharti ya dhamana na mikataba ya soko kwa kujitegemea.","resultSummary":"Kadirio la matokeo ya dhamana","yieldToMaturity":"Mavuno hadi ukomavu (jina la mwaka)","estimatedPrice":"Bei iliyokadiriwa","couponPayment":"kwa kila kipindi","currentYield":"Mavuno ya sasa","totalCoupons":"Jumla ya kuponi zilizopangwa","premiumDiscount":"Premium / punguzo kwa thamani ya uso","periods":"Coupon periods","chartTitle":"Kadirio la bei–mavuno Curve","chartDescription":"kwa ujumla huhamia upande tofauti ili kutoa mavuno. Curve hutumia kuponi isiyobadilika iliyoingizwa na mawazo ya ukomavu.","chartYield":"Mavuno ya kila mwaka (%)","chartPrice":"Bei iliyokadiriwa"},"messages":{"calculated":"imekokotolewa.","exampleLoaded":"umepakiwa: kuponi ya 5%, miaka 5, malipo ya kila mwaka, bei iliyo sawa.","checkInputs":"Angalia thamani za bondi na ujaribu tena.","copied":"yamenakiliwa.","copyUnavailable":"haipatikani katika kivinjari hiki.","invalidPeriods":"Chagua ukomavu ambao una idadi kamili ya vipindi vya kuponi (hadi 1,200).","yieldOutOfRange":"Bei ya soko iko nje ya anuwai ya nambari inayotumika."},"additionalFaqs":[{"question":"Bondi ya 5% ya kuponi ina mavuno gani wakati bei yake inalingana?","answer":"Chini ya mawazo ya kikokotoo, bondi yenye kiwango cha kuponi cha 5% kwa mwaka, bei ya soko inayolingana na thamani halisi na malipo ya kawaida ya kuponi yana mavuno ya kawaida hadi ukomavu wa 5%."},{"question":"Kwa nini bei za dhamana na mazao husogea katika mwelekeo tofauti?","answer":"Bei ya bondi ni thamani ya sasa ya kuponi zake kuu na kuu iliyoratibiwa. Mavuno ya juu ya punguzo hupunguza thamani hiyo ya sasa; mavuno ya chini huongeza yake."},{"question":"Je, mavuno ya sasa ni sawa na mavuno hadi ukomavu?","answer":". Mavuno ya sasa ni kuponi ya kila mwaka iliyogawanywa na bei ya sasa. Mavuno hadi ukomavu pia huchangia tofauti ya bei kutoka kwa thamani halisi na muda uliosalia, chini ya makadirio yaliyotajwa ya mtiririko wa pesa."},{"question":"Je, makadirio haya yanajumuisha riba au kodi iliyoongezwa?","answer":". Ni mfano wa malipo ya kawaida ya kuponi yasiyobadilika na ulipaji mkuu pekee. Hahesabu bei safi dhidi ya chafu, riba iliyokusanywa, kodi, ada, hatari ya mkopo au ukombozi wa hiari."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"mr":{"copyLanguage":"mr","name":"बाँड कॅल्क्युलेटर","title":"बाँड कॅल्क्युलेटर मोफत | UsefulVerse","description":"कूपन, फेस व्हॅल्यू आणि टर्मवरून बॉण्डची किंमत किंवा परिपक्वतेपर्यंत उत्पन्नाचा अंदाज लावा. तुमच्या ब्राउझरमध्ये विनामूल्य, अमर्यादित गणना स्थानिक पातळीवर चालते.","intro":"त्याच्या उत्पन्नावरून निश्चित-दर बाँडच्या किमतीचा अंदाज लावा किंवा उद्धृत बाजार किमतीवरून परिपक्वतेपर्यंत अंदाजे उत्पन्न सोडवा. निकाल वापरण्यापूर्वी गृहीतके आणि किंमत-उत्पन्न वक्र यांचे पुनरावलोकन करा.","howQuestion":"मी बॉण्डची किंमत किंवा परिपक्वतेपर्यंत उत्पन्न कसे मोजू?","howAnswer":"दर्शनी मूल्य, वार्षिक कूपन दर, परिपक्वता वर्षे आणि कूपन वारंवारता प्रविष्ट करा. अनुसूचित कूपन आणि मुख्य देयके सवलत देण्यासाठी किंमत-पासून-उत्पन्न निवडा किंवा बाजारभावाशी जुळणारे नाममात्र वार्षिक उत्पन्न संख्यात्मकरित्या सोडवण्यासाठी किंमत-पासून-उत्पन्न निवडा.","privacyQuestion":"माझे बाँड इनपुट अपलोड केले आहेत का?","privacyAnswer":"क्रमांक. गणना या ब्राउझरमध्ये चालते. या साधनाद्वारे इनपुट अपलोड किंवा जतन केले जात नाहीत.","howTo":["उत्पादनावरून किंमत मोजायची की बाजारभावावरून उत्पन्न सोडवायचे ते निवडा.","दर्शनी मूल्य, वार्षिक कूपन दर, परिपक्वता आणि कूपन वारंवारता प्रविष्ट करा.","प्रदर्शित गृहीतके आणि वक्र सह निकालाची गणना आणि तुलना करा."],"example":{"label":"Load a 5% coupon bond priced at par","values":[]},"actions":{"calculate":"बाँड मूल्याची गणना करा","example":"लोड पार-बॉन्ड उदाहरण","reset":"Reset","copy":"परिणाम कॉपी करा","result":"बाँड अंदाज"},"fields":{"mode":"गणना मोड","priceMode":"उत्पन्नापासून","yieldMode":"बाजारभाव","faceValue":"फेस (पार) मूल्य","couponPercent":"वार्षिक कूपन दर (%)","years":"परिपक्वतेसाठी वर्षे","frequency":"प्रति वर्ष कूपन पेमेंट","annual":"वार्षिक (1)","semiannual":"अर्धवार्षिक (2)","quarterly":"त्रैमासिक (4)","monthly":"मासिक (12)","yieldPercent":"नाममात्र वार्षिक उत्पन्न (%)","marketPrice":"बाजारभाव","accuracyNote":"केवळ शैक्षणिक अंदाज, गुंतवणूक सल्ला नाही. नियमित अंतराने अदा केलेले निश्चित कूपन, मुदतपूर्तीच्या वेळी परतफेड केलेली मुद्दल, निवडलेल्या कूपन वारंवारतेनुसार नाममात्र वार्षिक उत्पन्न, आणि कोणतेही जमा झालेले व्याज, कर, शुल्क, डीफॉल्ट, कॉल वैशिष्ट्ये, चलनवाढ किंवा पुनर्गुंतवणूक प्रभाव गृहीत धरते. मॅच्युरिटी कूपन कालावधीची संपूर्ण संख्या असणे आवश्यक आहे. उत्पन्न संख्यात्मक आणि अंदाजे आहे; बाँडच्या अटी आणि बाजार नियमांची स्वतंत्रपणे पुष्टी करा.","resultSummary":"अंदाजे बाँड परिणाम","yieldToMaturity":"परिपक्वतेपर्यंत उत्पन्न (नाममात्र वार्षिक)","estimatedPrice":"अंदाजे किंमत","couponPayment":"प्रति कालावधी","currentYield":"वर्तमान उत्पन्न","totalCoupons":"एकूण अनुसूचित कूपन","premiumDiscount":"प्रीमियम / दर्शनी मूल्यावर सूट","periods":"कूपन कालावधी","chartTitle":"अंदाजे किंमत–उत्पन्न वक्र","chartDescription":"बाँडची किंमत सामान्यतः उत्पन्नासाठी उलट दिशेने फिरते. वक्र प्रविष्ट केलेले निश्चित कूपन आणि परिपक्वता गृहितके वापरते.","chartYield":"नाममात्र वार्षिक उत्पन्न (%)","chartPrice":"अंदाजे किंमत"},"messages":{"calculated":"बाँड अंदाज मोजला.","exampleLoaded":"लोड केलेले उदाहरण: 5% कूपन, 5 वर्षे, वार्षिक देयके, समान किंमत.","checkInputs":"बाँड मूल्ये तपासा आणि पुन्हा प्रयत्न करा.","copied":"परिणाम कॉपी केले.","copyUnavailable":"कॉपी या ब्राउझरमध्ये अनुपलब्ध आहे.","invalidPeriods":"एक परिपक्वता निवडा ज्यामध्ये संपूर्ण कूपन कालावधी (1,200 पर्यंत).","yieldOutOfRange":"बाजारातील किंमत समर्थित संख्यात्मक उत्पन्न श्रेणीच्या बाहेर आहे."},"additionalFaqs":[{"question":"5% कूपन बाँडची किंमत सममूल्य असताना त्याचे काय उत्पन्न मिळते?","answer":"कॅल्क्युलेटर गृहीतकांनुसार, 5% वार्षिक कूपन दर, दर्शनी मूल्याच्या समान बाजारभाव आणि नियमित कूपन पेमेंटसह बॉण्डची परिपक्वता 5% पर्यंत नाममात्र उत्पन्न असते."},{"question":"रोख्यांच्या किमती आणि उत्पन्न विरुद्ध दिशेने का फिरतात?","answer":"बाँडची किंमत ही त्याच्या अनुसूचित कूपन आणि मुद्दलांचे सध्याचे मूल्य आहे. उच्च सवलतीचे उत्पन्न सध्याचे मूल्य कमी करते; कमी उत्पन्न ते वाढवते."},{"question":"सध्याचे उत्पन्न परिपक्वतेच्या उत्पन्नासारखे आहे का?","answer":"क्रमांक. वर्तमान उत्पन्न हे वर्तमान किमतीने भागलेले वार्षिक कूपन आहे. नगदी-प्रवाह गृहीतके अंतर्गत, परिपक्वतेपर्यंतचे उत्पन्न हे दर्शनी मूल्यातील किंमतीतील फरक आणि उरलेल्या वेळेसाठी देखील जबाबदार आहे."},{"question":"या अंदाजामध्ये जमा झालेले व्याज किंवा कर समाविष्ट आहेत का?","answer":"क्र. हे नियमित फिक्स्ड कूपन पेमेंट आणि फक्त मुद्दल परतफेड मॉडेल करते. हे स्वच्छ-विरुद्ध-डर्टी किंमत, जमा झालेले व्याज, कर, शुल्क, क्रेडिट जोखीम किंवा पर्यायी पूर्तता यांची गणना करत नाही."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"te":{"copyLanguage":"te","name":"బాండ్ కాలిక్యులేటర్","title":"బాండ్ కాలిక్యులేటర్ ఉచితం | UsefulVerse","description":"బాండ్ ధరను అంచనా వేయండి లేదా కూపన్, ముఖ విలువ మరియు పదం నుండి మెచ్యూరిటీకి వచ్చే రాబడిని అంచనా వేయండి. ఉచిత, అపరిమిత లెక్కలు మీ బ్రౌజర్‌లో స్థానికంగా అమలు…","intro":"దాని దిగుబడి నుండి స్థిర-రేటు బాండ్ ధరను అంచనా వేయండి లేదా కోట్ చేయబడిన మార్కెట్ ధర నుండి మెచ్యూరిటీకి సుమారు దిగుబడిని పరిష్కరించండి. ఫలితాన్ని ఉపయోగించే ముందు అంచనాలు మరియు ధర-దిగుబడి వక్రతను సమీక్షించండి.","howQuestion":"నేను మెచ్యూరిటీకి బాండ్ ధర లేదా రాబడిని ఎలా లెక్కించాలి?","howAnswer":"ముఖ విలువ, వార్షిక కూపన్ రేటు, మెచ్యూరిటీ నుండి సంవత్సరాలు మరియు కూపన్ ఫ్రీక్వెన్సీని నమోదు చేయండి. షెడ్యూల్ చేయబడిన కూపన్ మరియు ప్రధాన చెల్లింపులను తగ్గించడానికి దిగుబడి నుండి ధరను ఎంచుకోండి లేదా మార్కెట్ ధరకు సరిపోయే నామమాత్రపు వార్షిక దిగుబడిని సంఖ్యాపరంగా పరిష్కరించడానికి దిగుబడి నుండి ధరను ఎంచుకోండి.","privacyQuestion":"నా బాండ్ ఇన్‌పుట్‌లు అప్‌లోడ్ చేయబడిందా?","privacyAnswer":"సంఖ్య. గణన ఈ బ్రౌజర్‌లో నడుస్తుంది. ఈ సాధనం ద్వారా ఇన్‌పుట్‌లు అప్‌లోడ్ చేయబడవు లేదా సేవ్ చేయబడవు.","howTo":["దిగుబడి నుండి ధరను అంచనా వేయాలో లేదా మార్కెట్ ధర నుండి దిగుబడిని పరిష్కరించాలో ఎంచుకోండి.","ముఖ విలువ, వార్షిక కూపన్ రేటు, మెచ్యూరిటీ మరియు కూపన్ ఫ్రీక్వెన్సీని నమోదు చేయండి.","ప్రదర్శించబడిన ఊహలు మరియు వక్రతతో ఫలితాన్ని లెక్కించండి మరియు సరిపోల్చండి."],"example":{"label":"Load a 5% coupon bond priced at par","values":[]},"actions":{"calculate":"బాండ్ విలువ","example":"లోడ్ పార్-బాండ్ ఉదాహరణ","reset":"Reset","copy":"ఫలితాలను కాపీ చేయండి","result":"బాండ్ అంచనా"},"fields":{"mode":"గణన మోడ్","priceMode":"దిగుబడి","yieldMode":"మార్కెట్ ధర","faceValue":"ముఖం (సమాన) విలువ","couponPercent":"వార్షిక కూపన్ రేటు (%)","years":"పరిపక్వత","frequency":"సంవత్సరానికి కూపన్ చెల్లింపులు","annual":"వార్షిక (1)","semiannual":"సెమియాన్యువల్ (2)","quarterly":"త్రైమాసికం (4)","monthly":"నెలవారీ (12)","yieldPercent":"నామమాత్రపు వార్షిక దిగుబడి (%)","marketPrice":"మార్కెట్ ధర","accuracyNote":"విద్యా అంచనా మాత్రమే, పెట్టుబడి సలహా కాదు. నిర్ణీత వ్యవధిలో చెల్లించిన స్థిర కూపన్‌లు, మెచ్యూరిటీ సమయంలో అసలు రీపేడ్, ఎంచుకున్న కూపన్ ఫ్రీక్వెన్సీలో నామమాత్రపు వార్షిక రాబడి సమ్మేళనం మరియు వడ్డీ, పన్నులు, ఫీజులు, డిఫాల్ట్, కాల్ ఫీచర్‌లు, ద్రవ్యోల్బణం లేదా రీఇన్వెస్ట్‌మెంట్ ఎఫెక్ట్‌లు లేవు. మెచ్యూరిటీ తప్పనిసరిగా కూపన్ పీరియడ్‌ల పూర్తి సంఖ్యలో ఉండాలి. దిగుబడి సంఖ్యాపరంగా మరియు సుమారుగా ఉంటుంది; బాండ్ నిబంధనలు మరియు మార్కెట్ సమావేశాలను స్వతంత్రంగా నిర్ధారించండి.","resultSummary":"అంచనా వేసిన బాండ్ ఫలితాలు","yieldToMaturity":"మెచ్యూరిటీకి దిగుబడి (నామమాత్రపు వార్షికం)","estimatedPrice":"అంచనా ధర","couponPayment":"వ్యవధికి","currentYield":"ప్రస్తుత దిగుబడి","totalCoupons":"మొత్తం షెడ్యూల్ చేసిన కూపన్‌లు","premiumDiscount":"ప్రీమియం / ముఖ విలువకు తగ్గింపు","periods":"కూపన్ కాలాలు","chartTitle":"అంచనా ధర-దిగుబడి వక్రత","chartDescription":"బాండ్ ధర సాధారణంగా దిగుబడికి వ్యతిరేక దిశలో కదులుతుంది. వక్రరేఖ నమోదు చేయబడిన స్థిర కూపన్ మరియు మెచ్యూరిటీ అంచనాలను ఉపయోగిస్తుంది.","chartYield":"నామమాత్రపు వార్షిక దిగుబడి (%)","chartPrice":"అంచనా ధర"},"messages":{"calculated":"బాండ్ అంచనా లెక్కించబడింది.","exampleLoaded":"ఉదాహరణ లోడ్ చేయబడింది: 5% కూపన్, 5 సంవత్సరాలు, వార్షిక చెల్లింపులు, సమానంగా ధర.","checkInputs":"బాండ్ విలువలను తనిఖీ చేసి, మళ్లీ ప్రయత్నించండి.","copied":"ఫలితాలు కాపీ చేయబడ్డాయి.","copyUnavailable":"కాపీ ఈ బ్రౌజర్‌లో అందుబాటులో లేదు.","invalidPeriods":"మొత్తం సంఖ్యలో కూపన్ పీరియడ్‌లను (1,200 వరకు) కలిగి ఉన్న మెచ్యూరిటీని ఎంచుకోండి.","yieldOutOfRange":"మార్కెట్ ధర మద్దతు ఉన్న సంఖ్యా దిగుబడి పరిధికి వెలుపల ఉంది."},"additionalFaqs":[{"question":"5% కూపన్ బాండ్ సమానంగా ధర నిర్ణయించబడినప్పుడు ఎంత దిగుబడిని కలిగి ఉంటుంది?","answer":"కాలిక్యులేటర్ అంచనాల ప్రకారం, 5% వార్షిక కూపన్ రేటుతో కూడిన బాండ్, ముఖ విలువకు సమానమైన మార్కెట్ ధర మరియు సాధారణ కూపన్ చెల్లింపులు 5% మెచ్యూరిటీకి నామమాత్రపు రాబడిని కలిగి ఉంటాయి."},{"question":"బాండ్ ధరలు మరియు ఈల్డ్‌లు వ్యతిరేక దిశల్లో ఎందుకు కదులుతాయి?","answer":"ఒక బాండ్ ధర దాని షెడ్యూల్ చేయబడిన కూపన్లు మరియు ప్రిన్సిపాల్ యొక్క ప్రస్తుత విలువ. అధిక తగ్గింపు దిగుబడి ప్రస్తుత విలువను తగ్గిస్తుంది; తక్కువ దిగుబడి పెరుగుతుంది."},{"question":"మెచ్యూరిటీకి వచ్చే దిగుబడికి ప్రస్తుత దిగుబడి సమానంగా ఉందా?","answer":"సంఖ్య. ప్రస్తుత దిగుబడి ప్రస్తుత ధరతో భాగించబడిన వార్షిక కూపన్. మెచ్యూరిటీకి వచ్చే దిగుబడి కూడా పేర్కొన్న నగదు ప్రవాహ అంచనాల ప్రకారం ముఖ విలువ మరియు మిగిలిన సమయం నుండి ధర వ్యత్యాసానికి కారణమవుతుంది."},{"question":"ఈ అంచనాలో పెరిగిన వడ్డీ లేదా పన్నులు ఉన్నాయా?","answer":"సంఖ్య. ఇది సాధారణ స్థిర కూపన్ చెల్లింపులు మరియు అసలు తిరిగి చెల్లింపులను మాత్రమే మోడల్ చేస్తుంది. ఇది క్లీన్-వర్సెస్ డర్టీ ధర, పెరిగిన వడ్డీ, పన్నులు, ఫీజులు, క్రెడిట్ రిస్క్ లేదా ఐచ్ఛిక విముక్తిని లెక్కించదు."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"ha":{"copyLanguage":"ha","name":"Kalkuleta mai ƙididdigewa","title":"Kalkuleta mai ƙididdigewa kyauta | UsefulVerse","description":"Ƙididdiga farashin haɗin gwiwa ko samar da girma daga coupon, ƙimar fuska da wa'adi. Ƙididdiga kyauta, mara iyaka yana gudana a cikin gida a cikin burauzar…","intro":"Yi ƙididdige ƙayyadaddun farashi mai ƙima daga yawan amfanin sa, ko warware ƙimar ƙima zuwa girma daga farashin kasuwa da aka nakalto. Bincika zato da farashin-hanyar samar da amfanin gona kafin amfani da sakamakon. Saukewa:","howQuestion":"Ta yaya zan lissafta farashin haɗin gwiwa ko yawan amfanin ƙasa zuwa girma? Saukewa:","howAnswer":"Shigar da ƙimar fuska, ƙimar coupon na shekara, shekaru zuwa girma da mitar coupon. Zaɓi farashin-daga-haɓaka don rangwamen kuɗin da aka tsara da kuma babban biyan kuɗi, ko zaɓi yawan amfanin ƙasa-daga-farashi don warware yawan amfanin ƙasa na shekara-shekara wanda ya yi daidai da farashin kasuwa.","privacyQuestion":"An ɗora abubuwan shigarwa na haɗin gwiwa?","privacyAnswer":"A'a. Lissafin yana gudana a cikin wannan mai binciken. Ba a loda abubuwan da aka shigar ko adana su ta wannan kayan aikin. Saukewa:","howTo":["Zaɓi ko don kimanta farashi daga yawan amfanin ƙasa ko warware yawan amfanin ƙasa daga farashin kasuwa. Saukewa:","Shigar da ƙimar fuska, ƙimar coupon na shekara, balaga da mitar coupon. Saukewa:","Yi ƙididdigewa kuma kwatanta sakamakon tare da zato da lankwasa da aka nuna."],"example":{"label":"Load da 5% coupon da aka saka farashi akan","values":[]},"actions":{"calculate":"Yi lissafin ƙimar haɗin","example":"Load par-bond misali","reset":"Reset","copy":"Kwafi sakamakon","result":"Bond kimanta"},"fields":{"mode":"Calculation mode","priceMode":"Farashin daga yawan amfanin ƙasa","yieldMode":"Haɓaka Haɓaka daga farashin kasuwa","faceValue":"Face (kwatanta) darajar","couponPercent":"ƙimar coupon na shekara (%)","years":"Shekaru zuwa girma","frequency":"a kowace shekara","annual":"Shekara-shekara (1)","semiannual":"Semi-shekara (2)","quarterly":"Kwata-kwata (4)","monthly":"kowane wata (12)","yieldPercent":"Yawan amfanin ƙasa na shekara (%)","marketPrice":"Market price","accuracyNote":"Ƙimar ilimi kawai, ba shawarar saka hannun jari ba. Yana ɗaukar ƙayyadaddun takaddun shaida da aka biya a tazara na yau da kullun, babban abin biya a lokacin balaga, yawan amfanin ƙasa na shekara-shekara wanda aka haɗe a mitar coupon da aka zaɓa, kuma babu riba mai tarin yawa, haraji, kudade, tsoho, fasalulluka na kira, hauhawar farashin kaya ko tasirin sa hannun jari. Balagagge dole ne ya zama cikakken adadin lokutan coupon. Abubuwan da aka samu na lambobi ne kuma kusan; tabbatar da sharuɗɗan haɗin gwiwa da yarjejeniyar kasuwa da kansu.","resultSummary":"Kiyasin sakamakon haɗin gwiwa","yieldToMaturity":"Bayarwa ga balaga (na shekara-shekara)","estimatedPrice":"Kiyasin farashin","couponPayment":"a kowane lokaci","currentYield":"yawan amfanin ƙasa na yanzu","totalCoupons":"Jimlar takardun shaida","premiumDiscount":"Premium / rangwame zuwa ƙimar fuskantar","periods":"Lokacin Coupon","chartTitle":"Ƙimar farashin–ƙananan yawan amfanin ƙasa","chartDescription":"Bond farashin gabaɗaya yana motsawa a kishiyar shugabanci don samun albarka. Lanƙwan yana amfani da ƙayyadaddun takaddun shaida da kuma zato balagagge. Saukewa:","chartYield":"Yawan amfanin ƙasa na shekara (%)","chartPrice":"kiyasin farashin"},"messages":{"calculated":"kimanta ƙididdiga. Saukewa:","exampleLoaded":"Misali wanda aka ɗora: 5% coupon, shekaru 5, biyan kuɗi na shekara, farashi a daidai. Saukewa:","checkInputs":"Bincika ƙimar haɗin kuma sake gwadawa. Saukewa:","copied":"an kwafi. Saukewa:","copyUnavailable":"a cikin wannan mazugi.","invalidPeriods":"Zaɓi balagagge mai ƙunshe da cikakken adadin lokutan takardun shaida (har zuwa 1,200). Saukewa:","yieldOutOfRange":"Farashin kasuwa ya fita waje da goyan bayan adadin yawan amfanin ƙasa. Saukewa:"},"additionalFaqs":[{"question":"Menene amfanin 5% coupon bond ke da shi lokacin da aka farashi daidai? Saukewa:","answer":"Ƙarƙashin ƙididdiga na ƙididdiga, haɗin gwiwa tare da ƙimar coupon na shekara-shekara 5%, farashin kasuwa daidai da ƙimar fuska da biyan kuɗi na yau da kullum yana da yawan amfanin ƙasa zuwa girma na 5%. Saukewa:"},{"question":"Me yasa farashin haɗin gwiwa da abin da ake samu ke motsawa a cikin saɓanin kwatance? Saukewa:","answer":"Farashin haɗin kai shine darajar yanzu na takaddun shaida da babba. Ƙimar ragi mafi girma yana rage wannan ƙimar yanzu; ƙananan yawan amfanin ƙasa yana ƙaruwa."},{"question":"Shin amfanin amfanin yanzu iri ɗaya ne da yawan amfanin ƙasa zuwa girma? Saukewa:","answer":"No. Yawan amfanin ƙasa na yanzu shine coupon shekara-shekara da aka raba ta farashin yanzu. Bayarwa zuwa balaga kuma yana lissafin bambancin farashi daga ƙimar fuska da sauran lokacin da ya rage, ƙarƙashin zato-zubawar tsabar kuɗi. Saukewa:"},{"question":"Shin wannan kiyasin ya haɗa da ribar riba ko haraji? Saukewa:","answer":"A'a. Yana ƙirar ƙayyadaddun ƙayyadaddun biyan kuɗi na coupon na yau da kullun da babban biya kawai. Ba ya ƙididdige tsaftar-da-ƙazanta farashin, ribar da aka tara, haraji, kudade, haɗarin bashi ko fansa na zaɓi. Saukewa:"}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"tl":{"copyLanguage":"tl","name":"Bond Calculator","title":"Bond Calculator libre | UsefulVerse","description":"Tantyahin ang presyo ng bono o yield hanggang maturity mula sa kupon, halaga ng mukha at termino. Ang libre, walang limitasyong mga kalkulasyon ay tumatakbo…","intro":"Tantyahin ang isang fixed-rate na presyo ng bono mula sa yield nito, o lutasin ang isang tinatayang ani hanggang maturity mula sa isang naka-quote na presyo sa merkado. Suriin ang mga pagpapalagay at kurba ng presyo–bunga bago gamitin ang resulta.","howQuestion":"Paano ko kalkulahin ang presyo ng bono o yield hanggang maturity?","howAnswer":"Ilagay ang halaga ng mukha, taunang rate ng kupon, taon hanggang sa kapanahunan at dalas ng kupon. Pumili ng presyo mula sa ani upang idiskwento ang naka-iskedyul na kupon at mga pagbabayad ng prinsipal, o piliin ang yield-mula sa-presyo upang malutas ayon sa numero ang nominal na taunang ani na tumutugma sa presyo sa merkado.","privacyQuestion":"Na-upload ba ang aking mga bond input?","privacyAnswer":"Hindi. Ang pagkalkula ay tumatakbo sa browser na ito. Ang mga input ay hindi ina-upload o sine-save ng tool na ito.","howTo":["Piliin kung tatantyahin ang isang presyo mula sa ani o lutasin ang ani mula sa isang presyo sa merkado.","Ilagay ang halaga ng mukha, taunang rate ng kupon, maturity at dalas ng kupon.","Kalkulahin at ihambing ang resulta sa ipinakitang mga pagpapalagay at kurba."],"example":{"label":"Mag-load ng 5% coupon bond na may presyo sa par","values":[]},"actions":{"calculate":"Kalkulahin ang halaga ng bono","example":"Mag-load ng par-bond halimbawa","reset":"I-reset ang","copy":"Kopyahin ang mga resulta","result":"Bond tantiya"},"fields":{"mode":"Calculation mode","priceMode":"Presyo mula sa isang ani","yieldMode":"Yield mula sa isang market price","faceValue":"Halaga ng mukha (par)","couponPercent":"Taunang rate ng kupon (%)","years":"Taon hanggang sa kapanahunan","frequency":"Mga pagbabayad ng kupon bawat taon","annual":"Taunang (1)","semiannual":"Kalahati-taon (2)","quarterly":"Quarterly (4)","monthly":"Buwanang (12)","yieldPercent":"Nominal na taunang ani (%)","marketPrice":"Presyo sa merkado","accuracyNote":"Pang-edukasyon na pagtatantya lamang, hindi payo sa pamumuhunan. Ipinapalagay na binayaran ang mga fixed coupon sa mga regular na pagitan, binayaran ang prinsipal sa panahon ng maturity, nominal na taunang ani na pinagsama sa napiling dalas ng kupon, at walang naipon na interes, mga buwis, bayarin, default, mga feature ng tawag, inflation o reinvestment effect. Ang maturity ay dapat na isang buong bilang ng mga panahon ng kupon. Ang ani ay numerical at tinatayang; independyenteng kumpirmahin ang mga tuntunin ng bono at mga kumbensyon sa merkado.","resultSummary":"Tinantyang mga resulta ng bono","yieldToMaturity":"Yield hanggang maturity (nominal annual)","estimatedPrice":"Tinantyang presyo","couponPayment":"Pagbabayad ng kupon bawat panahon","currentYield":"Kasalukuyang ani","totalCoupons":"Kabuuang nakaiskedyul na mga kupon","premiumDiscount":"Premium / diskwento sa halaga ng mukha","periods":"Mga panahon ng kupon","chartTitle":"Tinantyang presyo–curve ng ani","chartDescription":"Bond ay karaniwang gumagalaw sa kabaligtaran na direksyon upang magbunga. Ginagamit ng curve ang inilagay na fixed coupon at mga pagpapalagay sa maturity.","chartYield":"Nominal na taunang ani (%)","chartPrice":"Tinatayang presyo"},"messages":{"calculated":"Bono kalkulado.","exampleLoaded":"Halimbawang na-load: 5% na kupon, 5 taon, taunang pagbabayad, presyo sa par.","checkInputs":"Suriin ang mga halaga ng bono at subukang muli.","copied":".","copyUnavailable":"Copy ay hindi magagamit sa browser na ito.","invalidPeriods":"Pumili ng maturity na naglalaman ng buong bilang ng mga panahon ng kupon (hanggang sa 1,200).","yieldOutOfRange":"Ang presyo sa merkado ay nasa labas ng sinusuportahang numerical yield range."},"additionalFaqs":[{"question":"Ano ang yield ng 5% coupon bond kapag ito ay nakapresyo sa par?","answer":"Sa ilalim ng mga pagpapalagay ng calculator, ang isang bono na may 5% taunang rate ng kupon, isang presyo sa merkado na katumbas ng halaga ng mukha at mga regular na pagbabayad ng kupon ay may nominal na ani hanggang sa maturity na 5%."},{"question":"Bakit gumagalaw ang mga presyo at ani ng bono sa magkasalungat na direksyon?","answer":"Ang presyo ng bono ay ang kasalukuyang halaga ng naka-iskedyul na mga kupon at prinsipal nito. Ang mas mataas na ani ng diskwento ay nagpapababa sa kasalukuyang halaga; ang mas mababang ani ay nagpapataas nito."},{"question":"Ang kasalukuyang ani ba ay pareho sa ani hanggang sa kapanahunan?","answer":"Hindi. Ang kasalukuyang ani ay ang taunang kupon na hinati sa kasalukuyang presyo. Isinasaalang-alang din ng yield to maturity ang pagkakaiba ng presyo mula sa halaga ng mukha at ang natitirang oras, sa ilalim ng nakasaad na mga pagpapalagay ng cash-flow."},{"question":"Kasama ba sa pagtatantyang ito ang naipon na interes o mga buwis?","answer":"Hindi. Nagmomodelo ito ng regular na fixed coupon payment at principal repayment lamang. Hindi nito kinakalkula ang malinis-versus-marumi na presyo, naipon na interes, mga buwis, bayarin, panganib sa kredito o opsyonal na pagtubos."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"ta":{"copyLanguage":"ta","name":"பத்திர கால்குலேட்டர்","title":"பத்திர கால்குலேட்டர் இலவசம் | UsefulVerse","description":"கூப்பன், முக மதிப்பு மற்றும் காலத்தின் முதிர்வுக்கான பத்திர விலை அல்லது விளைச்சலை மதிப்பிடவும். இலவச, வரம்பற்ற கணக்கீடுகள் உங்கள் உலாவியில் இயங்கும்.","intro":"அதன் விளைச்சலில் இருந்து நிலையான-விகிதப் பத்திர விலையை மதிப்பிடவும் அல்லது மேற்கோள் காட்டப்பட்ட சந்தை விலையிலிருந்து முதிர்வுக்கான தோராயமான விளைச்சலைத் தீர்க்கவும். முடிவைப் பயன்படுத்துவதற்கு முன் அனுமானங்கள் மற்றும் விலை-விளைச்சல் வளைவை மதிப்பாய்வு செய்யவும்.","howQuestion":"முதிர்வுக்கான பத்திர விலை அல்லது விளைச்சலை எவ்வாறு கணக்கிடுவது?","howAnswer":"முக மதிப்பு, வருடாந்திர கூப்பன் வீதம், முதிர்வுக்கான ஆண்டுகள் மற்றும் கூப்பன் அதிர்வெண் ஆகியவற்றை உள்ளிடவும். திட்டமிடப்பட்ட கூப்பன் மற்றும் அசல் கொடுப்பனவுகளைத் தள்ளுபடி செய்ய விளைச்சலில் இருந்து விலையைத் தேர்வு செய்யவும் அல்லது சந்தை விலையுடன் பொருந்தக்கூடிய பெயரளவு வருடாந்திர மகசூலை எண்ணியல் ரீதியாகத் தீர்க்க விளைச்சலில் இருந்து விலையைத் தேர்வு செய்யவும்.","privacyQuestion":"எனது பத்திர உள்ளீடுகள் பதிவேற்றப்பட்டதா?","privacyAnswer":"எண். கணக்கீடு இந்த உலாவியில் இயங்குகிறது. இந்த கருவி மூலம் உள்ளீடுகள் பதிவேற்றம் செய்யப்படவில்லை அல்லது சேமிக்கப்படவில்லை.","howTo":["விளைச்சலில் இருந்து விலையை மதிப்பிட வேண்டுமா அல்லது சந்தை விலையிலிருந்து விளைச்சலைத் தீர்க்க வேண்டுமா என்பதைத் தேர்வுசெய்யவும்.","முக மதிப்பு, வருடாந்திர கூப்பன் விகிதம், முதிர்வு மற்றும் கூப்பன் அதிர்வெண் ஆகியவற்றை உள்ளிடவும்.","காட்டப்படும் அனுமானங்கள் மற்றும் வளைவுடன் முடிவைக் கணக்கிட்டு ஒப்பிடவும்."],"example":{"label":"இணை","values":[]},"actions":{"calculate":"பத்திர மதிப்பைக் கணக்கிடுக","example":"லோட் பார்-பாண்ட் உதாரணம்","reset":"Reset","copy":"முடிவுகளை நகலெடு","result":"பத்திர மதிப்பீடு"},"fields":{"mode":"கணக்கீட்டு முறை","priceMode":"ஒரு விளைச்சலில் இருந்து","yieldMode":"சந்தை விலை","faceValue":"முகம் (பார்) மதிப்பு","couponPercent":"ஆண்டு கூப்பன் வீதம் (%)","years":"வருடங்கள் முதிர்வு","frequency":"வருடத்திற்கு","annual":"ஆண்டு (1)","semiannual":"அரையாண்டு (2)","quarterly":"காலாண்டு (4)","monthly":"மாதாந்திர (12)","yieldPercent":"பெயரளவு வருடாந்திர மகசூல் (%)","marketPrice":"சந்தை விலை","accuracyNote":"கல்வி மதிப்பீடு மட்டுமே, முதலீட்டு ஆலோசனை அல்ல. சீரான இடைவெளியில் செலுத்தப்படும் நிலையான கூப்பன்கள், முதிர்ச்சியின் போது அசல் திருப்பிச் செலுத்தப்படும், தேர்ந்தெடுக்கப்பட்ட கூப்பன் அதிர்வெண்ணில் பெயரளவிலான வருடாந்திர மகசூல் கூட்டும், மற்றும் திரட்டப்பட்ட வட்டி, வரிகள், கட்டணங்கள், இயல்புநிலை, அழைப்பு அம்சங்கள், பணவீக்கம் அல்லது மறு முதலீட்டு விளைவுகள் எதுவும் இல்லை. முதிர்வு கூப்பன் காலங்களின் முழு எண்ணிக்கையாக இருக்க வேண்டும். மகசூல் எண் மற்றும் தோராயமானது; பத்திர விதிமுறைகள் மற்றும் சந்தை மரபுகளை சுயாதீனமாக உறுதிப்படுத்தவும்.","resultSummary":"மதிப்பிடப்பட்ட பத்திர முடிவுகள்","yieldToMaturity":"முதிர்வுக்கான மகசூல் (பெயரளவு ஆண்டு)","estimatedPrice":"மதிப்பிடப்பட்ட விலை","couponPayment":"காலத்திற்கு","currentYield":"தற்போதைய மகசூல்","totalCoupons":"மொத்த திட்டமிடப்பட்ட கூப்பன்கள்","premiumDiscount":"பிரீமியம் / முக மதிப்புக்கு தள்ளுபடி","periods":"கூப்பன் காலங்கள்","chartTitle":"மதிப்பிடப்பட்ட விலை-விளைச்சல் வளைவு","chartDescription":"பத்திரத்தின் விலை பொதுவாக விளைச்சலுக்கு எதிர் திசையில் நகரும். வளைவு உள்ளிடப்பட்ட நிலையான கூப்பன் மற்றும் முதிர்வு அனுமானங்களைப் பயன்படுத்துகிறது.","chartYield":"பெயரளவு வருடாந்திர மகசூல் (%)","chartPrice":"மதிப்பிடப்பட்ட விலை"},"messages":{"calculated":"பத்திர மதிப்பீடு கணக்கிடப்பட்டது.","exampleLoaded":"எடுத்துக்காட்டு ஏற்றப்பட்டது: 5% கூப்பன், 5 ஆண்டுகள், வருடாந்திர கொடுப்பனவுகள், இணையான விலை.","checkInputs":"பத்திர மதிப்புகளைச் சரிபார்த்து, மீண்டும் முயற்சிக்கவும்.","copied":"முடிவுகள் நகலெடுக்கப்பட்டன.","copyUnavailable":"நகல் இந்த உலாவியில் இல்லை.","invalidPeriods":"முழு எண்ணிக்கையிலான கூப்பன் காலங்கள் (1,200 வரை) உள்ள முதிர்ச்சியைத் தேர்ந்தெடுக்கவும்.","yieldOutOfRange":"சந்தை விலை ஆதரிக்கப்படும் எண் மகசூல் வரம்பிற்கு வெளியே உள்ளது."},"additionalFaqs":[{"question":"5% கூப்பன் பத்திரத்திற்கு இணையான விலையில் என்ன லாபம் கிடைக்கும்?","answer":"கால்குலேட்டர் அனுமானங்களின் கீழ், 5% வருடாந்திர கூப்பன் வீதம் கொண்ட ஒரு பத்திரம், முக மதிப்புக்கு சமமான சந்தை விலை மற்றும் வழக்கமான கூப்பன் கொடுப்பனவுகள் 5% முதிர்வுக்கான பெயரளவு மகசூலைக் கொண்டிருக்கும்."},{"question":"ஏன் பத்திர விலைகள் மற்றும் விளைச்சல்கள் எதிர் திசைகளில் நகர்கின்றன?","answer":"ஒரு பத்திர விலை என்பது அதன் திட்டமிடப்பட்ட கூப்பன்கள் மற்றும் அசல் ஆகியவற்றின் தற்போதைய மதிப்பாகும். அதிக தள்ளுபடி விளைச்சல் தற்போதைய மதிப்பைக் குறைக்கிறது; குறைந்த மகசூல் அதை அதிகரிக்கிறது."},{"question":"தற்போதைய மகசூல் முதிர்வுக்கான மகசூலுக்கு சமமா?","answer":"எண். தற்போதைய மகசூல் என்பது தற்போதைய விலையால் வகுக்கப்படும் வருடாந்திர கூப்பன் ஆகும். முதிர்வுக்கான மகசூல் முக மதிப்பில் இருந்து விலை வேறுபாட்டையும், கூறப்பட்ட பணப்புழக்க அனுமானங்களின் கீழ் மீதமுள்ள நேரத்தையும் கணக்கிடுகிறது."},{"question":"இந்த மதிப்பீட்டில் திரட்டப்பட்ட வட்டி அல்லது வரிகள் உள்ளதா?","answer":"எண். இது வழக்கமான நிலையான கூப்பன் கொடுப்பனவுகள் மற்றும் அசல் திருப்பிச் செலுத்துதலை மட்டும் மாதிரியாகக் கொண்டுள்ளது. இது சுத்தமான மற்றும் அழுக்கு விலை, திரட்டப்பட்ட வட்டி, வரிகள், கட்டணங்கள், கடன் ஆபத்து அல்லது விருப்பமான மீட்பு ஆகியவற்றைக் கணக்கிடாது."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"fa":{"copyLanguage":"fa","name":"Bond Calculator","title":"Bond Calculator رایگان | UsefulVerse","description":"قیمت اوراق یا بازده تا سررسید را از کوپن، ارزش اسمی و مدت تخمین بزنید. محاسبات رایگان و نامحدود به صورت محلی در مرورگر شما اجرا می شود.","intro":"قیمت اوراق با نرخ ثابت را از بازده آن تخمین بزنید، یا بازده تقریبی تا سررسید را از قیمت بازار مظنه حل کنید. پیش از استفاده از نتیجه، مفروضات و منحنی قیمت-بازده را بررسی کنید.","howQuestion":"چگونه می توانم قیمت اوراق یا بازده تا سررسید را محاسبه کنم؟","howAnswer":"ارزش اسمی، نرخ کوپن سالانه، سالهای تا سررسید و فرکانس کوپن را وارد کنید. قیمت از بازده را برای تخفیف کوپن برنامه ریزی شده و پرداخت های اصلی انتخاب کنید، یا بازده از قیمت را برای حل عددی بازده اسمی سالانه که با قیمت بازار مطابقت دارد، انتخاب کنید.","privacyQuestion":"آیا ورودی های اوراق قرضه من آپلود شده است؟","privacyAnswer":"نه. محاسبه در این مرورگر انجام می شود. ورودی ها توسط این ابزار آپلود یا ذخیره نمی شوند.","howTo":["انتخاب کنید که آیا قیمت را از بازده تخمین بزنید یا بازده را از قیمت بازار حل کنید.","ارزش اسمی، نرخ کوپن سالانه، سررسید و فرکانس کوپن را وارد کنید.","نتیجه را با مفروضات و منحنی نمایش داده شده محاسبه و مقایسه کنید."],"example":{"label":"یک اوراق قرضه کوپنی 5% با قیمت برابر","values":[]},"actions":{"calculate":"محاسبه ارزش اوراق قرضه","example":"بارگذاری par-bond مثال","reset":"بازنشانی","copy":"کپی نتایج","result":"برآورد اوراق قرضه"},"fields":{"mode":"Calculation mode","priceMode":"قیمت از عملکرد","yieldMode":"بازده از قیمت بازار","faceValue":"مقدار چهره (همتراز)","couponPercent":"نرخ کوپن سالانه (%)","years":"سالهای تا سررسید","frequency":"پرداخت کوپن در سال","annual":"سالانه (1)","semiannual":"شش ماهه (2)","quarterly":"(4)","monthly":"(12)","yieldPercent":"بازده اسمی سالانه (%)","marketPrice":"قیمت بازار","accuracyNote":"فقط برآورد آموزشی، نه توصیه سرمایه گذاری. کوپن‌های ثابت پرداخت شده در فواصل منظم، اصل بازپرداخت در سررسید، بازده اسمی سالانه ترکیب شده در فرکانس کوپن انتخابی، و بدون بهره انباشته، مالیات، کارمزد، پیش‌فرض، ویژگی‌های تماس، تورم یا اثرات سرمایه‌گذاری مجدد را فرض می‌کند. سررسید باید تعداد کامل دوره های کوپن باشد. بازده عددی و تقریبی است. شرایط اوراق قرضه و قراردادهای بازار را به طور مستقل تأیید کنید.","resultSummary":"نتایج تخمینی اوراق قرضه","yieldToMaturity":"بازده تا سررسید (اسمی سالانه)","estimatedPrice":"قیمت تخمینی","couponPayment":"پرداخت کوپن در هر دوره","currentYield":"بازده فعلی","totalCoupons":"مجموع کوپن های برنامه ریزی شده","premiumDiscount":"حق بیمه / تخفیف به ارزش اسمی","periods":"Coupon periods","chartTitle":"منحنی قیمت-بازده تخمینی","chartDescription":"معمولاً در جهت مخالف حرکت می کند تا بازدهی داشته باشد. منحنی از کوپن ثابت وارد شده و مفروضات سررسید استفاده می کند.","chartYield":"بازده اسمی سالانه (%)","chartPrice":"قیمت تخمینی"},"messages":{"calculated":"محاسبه شد.","exampleLoaded":"مثال بارگذاری شده: کوپن 5%، 5 سال، پرداخت سالانه، قیمت برابر.","checkInputs":"مقادیر پیوند را بررسی کرده و دوباره امتحان کنید.","copied":"کپی شد.","copyUnavailable":"در این مرورگر در دسترس نیست.","invalidPeriods":"سررسیدی را انتخاب کنید که شامل تعداد کامل دوره های کوپن باشد (تا 1200).","yieldOutOfRange":"قیمت بازار خارج از محدوده بازده عددی پشتیبانی شده است."},"additionalFaqs":[{"question":"یک اوراق کوپنی 5 درصدی چه بازدهی دارد وقتی که قیمت آن برابر باشد؟","answer":"بر اساس مفروضات ماشین حساب، اوراق قرضه با نرخ کوپن سالانه 5%، قیمت بازار برابر با ارزش اسمی و پرداخت های کوپن معمولی دارای بازده اسمی تا سررسید 5% است."},{"question":"چرا قیمت و بازده اوراق قرضه در جهت مخالف حرکت می کنند؟","answer":"قیمت اوراق قرضه ارزش فعلی کوپن و اصل آن برنامه ریزی شده است. بازده تخفیف بالاتر، ارزش فعلی را کاهش می دهد. بازده کمتر آن را افزایش می دهد."},{"question":"آیا بازده فعلی همان بازده تا سررسید است؟","answer":"شماره. بازده فعلی کوپن سالانه تقسیم بر قیمت فعلی است. بازده تا سررسید نیز بر اساس مفروضات جریان نقدی بیان شده، تفاوت قیمت از ارزش اسمی و زمان باقیمانده را محاسبه می کند."},{"question":"آیا این برآورد شامل بهره یا مالیات تعلق گرفته می شود؟","answer":"نه. این مدل پرداخت کوپن ثابت معمولی و بازپرداخت اصل است. قیمت تمیز در مقابل کثیف، بهره انباشته، مالیات، کارمزد، ریسک اعتباری یا بازخرید اختیاری را محاسبه نمی کند."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"am":{"copyLanguage":"am","name":"ቦንድ ማስያ","title":"ቦንድ ማስያ ነፃ | UsefulVerse","description":"ግምት የማስያዣ ዋጋ ወይም ከኩፖን፣ የፊት እሴት እና ጊዜ ወደ ብስለት መድረስ። ነፃ ፣ ያልተገደበ ስሌቶች በአሳሽዎ ውስጥ በአገር ውስጥ ይሰራሉ።","intro":"የቋሚ-ተመን ማስያዣ ዋጋን ከምርቱ ይገምቱ ወይም ከተጠቀሰው የገበያ ዋጋ እስከ ብስለት ድረስ ያለውን ግምታዊ ምርት ይፍቱ። ውጤቱን ከመጠቀምዎ በፊት ግምቶችን እና የዋጋ-የምርት ኩርባውን ይገምግሙ።","howQuestion":"የማስያዣ ዋጋን እንዴት ማስላት ወይም ወደ ብስለት ማምጣት እችላለሁ?","howAnswer":"የፊት እሴቱን፣ አመታዊ የኩፖን መጠንን፣ አመታትን እስከ ብስለት እና የኩፖን ድግግሞሽ ያስገቡ። የታቀዱትን ኩፖን እና ዋና ክፍያዎችን ለመቀነስ ከዋጋ-ከምርት ይምረጡ ወይም ከገበያ ዋጋ ጋር የሚዛመደውን አመታዊ ምርት በቁጥር ለመፍታት ከዋጋ-ከዋጋን ይምረጡ።","privacyQuestion":"የእኔ የማስያዣ ግብዓቶች ተሰቅለዋል?","privacyAnswer":"ቁ. ስሌቱ በዚህ አሳሽ ውስጥ ይሰራል። ግብዓቶች በዚህ መሳሪያ አልተሰቀሉም ወይም አልተቀመጡም።","howTo":["ከምርት ዋጋ ለመገመት ወይም ከገበያ ዋጋ ምርትን ለመፍታት ይምረጡ።","የፊት እሴት፣ ዓመታዊ የኩፖን መጠን፣ ብስለት እና የኩፖን ድግግሞሽ ያስገቡ።","ውጤቱን ከሚታየው ግምቶች እና ከርቭ ጋር አስላ እና አወዳድር።"],"example":{"label":"በ","values":[]},"actions":{"calculate":"የማስያዣ ዋጋ","example":"የፓር-ቦንድ ምሳሌ","reset":"Reset","copy":"ውጤቶች","result":"ቦንድ ግምት"},"fields":{"mode":"ስሌት ሁነታ","priceMode":"ዋጋ ከምርት","yieldMode":"ከገበያ ዋጋ","faceValue":"ፊት (የተነፃፃሪ) እሴት","couponPercent":"ዓመታዊ የኩፖን መጠን (%)","years":"ዓመታት እስከ ብስለት","frequency":"ኩፖን ክፍያዎች በዓመት","annual":"ዓመታዊ (1)","semiannual":"ግማሽ ዓመታዊ (2)","quarterly":"በየሩብ (4)","monthly":"ወርሃዊ (12)","yieldPercent":"አመታዊ ምርት (%)","marketPrice":"የገበያ ዋጋ","accuracyNote":"ትምህርታዊ ግምት ብቻ እንጂ የኢንቨስትመንት ምክር አይደለም። ቋሚ ኩፖኖች በየጊዜው የሚከፈሉ፣ ዋና በብስለት የሚከፈሉ፣ በተመረጠው የኩፖን ፍሪኩዌንሲ የተጠቃለለ አመታዊ ምርት፣ እና ምንም የተጠራቀመ ወለድ፣ ግብሮች፣ ክፍያዎች፣ ነባሪ፣ የጥሪ ባህሪያት፣ የዋጋ ግሽበት ወይም የመልሶ ኢንቨስትመንት ውጤቶች እንደሌለ ይገመታል። ብስለት ሙሉ የኩፖን ጊዜዎች ብዛት መሆን አለበት። ምርት ቁጥር እና ግምታዊ ነው; የቦንድ ውሎችን እና የገበያ ስምምነቶችን በተናጥል ያረጋግጡ።","resultSummary":"ግምታዊ የማስያዣ ውጤቶች","yieldToMaturity":"ለብስለት (ስመ አመታዊ)","estimatedPrice":"የሚገመተው ዋጋ","couponPayment":"የኩፖን ክፍያ በየወቅቱ","currentYield":"የአሁኑ ምርት","totalCoupons":"ጠቅላላ የታቀዱ ኩፖኖች","premiumDiscount":"ፕሪሚየም/የዋጋ ቅናሽ","periods":"ኩፖን ወቅቶች","chartTitle":"የሚገመተው ዋጋ–የሚያፈራ ኩርባ","chartDescription":"የማስያዣ ዋጋ በአጠቃላይ ለማምረት በተቃራኒ አቅጣጫ ይንቀሳቀሳል። ኩርባው የገባውን ቋሚ ኩፖን እና የብስለት ግምቶችን ይጠቀማል።","chartYield":"አመታዊ ምርት (%)","chartPrice":"የተገመተው ዋጋ"},"messages":{"calculated":"ቦንድ ግምት ይሰላል።","exampleLoaded":"ምሳሌ የተጫነ፡ 5% ኩፖን፣ 5 ዓመታት፣ ዓመታዊ ክፍያዎች፣ ዋጋ በአን.","checkInputs":"የማስያዣ እሴቶቹን ይፈትሹ እና እንደገና ይሞክሩ።","copied":"ውጤቶች ተቀድተዋል።","copyUnavailable":"ቅጂ በዚህ አሳሽ ውስጥ አይገኝም።","invalidPeriods":"ሙሉ የኩፖን ጊዜዎችን (እስከ 1,200) የያዘ ብስለት ይምረጡ።","yieldOutOfRange":"የገበያ ዋጋ ከሚደገፈው የቁጥር ምርት ክልል ውጪ ነው።"},"additionalFaqs":[{"question":"5% የኩፖን ማስያዣ ተመጣጣኝ ዋጋ ሲኖረው ምን ምርት አለው?","answer":"በካልኩሌተሩ ግምቶች መሠረት፣ 5% አመታዊ የኩፖን መጠን ያለው ማስያዣ፣ ከዋጋ ዋጋ ጋር እኩል የሆነ የገበያ ዋጋ እና መደበኛ የኩፖን ክፍያዎች 5% የሚሆን የስም ምርት አለው።"},{"question":"ለምን የማስያዣ ዋጋዎች እና ምርቶች በተቃራኒ አቅጣጫዎች ይንቀሳቀሳሉ?","answer":"የማስያዣ ዋጋ በአሁኑ ጊዜ የታቀዱ ኩፖኖች እና ዋና ዋጋ ነው። ከፍተኛ ቅናሽ ያለው ምርት አሁን ያለውን ዋጋ ይቀንሳል; ዝቅተኛ ምርት ይጨምራል."},{"question":"የአሁኑ ምርት ለብስለት ከሚሰጠው ምርት ጋር አንድ ነው?","answer":"ቁጥር የአሁኑ ምርት አመታዊ ኩፖን አሁን ባለው ዋጋ የተከፈለ ነው። ለብስለት መሰጠት በተጠቀሱት የገንዘብ-ፍሰቶች ግምቶች መሠረት የዋጋ ልዩነትን ከመልክ እሴት እና የቀረውን ጊዜ ይይዛል።"},{"question":"ይህ ግምት የተጠራቀመ ወለድ ወይም ታክስ ያካትታል?","answer":"ቁ. መደበኛ ቋሚ የኩፖን ክፍያዎችን እና ዋና ክፍያን ብቻ ሞዴል ያደርጋል። ንፁህ እና ቆሻሻ ዋጋን፣ የተጠራቀመ ወለድን፣ ታክስን፣ ክፍያን፣ የክሬዲት አደጋን ወይም የአማራጭ መቤዠትን አይሰላም።"}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"},"gu":{"copyLanguage":"gu","name":"બોન્ડ કેલ્ક્યુલેટર","title":"બોન્ડ કેલ્ક્યુલેટર મફત | UsefulVerse","description":"કુપન, ફેસ વેલ્યુ અને ટર્મ પરથી બોન્ડની કિંમત અથવા પાકતી મુદતની ઉપજનો અંદાજ કાઢો. મફત, અમર્યાદિત ગણતરીઓ તમારા બ્રાઉઝરમાં સ્થાનિક રીતે ચાલે છે.","intro":"તેની ઉપજમાંથી ફિક્સ્ડ-રેટ બોન્ડની કિંમતનો અંદાજ કાઢો, અથવા ટાંકેલા બજાર ભાવથી પરિપક્વતા સુધીની અંદાજિત ઉપજને ઉકેલો. પરિણામનો ઉપયોગ કરતા પહેલા ધારણાઓ અને કિંમત-ઉપજ વળાંકની સમીક્ષા કરો.","howQuestion":"હું બોન્ડની કિંમત અથવા પાકતી મુદતની ઉપજની ગણતરી કેવી રીતે કરી શકું?","howAnswer":"ફેસ વેલ્યુ, વાર્ષિક કૂપન રેટ, પરિપક્વતાના વર્ષો અને કૂપન આવર્તન દાખલ કરો. સુનિશ્ચિત કૂપન અને મુખ્ય ચૂકવણીઓને ડિસ્કાઉન્ટ કરવા માટે કિંમત-માંથી-ઉપજ પસંદ કરો અથવા બજાર કિંમત સાથે મેળ ખાતી નજીવી વાર્ષિક ઉપજને સંખ્યાત્મક રીતે ઉકેલવા માટે કિંમત-માંથી-કિંમત પસંદ કરો.","privacyQuestion":"શું મારા બોન્ડ ઇનપુટ્સ અપલોડ કરવામાં આવ્યા છે?","privacyAnswer":"નંબર. ગણતરી આ બ્રાઉઝરમાં ચાલે છે. આ સાધન દ્વારા ઇનપુટ્સ અપલોડ અથવા સાચવવામાં આવતા નથી.","howTo":["ઉપજ પરથી કિંમતનો અંદાજ કાઢવો કે બજાર કિંમત પરથી ઉપજ ઉકેલવી કે કેમ તે પસંદ કરો.","ફેસ વેલ્યુ, વાર્ષિક કૂપન રેટ, મેચ્યોરિટી અને કૂપન ફ્રીક્વન્સી દાખલ કરો.","પ્રદર્શિત ધારણાઓ અને વળાંક સાથે પરિણામની ગણતરી કરો અને તેની તુલના કરો."],"example":{"label":"Load a 5% coupon bond priced at par","values":[]},"actions":{"calculate":"બોન્ડ મૂલ્યની ગણતરી કરો","example":"લોડ પાર-બોન્ડ ઉદાહરણ","reset":"Reset","copy":"પરિણામોની નકલ કરો","result":"બોન્ડ અંદાજ"},"fields":{"mode":"ગણતરી મોડ","priceMode":"ઉપજ","yieldMode":"બજાર કિંમતથી ઉપજ","faceValue":"ફેસ (પાર) મૂલ્ય","couponPercent":"વાર્ષિક કૂપન દર (%)","years":"પરિપક્વતાના વર્ષો","frequency":"પ્રતિ વર્ષ કૂપન ચુકવણી","annual":"વાર્ષિક (1)","semiannual":"અર્ધવાર્ષિક (2)","quarterly":"ત્રિમાસિક (4)","monthly":"માસિક (12)","yieldPercent":"નજીવી વાર્ષિક ઉપજ (%)","marketPrice":"બજાર કિંમત","accuracyNote":"માત્ર શૈક્ષણિક અંદાજ, રોકાણ સલાહ નહીં. નિયમિત અંતરાલો પર ચૂકવેલ નિશ્ચિત કૂપન, પાકતી મુદત પર ચૂકવેલ મુખ્ય, પસંદ કરેલ કૂપન આવર્તન પર ચક્રવૃદ્ધિ નજીવી વાર્ષિક ઉપજ અને કોઈ ઉપાર્જિત વ્યાજ, કર, ફી, ડિફોલ્ટ, કોલ સુવિધાઓ, ફુગાવો અથવા પુનઃરોકાણ અસરો ધારે છે. પરિપક્વતા કૂપન સમયગાળાની સંપૂર્ણ સંખ્યા હોવી આવશ્યક છે. ઉપજ સંખ્યાત્મક અને અંદાજિત છે; સ્વતંત્ર રીતે બોન્ડની શરતો અને બજાર સંમેલનોની પુષ્ટિ કરો.","resultSummary":"અંદાજિત બોન્ડ પરિણામો","yieldToMaturity":"પરિપક્વતા સુધી ઉપજ (નજીવી વાર્ષિક)","estimatedPrice":"અંદાજિત કિંમત","couponPayment":"સમયગાળા દીઠ કૂપન ચુકવણી","currentYield":"વર્તમાન ઉપજ","totalCoupons":"કુલ સુનિશ્ચિત કૂપન્સ","premiumDiscount":"પ્રીમિયમ / ફેસ વેલ્યુ માટે ડિસ્કાઉન્ટ","periods":"કૂપન સમયગાળા","chartTitle":"અંદાજિત કિંમત-ઉપજ વળાંક","chartDescription":"બોન્ડની કિંમત સામાન્ય રીતે ઉપજ માટે વિરુદ્ધ દિશામાં જાય છે. વળાંક દાખલ કરેલ નિશ્ચિત કૂપન અને પરિપક્વતા ધારણાઓનો ઉપયોગ કરે છે.","chartYield":"નજીવી વાર્ષિક ઉપજ (%)","chartPrice":"અંદાજિત કિંમત"},"messages":{"calculated":"બોન્ડ અંદાજની ગણતરી.","exampleLoaded":"ઉદાહરણ લોડ કર્યું: 5% કૂપન, 5 વર્ષ, વાર્ષિક ચૂકવણીઓ, સમાન કિંમત.","checkInputs":"બોન્ડ મૂલ્યો તપાસો અને ફરી પ્રયાસ કરો.","copied":"પરિણામો કૉપિ કર્યા.","copyUnavailable":"કૉપિ આ બ્રાઉઝરમાં અનુપલબ્ધ છે.","invalidPeriods":"એક પરિપક્વતા પસંદ કરો જેમાં કૂપન સમયગાળાની સંપૂર્ણ સંખ્યા (1,200 સુધી) હોય.","yieldOutOfRange":"બજાર કિંમત સમર્થિત સંખ્યાત્મક ઉપજ શ્રેણીની બહાર છે."},"additionalFaqs":[{"question":"જ્યારે 5% કૂપન બોન્ડની કિંમત સમાન હોય ત્યારે તેની શું ઉપજ હોય છે?","answer":"કેલ્ક્યુલેટર ધારણાઓ હેઠળ, 5% વાર્ષિક કૂપન રેટ સાથેના બોન્ડ, ફેસ વેલ્યુની સમાન બજાર કિંમત અને નિયમિત કૂપન ચુકવણીઓ 5% ની પરિપક્વતા માટે નજીવી ઉપજ ધરાવે છે."},{"question":"બોન્ડની કિંમતો અને ઉપજ શા માટે વિરુદ્ધ દિશામાં જાય છે?","answer":"એ બોન્ડની કિંમત તેના સુનિશ્ચિત કૂપન અને પ્રિન્સિપલનું વર્તમાન મૂલ્ય છે. ઉચ્ચ ડિસ્કાઉન્ટ ઉપજ તે વર્તમાન મૂલ્યને ઘટાડે છે; ઓછી ઉપજ તેને વધારે છે."},{"question":"શું વર્તમાન ઉપજ પરિપક્વતાની ઉપજ સમાન છે?","answer":"નંબર. વર્તમાન ઉપજ એ વર્તમાન કિંમત દ્વારા વિભાજિત વાર્ષિક કૂપન છે. પરિપક્વતા સુધીની ઉપજ પણ દર્શાવેલ રોકડ-પ્રવાહ ધારણાઓ હેઠળ, ફેસ વેલ્યુ અને બાકીના સમયના ભાવ તફાવત માટે જવાબદાર છે."},{"question":"શું આ અંદાજમાં ઉપાર્જિત વ્યાજ અથવા કરનો સમાવેશ થાય છે?","answer":"નંબર. તે નિયમિત નિશ્ચિત કૂપન ચૂકવણી અને માત્ર મુખ્ય ચુકવણીનું મોડેલ કરે છે. તે સ્વચ્છ-વિરુદ્ધ-ગંદી કિંમત, ઉપાર્જિત વ્યાજ, કર, ફી, ક્રેડિટ જોખમ અથવા વૈકલ્પિક રિડેમ્પશનની ગણતરી કરતું નથી."}],"sources":[],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-11"}});
